var AR4_DATA=[{"m":1,"w":1,"t":"فهم المنطوق: ثريّ الحرب","pg":"ص 8-9","i":"🎧","B":[["الموضوع",["قصة رجل أثرى أثناء الحرب العالمية الثانية ثم فقد كل شيء","آفة اجتماعية: الجشع واستغلال الظروف وضياع الثروة"]],["شخصية البطل",["كان فقيرا متواضعا، ثم صار مغرورا متكبرا بثروته","بعد انتهاء الحرب عاد إلى حالته الأولى فقيرا ذليلا"]],["النمط السردي ومؤشراته",["الأفعال الماضية وتتابع الأحداث","غلبة ضمير الغائب","ظروف الزمان تنظم الأحداث"]],["النمط الوصفي ومؤشراته",["وصف منزل «سي شعبان» وحجرة الاستقبال ومقعدها","نعوت وأحوال وأفعال مضارعة، وماض متبوع بمضارع، وظروف مكان"]],["النمط الحواري ومؤشراته",["بروز ضميري المتكلم والمخاطَب","جمل قصيرة (سؤال وجواب) وتغير نبرة الصوت"]],["أسئلة الفهم",["ما الموضوع؟ ولماذا هو آفة اجتماعية؟","أعيد بناء صورة البطل، وأسقطها على الواقع، وأقترح علاج الآفة"]]],"K":"الخطاب المنطوق قصة يغلب عليها السرد، ويخدمه الوصف والحوار، وتتغير شخصية البطل بتغير الأحداث.","M":["أستمع إلى الخطاب كله ثم أحدد الموضوع والفكرة العامة","أميز النمط بمؤشراته: أفعال ماضية للسرد، نعوت للوصف، ضمائر المتكلم والمخاطب للحوار","أرتب الأحداث زمنيا وأربط كل حدث بتحول الشخصية","أجيب عن أسئلة الفهم بجمل كاملة وأستشهد بما سمعت"],"X":"القصة تحكي كيف جعلت الحرب رجلا فقيرا غنيا ثم أعادته فقيرا. السرد يروي ما حدث، والوصف يرينا المكان والشخص، والحوار يجعلنا نسمع الشخصيات. تعلمنا القصة أن المال السهل بلا أخلاق لا يدوم.","EX":[["أحدد نمط الجزء الذي يصف منزل «سي شعبان» وأذكر مؤشرين","النمط وصفي. من مؤشراته: كثرة النعوت والأحوال، واستعمال الأفعال المضارعة وظروف المكان."],["أحدد مؤشرات السرد في الجزء الأول (اندلاع الحرب العالمية)","الأفعال ماضية. الأحداث متتابعة زمنيا. ضمير الغائب هو الغالب. ظروف الزمان حاضرة. إذن النمط سردي."]]},{"m":1,"w":1,"t":"فهم المنطوق: بنية الخطاب السردي وعلاقة الأنماط","pg":"ص 14-15، 20-21","i":"🧩","B":[["مخطط السرد",["الوضعية الابتدائية: فقر وتواضع قبل الحرب","العنصر المحوِّل: اندلاع الحرب واستغلاله لظروفها","الوضعية النهائية: ضياع الثروة والعودة إلى الفقر"]],["تطور الشخصية",["محور الأحداث: بداية الحرب ثم نهايتها ثم استغلال المحتالين له ثم ضياع ثروته","محور الشخصية: فقير متأثر بفقره ثم متكبر انتهازي ثم ذليل"]],["السرد والوصف",["السرد نمط غالب يحكي الأحداث","الوصف يخدمه برسم المكان والشخصيات"]],["السرد والحوار",["الحوار يخدم السرد بين الشخصيات","يكشف مواقفها ويعلق على الأحداث"]],["هيكلة الخطاب",["تتناوب الأنماط: سرد، وصف، سرد، حوار، وهكذا","السرد هو الأساس والباقي في خدمته"]],["المغزى",["الجملة الدالة على المغزى هي التي تعلق على الحدث وتعمم العبرة","مثل لعن الحرب أو لعن ذئاب البشرية الجائعة الشهوات"]]],"K":"كلما تطورت الأحداث تطورت الشخصية معها، ويحتاج النمط السردي إلى الوصف والحوار ليخدماه.","M":["أرسم الجدول: وضعية ابتدائية، عنصر محوّل، وضعية نهائية","أربط كل حدث بتغير في الشخصية","أميز جملة المغزى: تعليق عام فيه عبرة وليس سردا لحدث","أسأل: لماذا جاء الوصف هنا؟ ولماذا جاء الحوار؟"],"X":"أي قصة تبدأ بحال، ثم يحدث شيء يغيّر كل شيء، ثم نصل إلى حال جديدة. الشخصية تتغير بسبب الأحداث. والوصف والحوار مثل مساعدين يجعلان القصة حية.","EX":[["أضع مخطط السرد لقصة «ثريّ الحرب»","الوضعية الابتدائية: رجل فقير متواضع. العنصر المحوّل: اندلاع الحرب واستغلاله الفرصة فيثرى. الوضعية النهائية: ينتهي بخسارة كل ثروته ويعود فقيرا ذليلا."],["أعلل: هل الأحداث مرتبة زمنيا؟","نعم. الفقر يسبق الحرب، ثم الثراء أثناءها، ثم الضياع بعدها. ولا يصح تغيير هذا الترتيب لأن كل حدث سبب للذي بعده."]]},{"m":1,"w":2,"t":"فهم المكتوب: ذكرى وندم","pg":"ص 10-11","i":"📖","B":[["بطاقة النص",["الكاتب: مالك بن نبي (1905-1973م)، مفكر جزائري","المصدر: رواية «حج الفقراء» ترجمة زيدان خويلف، دار الفكر، دمشق 2009"]],["الفكرة العامة",["الخمر آفة تهدم الأسرة: زوج سكّير يفقد زوجته","غضبه في لحظة طيش ينتهي بالطلاق والندم"]],["أحداث النص",["إبراهيم يستعيد آخر مشهد من حياته الزوجية","زهرة تجلس حزينة وتأنس بعصفور في قفص","يغضب الزوج لإهمالها له فيرمي القفص فيموت العصفور","تهجر زهرة البيت ولا يراها إلا عند القاضي"]],["المفردات",["عربدته: طيشه","عضال: مزمن لا يُشفى","الحانة: مكان شرب الخمر","كروان: طائر حسن الصوت","استشاط: اشتعل غضبا"]],["النمط والمؤشرات",["النمط الغالب سردي: أفعال ماضية وتتابع أحداث وضمير الغائب","نمط وصفي مساند: نعوت تصف الجو والحزن وحال زهرة"]],["القيم والانسجام",["التحذير من الخمر والتهور","الانسجام: روابط مثل الفاء وحيث وغير أنها تحفظ تسلسل المعنى","العنوان منسجم: تذكّر وحسرة على ما ضاع"]]],"K":"نص قصصي يبين كيف يدمر السكر والغضب البيت، فيتحول الحدث الصغير إلى فراق يعقبه الندم.","M":["أحدد الشخصيات والمكان والزمان","أرتب الأحداث وأبحث عن الحدث المباشر للنهاية","أستخرج مؤشرات النمطين السردي والوصفي","أفرق بين فقرة متسقة وأخرى ناقصة الروابط"],"X":"في هذه القصة رجل يشرب الخمر فيسيء إلى زوجته. تجد زهرة سلواها في عصفور صغير. وفي لحظة غضب يرمي الزوج قفص العصفور فيموت، وتغادر زهرة البيت نهائيا. يتذكر الرجل ذلك لاحقا بندم كبير.","EX":[["ما السبب المباشر لنهاية العلاقة؟ هل هو معقول؟","السبب المباشر: غضب إبراهيم لانشغال زهرة بالعصفور عنه فألقى القفص فمات العصفور. السبب غير معقول وحده، فهو مجرد شرارة، والأصل هو أثر الخمر وسوء المعاملة."],["أعطي مؤشرين للنمط الوصفي من النص","كثرة النعوت مثل «حزن» و«عضال»، ووصف الجو الربيعي والقفص والكروان. هذا يرسم المكان والحالة النفسية."]]},{"m":1,"w":2,"t":"فهم المكتوب: الضحية والمحتال","pg":"ص 16-17","i":"🎭","B":[["بطاقة النص",["الكاتب: بديع الزمان الهمذاني (969-1007م)","فن المقامة: قصة قصيرة طريفة تعتني بالبديع، من مؤلفاته «المقامات»"]],["الفكرة العامة",["احتيال عيسى بن هشام على رجل ريفي ليأكل على حسابه","تنتهي الحيلة بوقوع الريفي في يد صاحب الشواء"]],["الأحداث",["عيسى يشتهي طعاما وليس معه مال، فيلقى رجلا ريفيا","يتظاهر بأنه يعرفه ويدّعي أنه أبو زيد، ويدعوه إلى الأكل","يأكلان شواء وحلوى، ثم يتسلل عيسى بحجة جلب الماء","يمسك الشواء بالريفي ليدفع الثمن فيضرب ويبكي"]],["المفردات",["الأزاذ: الطعام","سوادي: ريفي من قرى العراق","وافيت: قدمت","اللوزينج: حلوى من اللوز","القِحة: لئيم"]],["الأنماط",["سرد غالب يروي الحيلة والأحداث","حوار بين عيسى والريفي، ثم الشواء","وصف للشواء والطعام وحال الرجلين"]],["الاتساق",["الأداة «ثمّ» تربط الأحداث وتحدد ترتيبها الزمني","لا يمكن تغيير تعاقب الأحداث لأنه يمنح القصة بناء محكما"]]],"K":"مقامة طريفة عن محتال يستغل غفلة ريفي، وأداة «ثمّ» تضمن تسلسل الأحداث، والقصة متماسكة لا يُغيّر ترتيبها.","M":["أبحث عن الضحية والمحتال","أرتب الأحداث وأنتبه إلى حرف «ثمّ»","أميز الأنماط الثلاثة المتداخلة وأعطي لكل نمط مثالا","أفرق بين المعنى اللغوي للكلمة ومدلولها في السياق"],"X":"عيسى جائع وبلا مال، فيدعي أنه يعرف رجلا بسيطا ويأخذه إلى المطعم. يأكلان كثيرا، ثم يهرب عيسى ويترك الرجل ليدفع. الرجل ضحية، لكن طمعه في الأكل المجاني جعله يصدق الحيلة.","EX":[["من الضحية ومن المحتال؟","الضحية هو السوادي الريفي الغافل. المحتال هو عيسى بن هشام الذي ادعى معرفته. وعيسى لا يعرف أبا عبيد حقا."],["ما وظيفة «ثمّ» في بداية الفقرتين الثانية والثالثة؟","تربط بين الأحداث لفظيا. تدل على التتابع الزمني: الذهاب ثم الأكل ثم الهروب. بها تتسلسل أحداث القصة زمنيا."]]},{"m":1,"w":2,"t":"فهم المكتوب: سائل","pg":"ص 22-23","i":"🧓","B":[["بطاقة النص",["الشاعر: عبد الله صالح حسن البردوني (1929-1999م)، شاعر يمني","فقد بصره وهو صغير، ونظم في السياسة والاجتماع والإنسان"]],["الفكرة العامة",["قصيدة تصور شيخا أعمى فقيرا يتسول في الطريق","الأرض قاسية والناس لا يلتفتون إلى بؤسه"]],["صور الشيخ",["يمشي ببطء ويمد يده الخالية إلى كل عابر","جائع حائر لا يعرف بدايته ولا نهايته","لا يجني من مد يده إلا اليأس"]],["المفردات",["يدِبّ: يمشي ببطء","يجتدي: يتسول ويطلب العون","الضرير: الأعمى","الطوى: الجوع الشديد","يزجي: يسوق برفق"]],["النمط والصور",["النمط الوصفي غالب: أوصاف السائل وأوصاف الأرض","فيه سرد وحوار قصير: «هل في الأرض ظل لمسعد؟»","صور بيانية مثل التشبيه «كئيبا كأحلام الغريب»"]],["الاتساق والقيم",["الإحالة بالضمائر وبالروابط تجعل القصيدة متماسكة","حروف النفي الكثيرة تعكس اليأس والحرمان","الدعوة إلى التضامن وحفظ كرامة الفقير"]]],"K":"قصيدة وصفية إنسانية تدين قسوة الفقر والتسول، وتدعو إلى التضامن مع الفقراء.","M":["أستخرج صفات السائل وأصنفها: جسدية ونفسية واجتماعية","أحدد النمط بالقرائن","أبين دلالة حروف النفي في القصيدة","أقترح حلولا للفقر مع حفظ الكرامة"],"X":"الشاعر يرسم أمامنا شيخا أعمى فقيرا يسير ويمد يده، فلا يعطيه أحد. يظن أن الناس سيرحمونه فيخيب أمله. القصيدة تدعونا إلى الانتباه للفقراء والإحسان إليهم دون إذلالهم.","EX":[["أستخرج وصفين للسائل وأبين نوعهما","وصفان: حركته البطيئة «يدبّ»، وجسمه النحيل. الأول وصف حركي والثاني وصف جسدي، وهما يظهران الضعف والفاقة."],["أعلل هيمنة حروف النفي على القصيدة","النفي يعبر عن الحرمان واليأس: لا يدري، لم يجن. السائل لا يعرف مصيره ولا يجد من يعطيه، فالنفي انعكاس لحالته النفسية."]]},{"m":1,"w":3,"t":"الظاهرة اللغوية: عطف النسق","pg":"ص 12","i":"🔗","B":[["التعريف",["ربط اسم معطوف بمعطوف عليه تابع له في الإعراب","يكون الربط بأحد أحرف العطف"]],["النوع الأول",["يشرك المعطوف والمعطوف عليه في المعنى واللفظ","حروفه: الواو، الفاء، ثمّ، أو، أم، حتى"]],["النوع الثاني",["يشرك في اللفظ (الإعراب) فقط دون المعنى","حروفه: لا، بل، لكن"]],["مثال",["«جاء أحمد ثم خالد»: كلاهما جاء","«ما جاء أحمد بل خالد»: خالد وحده جاء"]],["الإعراب",["المعطوف يتبع المعطوف عليه رفعا أو نصبا أو جرا","أقول: معطوف على كذا مرفوع أو منصوب أو مجرور"]],["خطأ شائع",["الخلط بين حروف العطف والنعت أو البدل","نسيان أن «لا وبل ولكن» لا تشرك في المعنى"]]],"K":"عطف النسق نوعان: بالواو والفاء وثمّ وأو وأم وحتى يشرك في المعنى واللفظ، وبلا وبل ولكن يشرك في اللفظ فقط.","M":["أبحث عن حرف العطف ثم أحدد المعطوف عليه","أطابق إعراب المعطوف لإعراب المعطوف عليه","أنتبه: بعد «بل ولكن» يختلف المعنى ويتفق الإعراب","أتحقق: هل شاركه في الفعل أم لا؟"],"X":"حروف العطف تربط كلمتين فتأخذ الثانية إعراب الأولى. بعضها يجمع الكلمتين في المعنى مثل الواو، وبعضها يربط الإعراب فقط ويُخرج الكلمة الثانية من المعنى مثل «بل».","EX":[["أستخرج المعطوف والمعطوف عليه وأعرب المعطوف: «لم تسمع زوجها الذي ناداها مرتين أو ثلاثا»","المعطوف: ثلاثا. المعطوف عليه: مرتين. حرف العطف: أو. الإعراب: ثلاثا معطوف على مرتين منصوب وعلامة نصبه الفتحة الظاهرة."],["أعرب المعطوف: «لم يكن سلوك زوج زهرة سويا بل مضطربا»","حرف العطف: بل. المعطوف عليه: سويا. المعطوف: مضطربا. الإعراب: معطوف على سويا منصوب وعلامة نصبه الفتحة. العطف هنا في اللفظ فقط لأن المعنى تحول من السواء إلى الاضطراب."],["مثال من إنشائي: أعرب المعطوف في «حضر الأستاذ ثم التلاميذ»","التلاميذ معطوف على الأستاذ مرفوع وعلامة رفعه الضمة الظاهرة. «ثمّ» تفيد الترتيب مع المهلة، والمعنى مشترك."]]},{"m":1,"w":3,"t":"الظاهرة اللغوية: عطف البيان","pg":"ص 18","i":"🔎","B":[["التعريف",["اسم تابع جامد غالبا يوضح متبوعه","يوضح المعرفة ويخصص النكرة"]],["المطابقة",["يوافق متبوعه في الإعراب: رفعا أو نصبا أو جرا","يوافقه في النوع: تذكير أو تأنيث","يوافقه في العدد والتعريف والتنكير"]],["مثال",["«حدثنا الراوية عيسى بن هشام»","«عيسى بن هشام» يوضح الراوية"]],["نوعه",["توضيح إن كان المتبوع معرفة","تخصيص إن كان المتبوع نكرة"]],["الإعراب",["أقول: عطف بيان على كذا مرفوع أو منصوب أو مجرور","وأذكر العلامة الظاهرة أو المقدرة"]],["خطأ شائع",["إعرابه نعتا لأنه تابع، والنعت مشتق غالبا","الغفلة عن ضرورة المطابقة"]]],"K":"عطف البيان اسم تابع جامد غالبا يوضح متبوعه المعرفة أو يخصص النكرة، ويطابقه في الإعراب والنوع والعدد والتعريف والتنكير.","M":["أسأل: أي كلمة توضح ما قبلها؟","أتأكد أنها جامدة لا مشتقة وأنها تابعة بلا حرف","أعرب بالمطابقة مع المتبوع","أحدد النوع: توضيح أم تخصيص"],"X":"عندما نقول «الراوية» قد لا نعرف من هو، فنقول «عيسى بن هشام». هذه الكلمة الثانية هي عطف البيان لأنها توضح الأولى وتتبعها في الإعراب.","EX":[["أعرب عطف البيان في «حياك الله صديقنا أبا زيد»","أبا زيد عطف بيان على «صديقنا». نوعه توضيح لأن المتبوع معرفة. إعرابه: عطف بيان منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة."],["أعرب عطف البيان في «حدثنا الراوية عيسى بن هشام»","عيسى بن هشام عطف بيان على الراوية. نوعه توضيح. إعرابه: مرفوع وعلامة رفعه الضمة المقدرة على الألف للتعذر في «عيسى»، وهشام مضاف إليه."],["مثال من إنشائي: «جاء أخوك خالد»","خالد عطف بيان على «أخوك». نوعه توضيح. إعرابه: مرفوع وعلامة رفعه الضمة الظاهرة."]]},{"m":1,"w":3,"t":"الظاهرة اللغوية: البدل","pg":"ص 24","i":"🎯","B":[["التعريف",["تابع مقصود بالحكم بلا واسطة بينه وبين المبدل منه","يدل على المبدل منه ويفيد المقصود به"]],["بدل مطابق",["يساوي المبدل منه في المعنى (كل من كل)","من صوره: اسم معرف بأل بعد اسم إشارة"]],["بدل البعض من الكل",["البدل جزء من المبدل منه","مثل «نصفُه، معظمُه»"]],["بدل الاشتمال",["البدل صفة أو معنى يشتمل عليه المبدل منه","مثل «مرارته» بعد «اليأس»"]],["ما يلزم البدل",["ضمير يعود على المبدل منه في بدل البعض والاشتمال","يتبعه في الرفع والنصب والجر"]],["خطأ شائع",["الخلط بين البدل وعطف البيان","نسيان الضمير الرابط وتحديد نوع البدل"]]],"K":"البدل تابع مقصود بالحكم بلا واسطة، وهو ثلاثة أنواع: مطابق، وبعض من كل، واشتمال.","M":["أبحث عن الاسم المقصود بالحكم","أسأل: هل يساوي المبدل منه؟ أم جزء منه؟ أم صفة فيه؟","أضع الضمير الرابط في بدل البعض والاشتمال","أتبع إعراب المبدل منه"],"X":"البدل يأتي بعد كلمة ليكمل المقصود. إن كان يعني الشيء نفسه فهو مطابق، وإن كان جزءا منه فهو بعض من كل، وإن كان معنى فيه فهو اشتمال. لا نحتاج إلى حرف يربطه.","EX":[["أعرب البدل: «لم يجن إلا اليأس مرارتَه»","مرارتَه بدل اشتمال من اليأس. إعرابه: بدل منصوب وعلامة نصبه الفتحة الظاهرة، والهاء ضمير متصل في محل جر مضاف إليه."],["أعرب البدل: «غبار الأرض نصفُه آهات خائب»","نصفُه بدل بعض من كل من «غبار». إعرابه: بدل مرفوع وعلامة رفعه الضمة الظاهرة، والهاء في محل جر مضاف إليه."],["أعرب البدل: «أعجبني الأستاذُ شرحُه».","شرحُه بدل اشتمال من الأستاذ. إعرابه: بدل مرفوع وعلامة رفعه الضمة الظاهرة. والهاء ضمير متصل مبني في محل جر مضاف إليه وهو الرابط العائد على الأستاذ"]]},{"m":1,"w":4,"t":"الإنتاج الكتابي: أخطط لكتابة قصة","pg":"ص 13، 19","i":"✍️","B":[["اختيار النمط",["سرد فقط، أو سرد مع وصف، أو سرد مع حوار","أو سرد مع وصف وحوار، وأبرر اختياري"]],["اختيار الموضوع",["آفة اجتماعية: الغش، الكذب، الحسد، الرشوة، المخدرات...","أذكر سبب اختياري للموضوع"]],["جمع الموارد",["لا أكتب دون قراءة، فأختار مصادر قراءتي","المكتبة، الإنترنت، مجال ثقافي مثل التضامن والطبيعة"]],["خصائص القصة",["موضوع وفكرة تريد إيصالها","حدث رئيسي وأحداث جزئية متتابعة","بطل وشخصيات ثانوية تتطور بتطور الأحداث","لغة قصصية: سرد ووصف وحوار"]],["استثمار النص",["أرصد ما تحقق من الخصائص في النص وما لم يتحقق","مثال: نص عن مالك أرض طمع فمات (عن تولستوي)"]],["التخطيط",["أضع تخطيطا أوليا: وضعية ابتدائية، عنصر محوِّل، وضعية نهائية","أحدد الشخصيات وصفاتها قبل التحول وبعده"]]],"K":"أكتب القصة بعد أن أختار النمط والموضوع، وأجمع معارفي، وأتأكد من خصائصها، ثم أخطط لها.","M":["أختار فكرة واحدة واضحة تحمل رسالة أخلاقية","أضع الأحداث بتسلسل زمني منطقي","أجعل الشخصية تتغير بسبب الأحداث","أوازن بين السرد والوصف والحوار"],"X":"قبل أن أكتب قصتي أحدد الموضوع، ثم أقرأ لأتعلم، ثم أضع مخططا: كيف تبدأ؟ ما الذي يغير الأحداث؟ كيف تنتهي؟ وأحرص أن يكون لها بطل يتغير وحدث رئيسي ورسالة.","EX":[["أضع تخطيطا أوليا لقصة عن الغش","الوضعية الابتدائية: تلميذ يعتاد الغش. العنصر المحوِّل: يُكتشف أمره ويُحرم من الامتحان. الوضعية النهائية: يندم ويقرر الاجتهاد. الرسالة: الغش لا يبني مستقبلا."],["ما خصائص القصة التي تحققت في نص «الضحية والمحتال»؟","تحقق: موضوع (الاحتيال)، وحدث رئيسي متتابع، وشخصيات (عيسى والسوادي والشواء)، ولغة سرد ووصف وحوار. ولم تظهر بوضوح رسالة تصرح بها."]]},{"m":1,"w":4,"t":"الإنتاج الكتابي: أتدرب وأقيّم بالشبكة","pg":"ص 25","i":"✅","B":[["المشروع",["أناقش مشروعا مع زملائي ثم أنتجه","أقيمه بشبكة ضبط الإنتاج وأنشره باسم الفوج"]],["المحتوى",["نص قصصي في موضوع من الآفات الاجتماعية","يحمل رسالة اجتماعية أخلاقية"]],["بناء القصة",["بناء سردي بمؤشراته مع الوصف والحوار","أحداث مرتبة زمنيا ومنطقيا","شخصية تتأثر بالأحداث وتؤثر فيها"]],["المخطط",["وضعيات السرد الثلاث: ابتدائية، تحول، نهائية","نمط السرد والوصف والحوار بحجم متناسب"]],["اللغة",["سلامة التركيب النحوي","احترام الضوابط اللغوية وعلامات الوقف"]],["الشكل",["احترام معايير الكتابة والعرض","أجيب في الشبكة بـ«نعم» أو «لا» عن كل معيار"]]],"K":"أقيّم قصتي بشبكة معاييرها: النوع القصصي، الموضوع والرسالة، بناء السرد والوصف والحوار، تسلسل الأحداث، سلامة اللغة وحسن العرض.","M":["أقرأ نصي بعد الكتابة وأطبق الشبكة بصدق","أصحح ما كان جوابه «لا»","أتأكد من علامات الوقف وسلامة الجمل","أطلب رأي زميل قبل النشر"],"X":"بعد أن أكتب قصتي أستعمل جدولا فيه أسئلة مثل: هل فيها سرد ووصف وحوار؟ وهل لها رسالة؟ هل الأحداث مرتبة؟ هل اللغة سليمة؟ ثم أعدل ما ينقص.","EX":[["أطبق معيارين من الشبكة على قصة كتبتها: «هل الأحداث مرتبة زمنيا؟» و«هل الشخصية تأثرت بالأحداث؟»","أعيد قراءة الأحداث وأرتبها. إن وجدت أن الحدث الثاني لا يأتي بعد الأول أصحح الترتيب. أتحقق أن البطل تغير بين البداية والنهاية. إن لم يتغير أضيف حدثا محوّلا."]]},{"m":1,"w":5,"t":"الإدماج: وضعية تقويم المقطع 1","pg":"ص 26","i":"🏁","B":[["الإنتاج الشفوي: السياق",["رأيت زميلا يغش في اختبار وتألمت","أريد نصحه دون جرح مشاعره أو كشف معرفتي بغشه"]],["الإنتاج الشفوي: التعليمة",["أسرد قصة عن شخص غش في حياته المهنية","نهاية مأساوية دمرت مستقبله"]],["الإنتاج الكتابي: السياق",["المخدرات تغزو المحيط وأحيانا المدرسة","أفكر مع فوجي في وسيلة لتوعية الزملاء"]],["الإنتاج الكتابي: التعليمة",["أكتب قصة بأسلوبي عن مدمن دمر المخدر حياته","أستعين بشريط فيديو وأوظف مواردي السردية"]],["منهج العمل",["أحدد الموضوع والرسالة ثم المخطط السردي","أدمج السرد والوصف والحوار بحجم متناسب","أستعمل عطف النسق وعطف البيان والبدل في جملي"]],["التقويم الذاتي",["أختار شبكة التقويم الذاتي التي يقترحها الأستاذ","أصحح ما كان ناقصا قبل التسليم"]]],"K":"في الإدماج أوظف ما تعلمته: بناء قصة ذات رسالة، بسرد ووصف وحوار، ولغة سليمة تتضمن العطف والبدل.","M":["أقرأ السياق والتعليمة وأحدد المطلوب بدقة","أضع مخططا: وضعية ابتدائية ثم تحول ثم نهاية","أنوّع الأنماط وأحترم الترتيب الزمني","أراجع اللغة وعلامات الوقف بالشبكة"],"X":"المطلوب منك قصتان: واحدة تحكيها شفويا عن غشاش، وأخرى تكتبها عن مدمن مخدرات. في كل قصة بداية، ثم حدث يغير حياة البطل، ثم نهاية فيها عبرة. استعمل الوصف والحوار وجملا سليمة.","EX":[["أضع مخططا للقصة الكتابية عن المدمن","الوضعية الابتدائية: تلميذ متفوق ذو أسرة مستقرة. العنصر المحوّل: يجرب المخدر مع رفاق السوء ويدمنه. الوضعية النهائية: يفقد دراسته وصحته ثم يستفيق متأخرا. الرسالة: التحذير من المخدرات."],["أعطي جملة وصفية فيها بدل وأخرى سردية فيها عطف نسق","وصفية: «كان وجه الفتى نصفُه شاحب». سردية: «أدمن الفتى ثم فقد دراسته». «نصفه» بدل بعض من كل، و«فقد دراسته» معطوف بـ«ثمّ»."]]},{"m":2,"w":1,"t":"فهم المنطوق: ثقافة الصورة","pg":"ص 28-29، 34-35، 40-41","i":"🎧","B":[["الموضوع",["الخطاب يتحدث عن ثقافة الصورة وهيمنتها على حياتنا","يقارن بين مكانة الصورة ومكانة الأدب والكلمة قديما","يعرض أثر القنوات الفضائية في المجتمع"]],["الأفكار الرئيسة",["الصورة ثقافة مفروضة تقتحم البيوت وتؤثر في الأفكار","الصورة كسرت حاجز التلقي فصار الأميون يتابعون","عصر النخبة ولّى لكن دورها القيادي باقٍ"]],["الأنماط في الخطاب",["سردي: أفعال ماضية وأحداث متتابعة وظروف زمان","حجاجي: رأي ثم حجج وأقوال وشواهد","تفسيري: فكرة يتبعها شرح وتحليل وتعليل"]],["مؤشرات السرد",["الأفعال الماضية مثل كان ولم يعد","تتابع الأحداث وغلبة ضمير الغائب","وجود ظروف الزمان"]],["مؤشرات الحجاج والتفسير",["الحجاج: عرض وجهة نظر ثم تقديم الحجج","الحجج: أقوال داعمة كمثل صيني وقول الناقد رولان بارت","التفسير: طرح الفكرة ثم تعليل صحتها"]],["أسئلة الفهم",["المقصود بثقافة الصورة وما يقابلها","التعليق على عبارة الصورة تساوي ألف كلمة","إيجابيات القنوات الفضائية وسلبياتها وإبداء الرأي مع التعليل"]]],"K":"ثقافة الصورة تفرض نفسها في عصرنا، والخطاب يمزج السرد والتفسير لخدمة موقف حجاجي.","M":["حدّد الفكرة الأساسية في كل فقرة بعد الاستماع","ميّز النمط من مؤشراته لا من الموضوع","النمط السردي قد يأتي خادما للنمط الحجاجي أو التفسيري","علّل موافقتك أو معارضتك من الخطاب ومن واقعك"],"X":"الخطاب يقول إن الصور صارت تدخل بيوتنا وتؤثر فينا أكثر مما تفعل الكلمات. يستعمل صاحبه الحكاية والشرح والحجج ليقنعنا برأيه. وعلينا أن نعرف النمط من علاماته، كالأفعال الماضية للسرد وتقديم الأقوال والشواهد للحجاج.","EX":[["جاء في جزء من الخطاب: كان يقوم، كان يعكس، بدأ ينحصر، لم يعد. ما زمن الأفعال ونمط الجزء؟","كلها أفعال ماضية. تتابع فيها الأحداث. يغلب ضمير الغائب. يوجد ظرف زمان. إذن النمط سردي."],["جزء فيه رأي ثم مثل صيني وقول لرولان بارت، ما نمطه ولماذا؟","يبدأ بوجهة نظر عن أهمية الصورة. ثم يقدم حججا هي المثل الصيني وقول الناقد وشاهد القنوات الفضائية. عرض الرأي مع الحجج مؤشر الحجاج. النمط حجاجي."]]},{"m":2,"w":2,"t":"فهم المكتوب: الصحافة والأمة","pg":"ص 30-31","i":"📰","B":[["التعريف",["رسالة من الشيخ إبراهيم اطفيش (1886-1965) إلى الشيخ أبي اليقظان","اطفيش عالم وفقيه إباضي من وادي ميزاب ونشيط في الإصلاح","المصدر: كتاب الشيخ إبراهيم اطفيش في جهاده الإسلامي لمحمد ناصر"]],["الفكرة العامة",["حزن الكاتب لتعطيل جريدة وادي ميزاب بقرار استعماري","وتشجيعه على الصبر والمطالبة بعودتها"]],["الأفكار حسب الفقرات",["الأولى: تعبير عن الألم وأسئلة متعجبة من هذا الظلم","الثانية: تفسير الدوافع، فالاستعمار خاف من صوت الشعب","الثالثة: دعوة إلى عدم اليأس وواجب الأمة نحو صحافتها","الرابعة: الصحافة سلاح الأمة ولسانها ومرشدتها"]],["المفردات",["الغشومة: الظلم والعدوان","النائبة: المصيبة","العتاة: الظالمون المتجبرون","الطاغوت: الطغيان والظلم"]],["القيم",["الدفاع عن مقومات الشعب وهويته","الصبر وعدم اليأس أمام الظلم","وعي الأمة بدور الصحافة الهادفة"]],["النمط والاتساق",["الأسلوب مزيج من الانفعال والحجاج والتوجيه","التوجيه في عبارات نهي وأمر مثل لا تهن ولا تحزن","الروابط: حروف العطف كالواو وأم وثم","المحسن البديعي: جناس ناقص بين الإرهاق والإزهاق، وظيفته جمالية صوتية"]]],"K":"الصحافة الهادفة لسان الأمة وسلاحها، ومنعها بالقوة يستوجب الصبر والمطالبة بحقها.","M":["لخّص كل فقرة في جملة قصيرة","استخرج مؤشرات النمط ومثّل لها","اقرأ الفقرة بلا روابط لتفهم دور الروابط","ابحث عن معنى الكلمة الصعبة في المعجم"],"X":"في هذه الرسالة يحزن عالم جزائري لأن الاستعمار منع جريدة وادي ميزاب. يشرح لماذا خاف المستعمر منها، ثم يطلب من صاحبها ألا يستسلم. ويؤكد أن الأمة بلا صحافة تفقد صوتها وقوتها.","EX":[["لماذا ربط الكاتب بين الصحافة والأمة؟","الصحافة تعبّر عن كمال الأمة. وتدلها على طرق الحياة. وهي سلاحها وقوتها. إذن لا يجوز أن تبقى الأمة بلا جريدة."],["ما المحسن البديعي في عبارة الإرهاق والإزهاق؟","الكلمتان متقاربتان لفظا ومختلفتان في حرف واحد. هذا جناس ناقص. وظيفته جمالية صوتية بإيقاع موسيقي."]]},{"m":2,"w":2,"t":"فهم المكتوب: أسرى الشاشات","pg":"ص 36-37","i":"📱","B":[["التعريف",["الكاتبة حنان بيروتي، أديبة أردنية من الزرقاء","نُشر النص في مجلة العربي، العدد 705، أوت 2017","عنوانه يعني أن الناس صاروا عبيدا لشاشاتهم"]],["الفكرة العامة",["الهواتف الذكية تبعد أفراد الأسرة عن بعضهم رغم وجودهم معا"]],["الأفكار حسب الفقرات",["السهرات العائلية صارت صامتة والعيون على الهواتف","الهاتف صار ضرورة وموضة وموضع تنافس وتفاخر","زمن التواصل جلب جفافا عاطفيا بين أفراد الأسرة","أمهات يشغلن أبناءهن بالهاتف وينشأ الطفل أسيرا له","ضياع كثير من الوقت في التصفح السريع"]],["المفردات",["مواكبة: مسايرة","هدر: إضاعة","الانزواء: الانعزال","الهواتف الخلوية: الهواتف المحمولة"]],["القيم",["الاعتدال في استعمال التقنية","الحفاظ على الدفء الأسري والحوار","الانتباه إلى قيمة الوقت"]],["النمط والاتساق",["النمط تفسيري: فكرة ثم شرح وتحليل وتعليل وأمثلة","ينتهي بسؤال: هل الانزواء هروب من الوحدة أم سبب لها؟","أدوات الشرط تربط الشرط بجوابه، مثل لو واستطعنا ثم لأصابتنا","لكن تفيد الاستدراك وتربط المعاني منطقيا"]]],"K":"تحذر الكاتبة من أن الشاشات تعزل الأسرة عاطفيا، وتعرض ذلك بنمط تفسيري معلَّل.","M":["اجعل عنوانا لكل فقرة ثم وحّد الأفكار","قارن موضوع النص بتصورك الأول من العنوان","تعرّف التفسير من التعليل بعد الفكرة","انتبه إلى أدوات الشرط ودورها في الاتساق"],"X":"تصف الكاتبة بيوتا يجلس أهلها معا لكن كل واحد في عالم هاتفه. تشرح أن هذا يضعف المودة بين أفراد الأسرة ويضيع الوقت. وتختم بسؤال يدعونا إلى التفكير: هل الشاشة تنقذنا من الوحدة أم تزيدها؟","EX":[["اقترح عنوانا للفقرة التي تتحدث عن الأمهات والأطفال.","الفقرة تصف أما تشغل ابنها بالهاتف. والطفل ينشأ مفتونا بالشاشة. عنوان مناسب: الطفل أسير الشاشة."],["ما دور لو في عبارة: لو استطعنا حساب الوقت لأصابتنا صدمة؟","لو أداة شرط. جملة استطعنا جملة الشرط. جملة أصابتنا جواب الشرط. فالأداة تربط الجملتين وتمنح النص اتساقا."]]},{"m":2,"w":2,"t":"فهم المكتوب: تلك الصحافة","pg":"ص 42-43","i":"📜","B":[["التعريف",["قصيدة للشاعر الطيب بن إبراهيم العقبي، ولد سنة 1888 ببسكرة","من مؤسسي جمعية العلماء المسلمين وتوفي سنة 1960","المصدر: موسوعة الشعر الجزائري، دار الهدى، 2009"]],["الفكرة العامة",["الشاعر يمدح الصحافة ويدعو إلى خدمتها لأنها طريق العلم والنهضة"]],["الأفكار حسب الأبيات",["الأولى: تحية الجزائر والنهوض بالشعب الجاهل","الثانية: الصحافة تستحق الجهد والوقت","الثالثة: ثناء على الصحفيين وتوفيقهم في واجبهم","الرابعة: العودة إلى تاريخ الأمم التي ارتقت بالعلم"]],["المفردات",["حثيثا: سريعا وجادا","تندى: تبذل لها الجهد والوقت","مرحى: أهلا وسهلا","تردينا: تهلكنا","دانية: قريبة"]],["القيم",["الاعتزاز بالوطن والانتماء","طلب العلم والمعرفة","احترام أهل الصحافة"]],["النمط والاتساق",["النمط الغالب توجيهي، وهو خطاب من مرسل إلى مرسل إليه","مؤشراته: أفعال الأمر والنهي وضمير المخاطب","الأبيات الأخيرة تقترب من السرد لأنها تذكر أحداث الماضي","ضمير المؤنثة الغائبة يعود إلى الصحافة، وضمير نا للجزائريين"]]],"K":"قصيدة توجيهية تجعل الصحافة سبيلا إلى العلم وتقوية الهوية الوطنية.","M":["استخرج الأفعال وصنّفها إلى أمر ونهي وإخبار","حدّد الضمير الطاغي في الأبيات","ابحث عن مرجع كل ضمير لتفهم الاتساق","علّل موقفك من رأي الشاعر بدليل"],"X":"الشاعر يخاطب شخصا ويطلب منه أن يسير في طريق العلم وأن يخدم الصحافة. يمدح الصحفيين ويذكّره بأمم ارتفعت بالمعرفة. فالنص أوامر ونصائح، وهذا نمط التوجيه.","EX":[["ما نمط الأبيات الثلاثة الأولى؟","فيها فعل أمر مثل حيّ واعمل. الخطاب موجه إلى مخاطب واحد. غايتها دفعه إلى فعل شيء. إذن النمط توجيهي."],["على من تعود الضمائر المؤنثة في الأبيات من الرابع إلى الثامن؟","ورد في البيت الرابع لفظ الصحافة. ثم تتابعت ضمائر الغائبة. فهي تعود إلى الصحافة. هذه إحالة قبلية بالضمير."]]},{"m":2,"w":3,"t":"الظاهرة اللغوية: العدد وأحواله","pg":"ص 32","i":"🔢","B":[["التعريف",["العدد ما دل على المعدود، مثل ثلاثة وعشرون وألف","المعدود أو التمييز هو الاسم الذي يدل عليه العدد"]],["أنواع العدد",["المفرد: من واحد إلى عشرة والمئة والألف","المركّب: من أحد عشر إلى تسعة عشر","العقود: عشرون إلى تسعون","المعطوف: ما جمع آحادا وعقدا مثل: خمسة وتسعون"]],["الجنس مع المعدود",["من ثلاثة إلى عشرة: العدد يخالف المعدود","11 و12: العدد يطابق المعدود","13 إلى 19: الآحاد تخالف والعشرة تطابق","العقود والمئة والألف لا علاقة لها بجنس المعدود"]],["التمييز",["من 3 إلى 10: جمع مجرور بالإضافة","من 11 إلى 99: مفرد منصوب","المئة والألف: مفرد مجرور بالإضافة"]],["المعطوف (من 21 إلى 99)",["الواحد والاثنان يطابقان المعدود: واحد وعشرون، واثنتان وعشرون","من ثلاثة إلى تسعة يخالف المعدود: ثلاثة وعشرون، وثلاثٌ وعشرون","العقد لا يتغير لا في الجنس ولا في العدد"]],["أخطاء شائعة",["مطابقة الأعداد من ثلاثة إلى عشرة للمعدود","جر تمييز الأعداد المركبة","جمع التمييز بعد العقود"]]],"K":"الأعداد من ثلاثة إلى عشرة تخالف معدودها، والمركّبة تطابق في 11 و12 ثم تخالف في الآحاد وتطابق في العشرة، وتمييزها مفرد منصوب.","M":["انظر إلى المعدود: مذكر أم مؤنث؟","طبّق قاعدة المخالفة على الآحاد من 3 إلى 10","ضع التمييز المفرد المنصوب بعد 11 إلى 99","اكتب المئة والألف وبعدهما مفرد مجرور"],"X":"العدد كلمة تبين كم عدد الأشياء. بعض الأعداد تغيّر شكلها حسب كون الشيء مذكرا أو مؤنثا، والقاعدة عندها مخالفة. وبعضها لا يتغير مثل العشرين والمئة والألف. وبعد كل عدد يأتي الاسم المعدود في حالة إعرابية خاصة.","EX":[["اكتب بالحروف: تنتج المطبعة 10 جرائد.","جريدة مؤنثة. من 3 إلى 10 يخالف العدد معدوده فيأتي العدد بلا تاء مع المؤنث: عشرُ. عشرَ مفعول به منصوب. جرائدَ مضاف إليه مجرور. الجملة: تنتج المطبعة عشرَ جرائدَ."],["اكتب بالحروف: أقرأ 13 عنوانا و14 مجلة.","عنوان مذكر فنقول ثلاثة عشر. مجلة مؤنثة فنقول أربع عشرة. التمييز مفرد منصوب. الجملة: أقرأ ثلاثةَ عشرَ عنوانا وأربعَ عشرةَ مجلةً."],["اكتب بالحروف: تخرج من المعهد 111 طالبا.","مئة وأحد عشر. طالب مذكر فنقول أحد عشر. التمييز مفرد منصوب. مئةٌ فاعل مرفوع. الجملة: تخرج من المعهد مئةٌ وأحدَ عشرَ طالبا."]]},{"m":2,"w":3,"t":"الظاهرة اللغوية: الاستثناء","pg":"ص 38","i":"✂️","B":[["التعريف",["إخراج عنصر من الحكم العام بأداة استثناء"]],["عناصره",["المستثنى منه: ما شمله الحكم العام","المستثنى: ما خرج عن الحكم ويقع بعد الأداة","الأداة: إلا أو سوى أو غير"]],["إعراب المستثنى بإلا",["جملة مثبتة مع ذكر المستثنى منه: منصوب","جملة منفية مع ذكره: منصوب أو بدل منه","جملة منفية دون ذكره: حسب موقعه في الجملة"]],["غير وسوى",["الاسم بعد غير وسوى يكون مجرورا بالإضافة","وغير وسوى تأخذان إعراب المستثنى بعد إلا","وتأخذان إعراب المستثنى: النصب بعد الكلام التام المثبت، والنصب أو البدل بعد التام المنفي، وحسب الموقع إن غاب المستثنى منه"]],["أمثلة قصيرة",["نجح الطلاب إلا طالبا","ما حضر الصحفيون إلا المراسلَ أو المراسلُ","ما حضر إلا المراسلُ"]],["أخطاء شائعة",["رفع المستثنى في جملة مثبتة","نسيان البدل الجائز بعد النفي","جر المستثنى بعد إلا"]]],"K":"المستثنى بإلا منصوب في الجملة المثبتة، وفي المنفية يجوز النصب أو البدل، وإذا غاب المستثنى منه أُعرب حسب موقعه.","M":["حدّد الأداة أولا","ابحث عن المستثنى منه وانظر هل الجملة مثبتة أم منفية","طبّق قاعدة الإعراب بحسب الحالة","اجعل المستثنى بعد غير وسوى مجرورا بالإضافة"],"X":"الاستثناء معناه أن تحكم على الجميع ثم تُخرج واحدا منهم. الذي نخرجه هو المستثنى، والجميع هو المستثنى منه، والأداة بينهما. إعراب المستثنى يتغير إن كانت الجملة مثبتة أو منفية.","EX":[["أعرب: انتشرت في عصرنا كل وسائل الاتصال إلا التلغراف.","إلا أداة استثناء. التلغراف مستثنى بإلا منصوب وعلامة نصبه الفتحة. الجملة مثبتة والمستثنى منه كلُّ وسائل الاتصال."],["أعرب: ما حضر الصحفيون إلا المراسلَ.","الجملة منفية والمستثنى منه مذكور وهو الصحفيون. فيجوز نصب المراسل على الاستثناء. ويجوز رفعه بدلا من الصحفيين. إلا أداة استثناء."],["أعرب: ما حضر إلا المراسلُ.","الجملة منفية والمستثنى منه غير مذكور. إلا أداة حصر. المراسلُ فاعل مرفوع وعلامة رفعه الضمة."]]},{"m":2,"w":3,"t":"الظاهرة اللغوية: التمييز","pg":"ص 44","i":"🔍","B":[["التعريف",["اسم نكرة منصوب يأتي لإزالة الغموض عن كلمة قبله"]],["تمييز الذات",["يزيل الغموض عن اسم ذات: عدد أو كيل أو وزن أو مساحة أو قياس","يأتي المميَّز عددا أو مقدارا","مثال: أحد عشر بيتا"]],["تمييز الجملة",["يزيل الغموض عن مضمون جملة كاملة","مثال: امتلأت الوراقات صحفا","يكون غالبا محوَّلا عن الفاعل"]],["أنواع الذات",["العدد: ألف وخمسٌ وثلاثون نسخة","الكيل أو السعة: ألف لتر حبرا","الوزن: أطنان ورقا","المساحة: عشرون هكتارا أرضا","القياس: خمسون مترا قماشا"]],["الإعراب",["تمييز منصوب وعلامة نصبه الفتحة","وتكون علامة نصبه فرعية إن جاء مثنى أو جمعا سالما"]],["أخطاء شائعة",["جر التمييز بدل نصبه","استعمال معرفة بدل نكرة","الخلط بين تمييز الذات وتمييز الجملة"]]],"K":"التمييز اسم نكرة منصوب يوضح غموض ذات أو جملة، ويكون المميَّز عددا أو مقدارا في تمييز الذات.","M":["اسأل: عن أي كلمة يزيل الغموض؟","إن كان قبله عدد أو مقدار فهو تمييز ذات","إن أزال غموض جملة فهو تمييز جملة","انصبه دائما واجعله نكرة"],"X":"التمييز كلمة نضيفها لنوضح ما كان مبهما. حين نقول اشتريت عشرين فلا نعرف ماذا، فنكمل: كتابا. وهذا الكتاب هو التمييز، يأتي نكرة ومنصوبا. وقد يوضح معنى جملة كاملة مثل: تصبب الصحفي عرقا.","EX":[["بيّن التمييز في: حوت القصيدة أحد عشر بيتا.","بيتا تمييز. وهو أزال غموض العدد أحد عشر. فهو تمييز ذات. وهو اسم نكرة منصوب وعلامة نصبه الفتحة الظاهرة."],["بيّن التمييز في: امتلأت الجزائر فخرا.","فخرا تمييز. أزال غموض جملة امتلأت الجزائر. فهو تمييز جملة. وهو منصوب وعلامة نصبه الفتحة."],["بيّن التمييز في: نشرت الجريدة آلاف الأمتار المربعة صحفا.","صحفا تمييز منصوب بالفتحة. وهو يوضح مقدار المساحة آلاف الأمتار المربعة. فهو تمييز ذات. والمميَّز هو آلاف الأمتار."]]},{"m":2,"w":4,"t":"الإنتاج الكتابي: اختيار النمط والموضوع وجمع الموارد","pg":"ص 33","i":"📝","B":[["الهدف",["التحضير لكتابة نص حجاجي حول الإعلام والمجتمع"]],["اختيار النمط",["الحجاج مع الحوار","التفسير مع الوصف أو السرد أو التفسير وحده","نبرر اختيارنا"]],["مواضيع مقترحة",["التحسيس بين الإعلام والدعاية","المفاضلة بين إعلام الخبر وإعلام الرأي","وسائل التواصل بين الرافض والمؤيد","وسائل الإعلام الحديثة والقديمة"]],["جمع الموارد",["الموارد ورقية ورقمية والإنترنت أسرعها","نستشير الأولياء والأساتذة","ننتقي المواقع الموثوقة ونُنوّع المصادر"]],["جدول المطالعة",["نحدد المصدر: مكتبة المنزل أو المدرسة أو الحي أو الإنترنت","ونحدد المجال الثقافي كالإعلام والتضامن والهجرة","ونحدد الجنس الأدبي كمقالة أو حوار أو رسالة"]],["بعد الاختيار",["نبرر اختياراتنا","ونناقشها مع الزملاء"]]],"K":"قبل الكتابة نختار النمط والموضوع ونبرر اختيارنا، ثم نجمع معلومات من مصادر موثوقة ومتنوعة.","M":["اختر موضوعا تعرفه وتحبه","علّل سبب اختيار النمط","اجمع المعلومات من مصادر موثوقة","دوّن أفكارك قبل الكتابة"],"X":"قبل أن تكتب مقالا لا تبدأ مباشرة. اختر نمط نصك وموضوعه، وقل لماذا اخترتهما. بعدها اجمع معلومات من كتب ومواقع موثوقة، واسأل أستاذك أو والديك إن احتجت.","EX":[["اختر موضوعا وبرر اختياره.","الموضوع: وسائل التواصل بين المؤيد والرافض. السبب: فهو قريب من حياتنا ويحتمل رأيين. النمط: حجاجي لأنني أعرض رأيا وحججا."]]},{"m":2,"w":4,"t":"الإنتاج الكتابي: تلخيص النص الحجاجي وشبكة التقويم","pg":"ص 39، 45","i":"✍️","B":[["بنية النص الحجاجي",["نوعان: عرض فكرة، أو إبداء رأي في فكرة"]],["عناصر التلخيص",["عرض فكرة: ألخص الفكرة والحجج وتأكيد الفكرة","إبداء رأي: ألخص الفكرة والرأي والحجج"]],["مثال: نص التلفزيون",["الفكرة: أهمية التلفزيون تتزايد كل يوم","الحجج: تقنيات الإغراء وتأثيره في المتلقي ورأي المختصين","تأكيد: برنامج فضائي واستفتاء الطلبة، ثم نتيجة تخص المجتمع"]],["خطوات التلخيص",["أقرأ النص وأحدد الفكرة","أبحث عن الحجج وأنواعها","أكتب الملخص في حجم يقارب الربع"]],["شبكة التقويم",["هل لخصت نصوصا حجاجية وهيكلتها في مخططات؟","هل صنفتها إلى نصوص فكرة ونصوص رأي، ومؤيد ومخالف؟","هل وازنت بين الأفكار المؤيدة والمعارضة؟"]],["الجانب اللغوي",["احترام التركيب النحوي للجمل","احترام علامات الوقف والضوابط اللغوية","احترام معايير الكتابة والعرض"]]],"K":"لتلخيص النص الحجاجي أحدد نوعه، فكرة أم رأيا، ثم ألخص عناصره في ربع حجم الأصل مع مراعاة شبكة التقويم.","M":["حدّد نوع النص أولا","استخرج الفكرة والحجج","اجعل الملخص في نحو ربع النص","راجع بشبكة التقويم قبل التسليم"],"X":"التلخيص أن تبقي الأفكار المهمة وتحذف التفاصيل. في النص الحجاجي نبحث عن الفكرة التي يدافع عنها الكاتب وعن الحجج التي ذكرها. ثم نكتبها باختصار ولغة سليمة، ونراجع عملنا بجدول التقويم.","EX":[["لخّص فكرة نص التلفزيون في جملتين.","الفكرة: أهمية التلفزيون تزداد في حياة الناس. الحجة: يؤثر في أفكارنا وسلوكنا بتقنياته الجاذبة. الخلاصة: التلفزيون يؤثر فينا بقوة وعلينا الانتباه إليه."],["ما نوع النص: نص يعرض فكرة أهمية التلفزيون وحججها؟","يعرض فكرة أصلية ثم حججا تدعمها. لا يُبدي رأيا في فكرة سابقة. إذن هو نص عرض فكرة."]]},{"m":2,"w":5,"t":"الإدماج: وضعية تقويم المقطع 2","pg":"ص 46","i":"🎯","B":[["الإنتاج الشفوي: السياق",["زملاؤك منشغلون بمواقع التواصل وبعيدون عن شؤون وطنهم","اقترح أستاذك نقاشا في اليوم الوطني للصحافة"]],["التعليمة الشفوية",["أدر النقاش مبينا أهمية هذه الوسائل","اعرض حجج كل طرف","اختم بعرض شفوي يلخص النتائج"]],["الإنتاج الكتابي: السياق",["الشباب مولعون بالشبكات الاجتماعية ولا يطالعون الجرائد","مسابقة أحسن مقال مدرسي في قضية ثقافية"]],["التعليمة الكتابية",["اكتب مقالة لا تقل عن عشرة أسطر","اعرض أهمية الإعلام المكتوب بالحجج لإقناع الزملاء بالمطالعة الصحفية","اختر شبكة التقويم الذاتي"]],["منهج العمل",["حدّد الفكرة وأعدّ الحجج","نظّم الأفكار: مقدمة وعرض وخاتمة","استعمل روابط منطقية ولغة سليمة"]],["مخطط نموذجي للمقال",["المقدمة: ظاهرة الإقبال على الشبكات وإهمال الجرائد","العرض: فوائد الجرائد في تنمية الفكر واللغة والمعلومات الموثوقة","الخاتمة: دعوة إلى المطالعة الصحفية"]]],"K":"في الإدماج أوظف الأنماط والظواهر المدروسة لإدارة نقاش شفوي وكتابة مقال حجاجي مدعّم بالحجج.","M":["افهم السياق والتعليمة قبل البدء","اجمع الحجج وصنّفها إلى مؤيدة ومعارضة","استعمل العدد والاستثناء والتمييز بصواب","راجع كتابتك بشبكة التقويم"],"X":"في هذه الوضعية تتحدث مع زملائك في نقاش عن وسائل الإعلام، ثم تكتب مقالا يقنعهم بقراءة الجرائد. فكّر في أسباب مقنعة وأمثلة، ورتبها في مقدمة وعرض وخاتمة بلغة سليمة.","EX":[["اكتب فقرة حجاجية قصيرة عن فائدة المطالعة الصحفية.","أبدأ برأيي: المطالعة الصحفية تنمّي الفكر واللغة. أدعم بحجة: الجرائد تقدم معلومات موثوقة ومنوعة. أضيف مثالا: يزداد رصيدنا من المفردات. أختم بالدعوة إلى القراءة."],["اكتب جملة فيها استثناء عن وسائل الإعلام.","ما تابع التلاميذ إلا الأخبارَ الثقافية. إلا أداة حصر. الجملة منفية والمستثنى منه محذوف. فالأخبارَ مفعول به منصوب وعلامة نصبه الفتحة حسب موقعه في الجملة"]]},{"m":3,"w":1,"t":"فهم المنطوق: الإنسانية ومشكلاتها","pg":"ص 48-49، 54-55، 60-61","i":"🎧","B":[["الموضوع والمضمون",["خطاب يتحدث عن الإنسانية ومعاناتها","يصوّرها أمًّا حنونًا تتألم وتستغيث","يذكر مشكلات قديمة ثم مشكلات حاضرة"]],["المشكلات المعروضة",["قديمًا: الاستبداد والاستعباد والدجل والضلال","اليوم: الحروب والفقر وشرورهما","المرسل يدعو الناس إلى إغاثتها"]],["الأنماط في الخطاب",["وصفي: يعرّف الإنسانية بصفات وتشبيه","تفسيري: يشرح أسباب معاناتها","توجيهي: يطلب الرحمة بجمل طلبية"]],["السرد ومؤشراته",["أفعال ماضية وظرف زمان","أحداث متتابعة تربطها أدوات مثل «ما كاد... حتى»","الوصف يخدمه ببيان موقف المرسل من الظالمين"]],["الإجمال والتفصيل",["يجمل المشكلة: الإنسانية تشتكي من داهيتين","ثم يفصّلها: الحرب ثم الفقر","جمل «لو» الشرطية توجّه توجيهًا ضمنيًّا"]],["الإنتاج الشفوي ص 61",["كلمة تدعو الزملاء إلى مساعدة المتعثرين دراسيًّا","مقدمة فعرض فخاتمة","تفسيري للتبرير وتوجيهي للدعوة"]]],"K":"الخطاب المنطوق قد يجمع أنماطًا عدة: الوصف والتفسير والسرد والتوجيه، وكلها تخدم قصد المرسل.","M":["اسمع الخطاب كله ثم حدّد موضوعه وفكرته","استخرج المؤشرات: أفعال، أدوات، جمل طلبية","حدّد النمط الغالب وعلّل بمؤشرين","اربط الأنماط المساعدة بقصد المرسل"],"X":"في هذا الخطاب يتكلم الكاتب عن الإنسانية كأنها أمّ طيبة تتألم من المصائب. هو يصفها أولًا ثم يشرح سبب ألمها، وفي النهاية يطلب منا أن نرحمها ونساعدها. كل نمط له دور: الوصف يؤثر فينا والشرح يقنعنا والتوجيه يدعونا إلى العمل.","EX":[["حدّد نمط الجزء: استغاثت الإنسانية قديمًا من المستبدين فأغاثها دعاة المساواة.","أفعال ماضية. ظرف زمان «قديمًا». أحداث متتابعة. النمط: سردي."],["حدّد أسلوب ونوع العبارة: «فهل من منجد؟».","الأسلوب إنشائي. النوع طلبي (استفهام). النمط توجيهي. قصده حثّ السامعين على الإغاثة."],["ما علاقة السرد بالوصف في الجزء الثاني من الخطاب؟","السرد يروي أحداث استغاثة الإنسانية. الوصف بالصفات المتعددة يبيّن رأي المرسل في الظالمين. إذن الوصف يخدم السرد."]]},{"m":3,"w":2,"t":"فهم المكتوب: وكالة الأونروا","pg":"ص 50-51","i":"🕊️","B":[["التعريف بالنص",["نص إعلامي من الموقع الرسمي للأونروا","يعرّف بوكالة غوث وتشغيل اللاجئين الفلسطينيين","نمطه تفسيري يدعمه السرد"]],["نشأة الوكالة",["أنشئت بعد النزاع العربي الإسرائيلي عام 1948","بقرار رقم 302 للجمعية العامة للأمم المتحدة (1949)","بدأت عملها في ماي 1950"]],["مهامها وحدودها",["تعليم ورعاية صحية وإغاثة وبنية تحتية","قروض صغيرة واستجابة طارئة","خدماتها لمن يقيم في مناطق عملها ويحتاج المساعدة"]],["من هو اللاجئ؟ والتمويل",["كان مقيمًا في فلسطين بين جوان 1946 وماي 1948","فقد بيته ومصدر رزقه","تموَّل بتبرعات طوعية من دول ومنظمات"]],["الأنماط والتماسك",["السرد: ماضٍ وتواريخ وتجديد الولاية","التفسير: مضارع وتعداد وموضوعية وأسلوب مباشر","التكرار لترسيخ المفاهيم كالوكالة واللاجئين"]],["الرصيد اللغوي",["كانون الأول: ديسمبر، أيار: ماي، حزيران: جوان","اللاجئ: من فرّ من وطنه لحرب أو اضطهاد","مورد الرزق: مصدر العيش"]]],"K":"الأونروا وكالة أممية أُنشئت لإغاثة اللاجئين الفلسطينيين وتشغيلهم، وما زالت مستمرة لأن قضيتهم لم تُحَل.","M":["الفكرة العامة: التعريف بالأونروا ودورها","النص إعلامي: يقدم معلومات لا آراء","المؤشرات: مضارع، تعداد، موضوعية، لغة قاموسية مباشرة","السرد يدعم التفسير حين نحتاج التفاصيل التاريخية"],"X":"هذا النص يشرح لنا ما هي الأونروا ولماذا وُجدت. بعد حرب 1948 صار آلاف الفلسطينيين لاجئين، فأنشأت الأمم المتحدة هذه الوكالة لتعلّمهم وتعالجهم وتساعدهم. ما زالت تعمل إلى اليوم لأن مشكلتهم لم تنتهِ، لكنها تواجه نقصًا في المال.","EX":[["ما السبب التاريخي لإنشاء الأونروا ولفائدة من؟","السبب النزاع العربي الإسرائيلي عام 1948 وما نتج عنه من لجوء. أُنشئت لفائدة اللاجئين الفلسطينيين."],["هل الحل مؤقت أم دائم؟ ولماذا يستمر عملها؟","هو مؤقت في الأصل ويُجدَّد مرارًا. يستمر لأن قضية اللاجئين لم تُحَل. إذن تعمل إلى أن يوجد حل."],["اذكر مؤشرين لنمط التفسير في النص.","الأفعال المضارعة مثل «تقدم». التعداد مثل ذكر التعليم والصحة والإغاثة. أيضًا الأسلوب المباشر والموضوعية."]]},{"m":3,"w":2,"t":"فهم المكتوب: في مواجهة الكوارث","pg":"ص 56-58","i":"🚑","B":[["التعريف بالنص",["كاتبته أمال فضيل","مجلة الجيش، العدد 449، ديسمبر 2000","نمط تفسيري يدعمه الوصف"]],["الفكرة العامة",["الكوارث الطبيعية أكثر وأشد، والبلدان الفقيرة أكثر تضررًا","الصليب الأحمر والهلال الأحمر يقدمان الإغاثة","هما أكبر منظمة إنسانية في العالم"]],["أقسام الحركة الثلاثة",["اللجنة الدولية للصليب الأحمر: أُنشئت 1863 بجنيف لحماية الجرحى","الاتحاد الدولي للجمعيات: تأسس 1919 لتحسين حياة المستضعفين","الجمعيات الوطنية: قوة الحركة محليًّا (نحو 190 جمعية)"]],["قيمها وعملها",["مساعدة دون تمييز بسبب الجنسية أو العرق أو الدين","التنسيق بين الاتحاد والجمعيات يوسّع القدرات","المحلية تساعد السلطات في برامج صحية واجتماعية"]],["النمط والتماسك",["الهدف: التعريف بالحركة وترسيخ مفهومها","الوصف يبيّن واقع مآسي الإنسانية","روابط لفظية ومعنوية مثل «بما أنها... فإنها» تعبّر عن السبب"]],["رصيد لغوي",["أعتى: أقوى وأشد","الإغاثة: النصرة والعون","ابحث في القاموس عن: التمييز، العرق، الطبقة"]]],"K":"الصليب الأحمر والهلال الأحمر حركة إنسانية عالمية تساعد ضحايا الكوارث والحروب دون تمييز، بثلاثة أقسام متكاملة.","M":["حدّد الفكرة العامة ثم الأفكار الأساسية لكل قسم","نمط النص تفسيري داعمه الوصف","ابحث عن الروابط: لفظية (حروف وأدوات) ومنطقية (سبب ونتيجة)","اربط الأفكار بالفكرة العامة"],"X":"النص يعرّفنا بمنظمة إنسانية كبيرة تساعد الناس وقت الكوارث والحروب دون أن تسأل عن دينهم أو جنسيتهم. تتكون من ثلاثة أقسام: واحدة دولية للجرحى، وواحدة تنسّق المساعدات، وجمعيات في كل بلد تقريبًا. تعاون هذه الأقسام يجعل المساعدة أقوى.","EX":[["ما أقسام الحركة الدولية للهلال والصليب الأحمر؟","ثلاثة أقسام. اللجنة الدولية للصليب الأحمر. الاتحاد الدولي لجمعيات الصليب الأحمر والهلال الأحمر. الجمعيات الوطنية."],["هل ترى التنسيق بينهما ضروريًّا؟ علّل.","نعم. التنسيق يجمع الإمكانات. يساعد عددًا أكبر من المحتاجين. ويمنع تكرار الجهود."],["ما نمط النص ولماذا يحتاج إلى الوصف؟","النمط تفسيري لأنه يشرح مفهوم الحركة ويعرّف بها. الوصف يبيّن واقع المآسي الإنسانية. فهو يدعم الفكرة."]]},{"m":3,"w":2,"t":"فهم المكتوب: من يجير فؤاد الصغير؟","pg":"ص 62-63","i":"📜","B":[["التعريف",["قصيدة للشاعر الجزائري محمد العيد آل خليفة (1904-1979)","كان معلّمًا وشاعر جمعية العلماء المسلمين الجزائريين","اثنا عشر بيتًا"]],["الفكرة العامة",["الشاعر يستنهض الأغنياء لإغاثة الفقراء","يعرض مأساة طفل جائع وأمه","غايته التضامن ورحمة المحرومين"]],["بناء القصيدة",["مقطع يصف الفقر ومعاناة الفقير","مقطع يخاطب الأغنياء ويعاتبهم (تقسيم مقترح)","مقطع يترك فيه الطفل والفقير يتكلمان ليؤثر في السامع"]],["النمط ومؤشراته",["توجيهي: النداء وضمائر الخطاب","صيغ الأمر والنهي والاستفهام","الوصف يخدمه ببيان حال الفقراء"]],["الاتساق والانسجام",["غلبة ضمير المخاطبين تحقق وحدة النص","الأسلوب الإنشائي يغلب مع قصد الحث على التضامن","التضامن من أهم قيم المواطنة"]],["رصيد لغوي",["كرب: حزن وغم، الطوى: الجوع","الخز: نسيج من الحرير","الفاقرة: المصيبة الشديدة، آصرة: رابطة قوية"]]],"K":"قصيدة توجيهية يخاطب فيها الشاعر الأغنياء ليرحموا الفقراء، مستعينًا بالنداء والعتاب ووصف مأساة الطفل.","M":["حدّد المخاطَب وسبب النداء وغايته","استخرج صيغ الأمر والنهي والنداء والاستفهام","استخرج مؤشرات الوصف: صفات وحالات","لاحظ الضمير الغالب وعلاقته بالاتساق"],"X":"الشاعر ينادي الأغنياء الذين يعيشون في رفاهية وينسون الفقراء الجوعى. يصف لهم طفلًا يتألم من الجوع وأمه حائرة، ثم يترك الطفل يتكلم ليحرّك قلوبهم. أراد الشاعر أن يدفعنا إلى مساعدة المحتاجين وألا نبقى غير مبالين.","EX":[["إلى من يوجّه الشاعر نداءه ولماذا؟","يوجّهه إلى الأغنياء المترفين. لأنهم قادرون على مساعدة الفقراء وغافلون عنهم. غايته إثارة رحمتهم."],["اذكر مؤشرين للنمط التوجيهي في القصيدة.","النداء مثل «يا أيها الرافعون القصور». الاستفهام مثل «ألا تسمعون ألا تبصرون». وكذلك الأمر في «أعزّوا كرامتي»."],["هل غلب الأسلوب الخبري أم الإنشائي؟ وما أثر ذلك؟","غلب الإنشائي. لأن القصد حثّ المخاطبين على الفعل. فيحقق انسجام الخطاب مع غرضه."]]},{"m":3,"w":3,"t":"الظاهرة اللغوية: الممنوع من الصرف","pg":"ص 52","i":"✍️","B":[["المفهوم",["الاسم الممنوع من الصرف لا يقبل التنوين","ولا يُجرّ بالكسرة بل بالفتحة نيابة عنها","مثل: برامجَ، فلسطينَ"]],["حالات المنع (1)",["مختوم بهمزة تأنيث بعد ألف مد: صحراء","صيغة منتهى الجموع: مرافق، مطافئ","صفة على وزن أفعل: أحمر، أخضر"]],["حالات المنع (2)",["صفة على وزن فعلان/فعلى: سهران، حبلى","صفة أو اسم بألف تأنيث مقصورة: حبلى","علم مؤنث: غزّة، زينب"]],["حالات منع الأعلام",["علم بألف ونون زائدتين: رضوان","علم مركب مزجي: بور سعيد","علم أعجمي فوق ثلاثة حروف: موريس","علم على وزن الفعل: أحمد، أو وزن فُعَل: عمر"]],["كيف أطبّق؟",["أنظر إن كان مجرورًا بلا تنوين","أسأل: هل يدخل في الحالات؟","أعربه: مجرور بالفتحة نيابة عن الكسرة"]],["أخطاء شائعة",["تنوينه أو كسره عند الجر","عدّ جمع المؤنث السالم ممنوعًا مثل طوّافات (مصروف)","إن أُضيف أو دخلته «أل» جُرّ بالكسرة"]]],"K":"الممنوع من الصرف لا يُنوَّن ويُجَرّ بالفتحة نيابة عن الكسرة، إلا إذا أضيف أو عُرِّف بأل.","M":["احفظ حالات المنع واربط كل حالة بمثال","في الجر: «مجرور وعلامة جره الفتحة نيابة عن الكسرة»","اذكر علة المنع في الإعراب","جمع المؤنث السالم مصروف"],"X":"بعض الكلمات لا تأخذ تنوينًا ولا كسرة في آخرها لأنها تشبه الفعل في بعض صفاتها. نقول: مررتُ بغزةَ، وليس بغزةٍ. أما إذا أُضيفت الكلمة أو دخلت عليها «أل» فنجرها بالكسرة كالعادة.","EX":[["بيّن علة منع: رضوان، بور سعيد، أحمد، موريس، زينب، عمر.","رضوان: علم بألف ونون زائدتين. بور سعيد: علم مركب مزجي. أحمد: علم على وزن الفعل. موريس: علم أعجمي فوق ثلاثة أحرف. زينب: علم مؤنث. عمر: علم على وزن فُعَل."],["أعرب ما تحته خط: ساعد الأطباء إخوانهم في غزَّةَ.","في: حرف جر. غزةَ: اسم مجرور بفي وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف (علم مؤنث)."],["استخرج الممنوع من الصرف: مطافئ، طوّافات، زلازل، سهران، حضرموت.","مطافئ: صيغة منتهى الجموع. زلازل: صيغة منتهى الجموع. سهران: صفة على وزن فعلان. حضرموت: علم مركب مزجي. طوّافات: جمع مؤنث سالم فهو مصروف."]]},{"m":3,"w":3,"t":"الظاهرة اللغوية: التوكيد اللفظي والتوكيد المعنوي","pg":"ص 58","i":"🔁","B":[["التوكيد المعنوي",["بألفاظ: نفس، عين، كل، جميع، عامة","تضاف إلى ضمير يعود على المؤكَّد","وتطابقه في النوع والعدد"]],["التوكيد اللفظي",["تكرار الكلمة نفسها أو مرادفها مباشرة","الثانية تسمى توكيدًا لفظيًّا","يتبع المؤكَّد في الإعراب"]],["الإعراب",["التوكيد من التوابع","يأخذ إعراب المؤكَّد رفعًا أو نصبًا أو جرًّا","الضمير المتصل بالتوكيد مضاف إليه"]],["فائدة التوكيد",["تقوية المعنى وإزالة الشك","شمول الجميع بكلّ وجميع","التنبيه والتأكيد بتكرار الكلمة"]],["كيف أميّز؟",["هل تكررت الكلمة نفسها؟ فهو لفظي","هل جاءت «كل، نفس، ذات...» مع ضمير؟ فهو معنوي","ثم أعرب حسب موقع المؤكَّد"]],["أخطاء شائعة",["نسيان الضمير المطابق للمؤكَّد","إعراب «كل» مبتدأ وهي توكيد بعد اسم","إعرابها بغير إعراب المؤكَّد"]]],"K":"التوكيد تابع يقوّي معنى ما قبله: لفظي بتكرار الكلمة، ومعنوي بألفاظ مثل كلّ ونفس مضافة إلى ضمير مطابق.","M":["اللفظي: تكرار مباشر للكلمة أو مرادفها","المعنوي: لفظ التوكيد + ضمير يطابق المؤكَّد","التوكيد يتبع المؤكَّد إعرابًا","اذكر نوع التوكيد ثم إعرابه"],"X":"عندما نريد أن نؤكد معنى نكرر الكلمة، مثل «الأنانية الأنانية عدو»، وهذا توكيد لفظي. أو نستعمل كلمة مثل «كلّها» أو «نفسها» ونربطها بضمير يرجع إلى الكلمة المؤكَّدة، وهذا توكيد معنوي. وفي الحالتين تأخذ كلمة التوكيد نفس إعراب ما قبلها.","EX":[["ميّز نوع التوكيد وأعرب: الأنانية الأنانية عدو للمجتمع.","الأنانية الأولى: مبتدأ مرفوع. الأنانية الثانية: توكيد لفظي مرفوع وعلامة رفعه الضمة. النوع: لفظي."],["أعرب «جميعها»: السعي في قضاء حوائج الناس يمحو الذنوب جميعها.","الذنوب: مفعول به منصوب. جميعَها: توكيد معنوي منصوب وعلامة نصبه الفتحة. الهاء: ضمير متصل مبني في محل جر مضاف إليه."],["أعرب «نفسها»: قرأتُ القصة نفسَها.","نفسَها: توكيد معنوي منصوب لأنه تابع للقصة المنصوبة. الهاء: ضمير متصل في محل جر مضاف إليه. مطابق للمؤكَّد في النوع والعدد."]]},{"m":3,"w":3,"t":"الظاهرة اللغوية: الجملة البسيطة والجملة المركّبة","pg":"ص 64","i":"🧩","B":[["الجملة البسيطة",["كل عناصرها مفردة","مثل: الفقر داء قاتل","ليس فيها جملة داخل جملة"]],["الجملة المركّبة",["أحد عناصرها جملة فعلية أو اسمية","مثل: الفقير يشكر من يعطيه","الجملة الفرعية قد تكون صفة أو حالًا أو خبرًا"]],["مثال الكتاب",["صفة مفردة (يد جابرة): بسيطة","صفة جملة (يد تجبره): مركبة","حال مفردة (شاكرة) مقابل حال جملة (وأنا شاكرة)"]],["التحويل",["المفرد يصبح جملة: جابرة ← تجبره","الجملة تصبح مفردًا: تساند ← مساندة","المعنى باقٍ والتركيب يتغير"]],["كيف أميّز؟",["أحدد الخبر والصفة والحال","هل هي كلمة أم جملة؟","إن وُجدت جملة داخل الجملة فهي مركبة"]],["أخطاء شائعة",["اعتبار الجملة طويلة مركّبة دائمًا","نسيان أن الحال والصفة قد تكونان جملة","الخلط بين تعدد المفردات وتركيب الجملة"]]],"K":"الجملة بسيطة إذا كانت عناصرها مفردة، ومركّبة إذا كان أحد عناصرها جملة فعلية أو اسمية.","M":["اسأل: هل في الجملة عنصر هو جملة؟","الصفة والحال والخبر قد تأتي جملًا","يمكن تحويل المفرد إلى جملة والعكس","علّل دائمًا بذكر العنصر الجملة"],"X":"إذا كانت كل أجزاء الجملة كلمات فردية فهي بسيطة. وإذا كان أحد أجزائها جملة كاملة، كأن نقول «يد تجبره» بدل «يد جابرة»، فهي مركبة. كأننا نضع جملة صغيرة داخل الجملة الكبيرة.","EX":[["ميّز: التبرع عظيم الفوائد. / الله في عون العبد ما دام العبد في عون أخيه.","الأولى بسيطة: مبتدأ وخبر مفردان. الثانية مركبة: «ما دام العبد في عون أخيه» جملة. فالثانية مركبة."],["حوّل إلى مركبة: المجتمع بحاجة إلى مؤسسات خيرية.","نضيف صفة جملة. المجتمع بحاجة إلى مؤسسات خيرية تساند جهود الدولة. فصارت مركبة."],["حوّل إلى بسيطة: الجمعيات تساعد من يحتاج.","نبدّل الجملة الموصولة بمفرد. الجمعيات تساعد المحتاج. فصارت بسيطة."]]},{"m":3,"w":4,"t":"الإنتاج الكتابي: اختيار النمط والموضوع وجمع الموارد","pg":"ص 53","i":"📝","B":[["اختيار النمط",["الهدف كتابة قصة","أنماط مقترحة: السرد، السرد مع الوصف، التفسير مع الوصف، الوصف مع التوجيه","أبرّر اختياري: السرد مع الوصف مناسب للقصة"]],["اختيار الموضوع",["التضامن الإنساني، مساعدة المحرومين","الطفولة المسعفة، رعاية المسنين","يوم التبرع بالدم، اليوم الوطني لذوي الاحتياجات الخاصة"]],["جمع الموارد",["طريقة 1: معلومات عن موضوعي","طريقة 2: نصوص وخطابات من النمط الذي سأكتب به","الأولى تعطيني المعارف والثانية طريقة البناء ومؤشراته"]],["مصادر القراءة",["المكتبة المنزلية والمدرسية ومكتبة الحي","مواقع الإنترنت","أنظّم ما أقرؤه: مصدره ومجاله الثقافي وجنسه الأدبي"]],["الخطوات",["أحدد النمط والموضوع","أجمع المعلومات والنماذج","أبرر اختياري وأناقشه مع زملائي"]]],"K":"قبل الكتابة أختار النمط والموضوع وأبرر اختياري، ثم أجمع معارف عن الموضوع ونماذج عن النمط.","M":["اختر موضوعًا قريبًا من تجربتك وبرّر اختيارك","اجمع المعلومات من أكثر من مصدر","اقرأ نصوصًا من النمط نفسه لتتعرف مؤشراته","دوّن ما جمعت في جدول منظم"],"X":"قبل أن تكتب قصتك فكّر في نوع الكتابة: هل تحكي أحداثًا أم تصف أم تشرح؟ ثم اختر موضوعًا يهمك مثل مساعدة المحتاجين. بعدها اقرأ عن الموضوع، واقرأ قصصًا أخرى لتتعلم كيف تُبنى. هكذا تبدأ الكتابة وأنت جاهز.","EX":[["اختر نمطًا لقصة عن التبرع بالدم وبرّر.","النمط: السرد مع الوصف. السرد لتتابع الأحداث. الوصف لحالة المريض والمستشفى. فهما يناسبان القصة."],["كيف تجمع موارد موضوع «رعاية المسنين»؟","أبحث عن معلومات عن حاجات المسنين. أقرأ قصة أو مقالة عن الموضوع. أسجّل المصدر والمجال والجنس الأدبي."]]},{"m":3,"w":4,"t":"الإنتاج الكتابي: كتابة الخطاب التوجيهي (التضامن)","pg":"ص 59، 65","i":"📣","B":[["ما أوفّره قبل الكتابة",["عناصر الموضوع المستهدف","عناصر وصفية عن الموضوع","عناصر حجاجية للإقناع ومؤشرات النمط التوجيهي"]],["نموذج محمود شلتوت (ص 59)",["خطاب من «من توجيهات الإسلام»","يدعو إلى الرحمة والإحسان لمصلحة الفرد والوطن","يقنع بأن الإحسان يزيل الأحقاد ويجلب الطمأنينة"]],["مؤشرات النمط التوجيهي",["النداء: أيها الأغنياء، أيها السعداء","النفي ثم الاستدراك: لست أدعوكم... ولكنني","الأمر: هلمّوا، ارحموا، والحجة بجمل خبرية"]],["خطة الكتابة",["تمهيد وصفي للموضوع","توجيه يعتمد الإقناع والتأثير","خاتمة تؤكد ضرورة العمل بالتوجيهات"]],["شبكة ضبط الإنتاج (ص 65)",["خطاب توجيهي في موضوع التضامن الإنساني","النداء وضمائر المخاطب وجمل طلبية والأمر والنهي","سلامة التراكيب والضوابط وعلامات الوقف والعرض"]]],"K":"الخطاب التوجيهي يبدأ بتمهيد وصفي ثم توجيه مقنع بالنداء والأمر والحجج، ويُختم بالتأكيد على العمل.","M":["ناد المخاطَبين وخاطبهم بضمير المخاطب","استعمل الأمر والنهي والاستفهام","أقنع بحجج: ديني أو وطني أو إنساني","اختم بالحث على التنفيذ ثم راجع بالشبكة"],"X":"الخطاب التوجيهي كلمة تقنع بها الناس بفعل الخير. تبدأ بوصف المشكلة ثم تناديهم وتطلب منهم العمل وتشرح لهم فوائده. وفي النهاية تؤكد أنه يجب أن يبدؤوا فورًا. وبعد الكتابة تراجع نصك بالأسئلة التي في الشبكة.","EX":[["من نص شلتوت: ما نوع مؤشرات «أيها الأغنياء»؟","هذه عبارة نداء. النداء مؤشر للنمط التوجيهي. يخاطب المرسل بها جمهوره."],["ضع خطة لخطاب يدعو إلى حملة تضامنية في المدرسة.","المقدمة: وصف حال المحتاجين. العرض: ندائهم وأمرهم بالمساعدة مع حجج. الخاتمة: التأكيد على المشاركة الفورية."]]},{"m":3,"w":5,"t":"الإدماج: وضعية تقويم المقطع 3","pg":"ص 66","i":"🎯","B":[["الإنتاج الشفوي: السياق",["اليوم العالمي للأشخاص ذوي الاحتياجات الخاصة","جمعية تنظم يومًا تحسيسيًّا في مدرستك","دُعيت لإلقاء كلمة مقنعة ومؤثرة"]],["الإنتاج الشفوي: التعليمة",["أنت تحضّر شريط فيديو بلا صوت","توجّه الحاضرين إلى دمج هذه الفئة","في الجماعات والعلاقات اليومية"]],["الإنتاج الكتابي: السياق",["أنشأتم جمعية مدرسية لمساعدة التلاميذ المحتاجين دراسيًّا","تريدون جذب زملاء آخرين إلى العمل الخيري"]],["الإنتاج الكتابي: التعليمة",["اكتب موضوعًا منسجمًا لا يقل عن أحد عشر سطرًا","يعرض نشاطات الجمعية عبر الفيديو","هدفه التأثير والإقناع بالانخراط في التطوع"]],["المنهج",["نمط توجيهي يدعمه الوصف والتفسير","مقدمة وصفية ثم عرض بحجج ثم خاتمة","أقيّم عملي بشبكة التقويم الذاتي التي يقترحها الأستاذ"]]],"K":"في وضعية الإدماج أكتب وأتكلم بنمط توجيهي مقنع: وصف للموضوع، نداء وأمر وحجج، ثم خاتمة تحث على العمل.","M":["اقرأ السياق والتعليمة جيدًا وحدد المطلوب","اعتمد النداء والأمر وضمائر المخاطب","قدّم حجة واحدة على الأقل في كل فقرة","راجع اللغة وعلامات الوقف والعدد المطلوب من الأسطر"],"X":"في هذه الوضعية تستعمل ما تعلمته في المقطع: تتكلم أولًا عن دمج ذوي الاحتياجات الخاصة، ثم تكتب نصًّا طويلًا لتدعو زملاءك إلى جمعية خيرية. الأهم أن تبدأ بوصف الموضوع ثم تقنع الجمهور بالأمر والنداء والحجج. وفي النهاية تراجع كتابتك بالشبكة.","EX":[["ضع خطة للكلمة الشفوية عن دمج ذوي الاحتياجات الخاصة.","المقدمة: تحية والتذكير باليوم العالمي. العرض: وصف حال هذه الفئة وحججها: حقهم في المشاركة وفائدة ذلك للجميع. التوجيه: ناد زملاءك وادعهم إلى إشراكهم. الخاتمة: الحث على البدء الآن."],["اكتب مقدمة لنص دعوة إلى الانخراط في الجمعية المدرسية.","أيها الزملاء الأعزاء، كثير من تلاميذ مدرستنا يحتاجون إلى من يأخذ بيدهم دراسيًّا. وقد أنشأنا جمعية لمساعدتهم. هلمّوا إلى الانضمام إليها."]]},{"m":4,"w":1,"t":"فهم المنطوق: مفاخر الأجناس (الفهم والتحليل)","pg":"ص 68-69","i":"🎧","B":[["الموضوع",["خطاب عن افتخار الشعوب بأجناسها وأقوامها","يسأل: هل يحق لشعب أن يفخر بنفسه؟","يقارن أسس الفخر قديما وحديثا"]],["أسئلة التهيئة",["من يحق له الافتخار ومن لا يحق؟","ما موقف الكاتب من أسس الفخر؟","عبّر عن رأيك مؤيدا أو معارضا مع التعليل"]],["أسئلة بعد الاستماع",["هل الفخر بالأقوام سلوك قديم أم حديث؟","ما الطبيعي وما الغريب في فخر الشعوب؟","ما موقف العالم النمساوي فريدريك هرتز؟"]],["تحليل الجزء الأول",["الفقرة الأولى: الفخر قديم، ويُبرَّر بالتعليل","ثم موقف مشروط: لا غرابة إذا وُجدت أسباب القوة","ثم اعتراض: الغريب أن يشيع عند ضعفاء بلا قوة"]],["نمط الخطاب",["النمط الحجاجي: مواقف مدعومة بالتعليل والشرط والاستشهاد","المؤشرات: التعليل، الشرط، الشاهد"]],["الروابط المنطقية",["الفاء للتعليل","إذا للشرط","لكنّ الاستدراكية للاعتراض","الواو للربط وثم للترتيب والتراخي"]]],"K":"الخطاب حجاجي: يعرض مواقف ويدعمها بالتعليل والشرط والاستشهاد، ويستعمل روابط منطقية كالفاء وإذا ولكنّ.","M":["استمع جيدا وسجّل الفكرة الأساسية وموقف صاحب الخطاب","حدّد ما يؤيده وما يعارضه","ابحث عن الروابط: فاء، إذا، لكنّ","علّل رأيك بحجة لا بمجرد الإعجاب"],"X":"الخطاب يناقش فكرة أن شعبا ما أفضل من غيره بسبب جنسه. صاحبه يرى الفخر قديما ويقبله إذا كانت وراءه قوة حقيقية، لكنه يعترض على من يفخر وهو ضعيف. ونعرف أن النمط حجاجي لأن الكاتب يعطي رأيه ويقدّم أسبابه.","EX":[["ما النمط في الجزء الأول وما مؤشراته؟","نمط حجاجي. المؤشرات: إصدار مواقف مدعومة بالتعليل (فما من جيل...) والشرط (إذا سوّغتها...) والاستشهاد."],["ما دلالة «لكنّ» و«الفاء» في الخطاب؟","لكنّ رابط استدراكي يفيد الاعتراض، والفاء رابط منطقي يفيد التعليل. كلاهما من الروابط المعنوية التي تقوّي الحجاج."]]},{"m":4,"w":1,"t":"فهم المنطوق: مفاخر الأجناس (بنية الخطاب وأنماطه)","pg":"ص 74-75، 80-81","i":"🗣️","B":[["بنية الخطاب",["فقرة 1: فخر الأجناس قديم؛ موقف مؤيد ثم معارض","فقرة 2: حقائق تاريخية عن المصريين واليونان والأوربيين","فقرة 3: العلم الحديث صبغة لخرافة قديمة"]],["حجج أصحاب التفوق",["قالوا إن العلم الحديث صادق شريف","فضّلوا الأوربيين على غيرهم","ادّعوا تفاوتا بين الأجناس لا يُدرَك"]],["موقف صاحب الخطاب",["يفنّد دعواهم بمسلّماتهم نفسها","أساس المعتقد خرافي ألبس ثوب العلم","مزايا الشعوب ونقائصها ليست حكرا على شعب"]],["تعدد الأنماط",["السرد التاريخي: شواهد عن المصريين واليونان","الوصف: الحديث عن أهمية العلم وصدقه","الحجاج: رفض موقف علمي بموقف علمي"]],["الحوار داخل الخطاب",["نقل قول هرتز لعلماء الأجناس المتعصبين","هو شاهد وبرهان يدعم الحجاج"]],["العلاقة بين الأنماط",["الحجاج هو النمط الغالب","السرد والوصف والحوار أنماط خادمة له"]]],"K":"النمط الغالب في الخطاب حجاجي، وتخدمه أنماط أخرى (سرد ووصف وحوار) تقدّم الشواهد والبراهين.","M":["صنّف الحجج: بديهيات، مسلّمات، براهين عقلية، شواهد","اربط كل موقف بوسيلته: تعليل أو شرط أو استشهاد","اسأل: لماذا أُدخل هذا النمط؟ للتدعيم لا للزينة","لخّص بترتيب: الموقف المعروض ثم الموقف المعبَّر عنه"],"X":"الكاتب يعرض رأي من يفتخرون بأجناسهم ثم يهدمه. وحين يروي تاريخ المصريين واليونان أو ينقل كلام العالم هرتز فهو لا يحكي فقط، بل يستعمل ذلك دليلا. فالسرد والحوار هنا جنود في خدمة الحجاج.","EX":[["لماذا أُدخل السرد التاريخي في النص الحجاجي؟","لأن الوقائع التاريخية شواهد تؤكد الموقف. وهي تبيّن أن كل أمة افتخرت بنفسها في عصرها. فالسرد خادم والحجاج غالب."],["مثّل شبكة التحليل: ما الموقف المعروض والمعبَّر عنه؟","الموقف المعروض: التفوق العرقي مؤسَّس على العلم الحديث. المعبَّر عنه: هو خرافة قديمة بثوب جديد. الأداة: الاستشهاد والتعليل. النمط: حجاجي."]]},{"m":4,"w":2,"t":"فهم المكتوب: من معتقدات الهنود","pg":"ص 70-71","i":"📜","B":[["التعريف بالنص",["الكاتب: أحمد أمين (1886-1954)، أديب مصري","من كتابه «ضحى الإسلام» الجزء الأول، بتصرف","ينقل عن العالم البيروني وصفه للهنود"]],["الفكرة العامة",["عرض معتقدات الهنود الدينية","أبرزها تناسخ الأرواح وخصوصيتها عند الهند"]],["أفكار النص",["وصف البيروني الهنود بالإعجاب بأنفسهم والاستخفاف بغيرهم","التناسخ علامة النحلة الهندية، كالإخلاص للمسلمين","الروح باقية تنتقل من بدن إلى بدن طلبا للكمال","الثواب والعقاب مرتبطان بالتناسخ"]],["المعجم",["الازدراء: الاستخفاف والاحتقار","ينتحله: ينتسب إليه ويدين به","خَلِق: صار باليا","تناسخ الأرواح: انتقالها بين الأجسام بعد الموت"]],["نمط النص",["يتنوع بين التفسير والوصف، ويغلب التفسير","الوصف يخدم التفسير","هدفهما تعريف موضوعي حيادي بالفكرة"]],["الاتساق والانسجام",["لكل نص روابط تربط الفقرات","كلمات بدايات الفقرات تؤدي هذا الدور"]]],"K":"النص من نمط تفسيري يخدمه الوصف، وهدفه عرض معتقد الهنود في تناسخ الأرواح عرضا موضوعيا حياديا.","M":["حدّد النمط الغالب ثم الخادم","استخرج مؤشرات التفسير: التعريف والشرح والتعليل","ابدأ الفقرات بروابط تضمن الانسجام","قارن المعتقدات دون إصدار أحكام جارحة"],"X":"الكاتب ينقل لنا ما رواه البيروني عن الهنود. أهم ما عندهم أن الروح لا تموت بل تنتقل من جسد إلى جسد حتى تتحسن وتصل إلى الكمال. وهم يربطون الجنة والنار بهذا الانتقال. الكاتب يشرح ولا يحكم، فلذلك النمط تفسيري.","EX":[["ما علاقة التناسخ بالثواب والعقاب عند الهنود؟","جعلوا جهنم وسيلة لتمييز الخير من الشر. فالروح غير المستحقة للثواب تنتقل بين النبات والحيوان وتتردد حتى تستحق الثواب، ثم تنجو."],["ما النمط الغالب على النص؟ علّل.","النمط التفسيري. لأن الكاتب يعرّف المعتقد ويشرح كيفية انتقال الأرواح وأسبابه. والوصف خادم له."]]},{"m":4,"w":2,"t":"فهم المكتوب: الشعب الياباني","pg":"ص 76-77","i":"🇯🇵","B":[["التعريف بالنص",["الكاتب: أنيس منصور (1924-2011)، صحفي وأديب مصري","من كتاب «حول العالم في 200 يوم»، بتصرف","النص من أدب الرحلات"]],["الفكرة العامة",["إعجاب الكاتب بالشعب الياباني وحضارته وذوقه","وداع اليابان بعبارة «سايونارا»"]],["أفكار النص",["رأى طوكيو ليلا جميلة بإعلاناتها وألوانها","كان يظنها بلدا صغيرا فتبيّن له خطأ ذلك","اليابان عملاق يتحفّز ليقفز إلى الأمام","الأحياء الصغيرة والمطاعم النظيفة فيها حياة"]],["الفكرة القديمة والجديدة",["كان يتصور شعبا ضئيل الحجم يأكل في أطباق صغيرة","تغيرت فكرته بعد أن شاهد واقعا مختلفا","دافع عنها بشواهد واقعية رآها بعينه"]],["الأسلوب والمعجم",["فيه مرح وسخرية وعاطفة إعجاب كبيرة","الجيشا: فتيات فنانات في الغناء والاستعراض","ضمير «أنت» يشرك القارئ ويثير انتباهه"]],["النمط",["وصف يخدمه السرد","مؤشرات الوصف: النعوت والتشبيه وأفعال الحال","شواهد واقعية تدعم الفكرة الجديدة"]]],"K":"أنيس منصور وصف اليابان وصفا معجَبا، وتغيّرت فكرته عنها من بلد صغير إلى عملاق يتحفّز، مدعّما ذلك بما شاهده.","M":["اكتشف وصف الشعب في النص ثم صنّفه","اربط بين الفكرة القديمة والفكرة الجديدة","لاحظ توظيف الضمائر والروابط للاتساق","استخرج عبارات السخرية والإعجاب بدقة"],"X":"الكاتب سافر إلى اليابان وهو يظنها بلدا صغيرا، فوجدها بلدا كبيرا متقدما وجميلا. أعجب بنظافته وألوانه وناسه. ثم ودّعه بحزن وحب قائلا إن شمسه أشرقت في نفسه ولن تغرب. فالنص يحكي رحلة ويصف شعبا ويحترمه.","EX":[["كيف شبّه الكاتب اليابان اليوم؟","شبّهها بعملاق يخطو إلى الوراء فيظنه الناس يتراجع، لكنه في الحقيقة يتحفّز ليقفز إلى الأمام. وهي صورة تدل على القوة والتقدم."],["ما الدلالة التي يضيفها ضمير المخاطب «أنت» إلى النص؟","يشرك القارئ في التجربة ويقرّبه من الكاتب. ويثير انتباهه ويجعل النص أكثر حيوية وإقناعا."]]},{"m":4,"w":2,"t":"فهم المكتوب: أنا الإفريقي","pg":"ص 82-83","i":"🌍","B":[["التعريف بالنص",["الشاعر: محمد الفيتوري (1936-2015) من السودان","نشأ في مصر ودرس بالأزهر واشتغل بالصحافة والدبلوماسية","يُعدّ من رواد الشعر الحديث، وهو «عاشق إفريقيا»"]],["الفكرة العامة",["الإفريقي يعرّف بنفسه ويدعو شعوب العالم إلى السلام","يفخر بحريته وأرضه وتضحيات أجداده"]],["أفكار القصيدة",["نداء للأخ في الشرق وفي كل وطن: هل تعرفني؟","ثورة على الوهن والذل وتحطيم قيود الماضي","الأرض ملكه، فيها دفن أجداده وسقاها بدمه","فاسلمي يا إفريقيا لنا: دعاء بالسلام"]],["المعجم",["الدجى: الظلام الحالك","الوهن: الضعف، والبلى: القدم","الدمن: آثار الديار (الأطلال)","أهرقنا: سكبنا، وواريت: أخفيت وسترت"]],["نمط النص",["المفارقة بين ماضي إفريقيا وحاضرها: نمط وصفي سردي","أوصاف الإفريقي اليوم: حر، فلاح، صاحب أرض","نزعة التوجيه: دعوة إلى السلام"]],["الاتساق",["النفي (لم أعد) يربط مقاطع القصيدة","ضمير المتكلم يهيمن على بنائها","أدوات العطف والتكرار تحكم النسج"]]],"K":"القصيدة صوت إفريقي حر يطوي ماضي الذل ويتمسك بأرضه وحريته ويدعو العالم إلى السلام.","M":["لاحظ التقابل بين ماضي الذل وحاضر الحرية","استخرج النفي وضمير المتكلم وبيّن وظيفتهما","ميّز الوصف عن السرد وعن التوجيه","اشرح العبارات بأسلوبك لا بحفظها"],"X":"الشاعر يتكلم بلسان الإفريقي. يقول إنه كسر قيود الخوف والعبودية وأصبح حرا في أرضه التي دفن فيها أجداده وروّاها بدمه. ثم يطلب من إفريقيا أن تبقى سالمة. فالقصيدة تجمع الفخر بالحرية والدعوة إلى السلام.","EX":[["ما الفرق بين ماضي الإفريقي وحاضره في القصيدة؟","الماضي: ذلّ وقيود ووهن وأطلال تبكي. الحاضر: ثورة وحرية وأرض يملكها ويدافع عنها. النمط الذي يبرز المفارقة وصفي وسردي."],["ما وظيفة أسلوب النفي «لم أعد» في القصيدة؟","ينفي صفات الماضي (العبودية والوهن) فيربط الأبيات ببعضها. ويمهّد لإثبات الحرية، فيحافظ على انسجام القصيدة."]]},{"m":4,"w":3,"t":"الظاهرة اللغوية: الجملة الواقعة مفعولا به","pg":"ص 72","i":"✍️","B":[["التعريف",["قد يأتي المفعول به جملة فعلية أو اسمية","وتكون في محل نصب دائما"]],["الحالة الأولى",["أن تكون مقولا للقول","مثل: قال البيروني إن الإخلاص شعار..."]],["الحالة الثانية",["مصدر مؤوّل بأن أو لو المصدريتين","وفعلهما مضارع: تطلب النفس أن تصل"]],["الحالة الثالثة",["مفعول به ثان لظنّ أو إحدى أخواتها","مثل: يظن الهنود الأرواح تتناسخ"]],["خطوات الإعراب",["حدّد الفعل والفاعل","اسأل: ماذا؟ فتجد الجملة","أعربها: في محل نصب مفعول به"]],["أخطاء شائعة",["إعراب الجملة إعراب المفرد بالحركات","نسيان تحديد نوعها: فعلية أم اسمية"]]],"K":"تقع الجملة مفعولا به في ثلاث حالات: مقول القول، المصدر المؤوّل بأن أو لو، والمفعول الثاني لظنّ وأخواتها، وهي في محل نصب دائما.","M":["الجملة لا تظهر عليها علامة إعراب، فنقول: في محل نصب","بعد القول: الجملة مقول القول","ظنّ وأخواتها تنصب مفعولين: الثاني قد يكون جملة","لو المصدرية تأتي بعد أودّ ويودّ"],"X":"عندما نسأل «ماذا قال؟» أو «ماذا يظن؟» قد يكون الجواب كلمة واحدة أو جملة كاملة. إذا كان الجواب جملة فهي مفعول به في محل نصب. مثلا: قال المعلم العلم نور؛ جملة العلم نور هي الشيء المقول.","EX":[["أعرب: يخال الهندوس الأرواح تنتقل من جسد إلى آخر.","يخال: فعل مضارع مرفوع. الهندوس: فاعل مرفوع. الأرواح: مفعول به أول منصوب. جملة «تنتقل من جسد إلى آخر»: فعلية في محل نصب مفعول به ثان. فالجملة مفعول ثان لـ يخال."],["أعرب الجملة المفعول به: أودّ لو أزور اليابان.","أودّ: فعل مضارع مرفوع والفاعل ضمير مستتر. لو: حرف مصدري. أزور: فعل مضارع مرفوع. اليابان: مفعول به. لو والفعل في تأويل مصدر. الجملة «أزور اليابان» صلة لو المصدرية لا محل لها، والمصدر المؤوّل في محل نصب مفعول به."],["أعرب الجملة الواقعة بعد القول: «قال الأستاذ: العلم نور».","قال: فعل ماض مبني على الفتح. الأستاذ: فاعل مرفوع. جملة «العلم نور» اسمية في محل نصب مفعول به لأنها مقول القول. العلم: مبتدأ مرفوع. نور: خبر مرفوع"]]},{"m":4,"w":3,"t":"الظاهرة اللغوية: الجملة الواقعة نعتا","pg":"ص 78","i":"🔎","B":[["تذكير بالنعت",["النعت الحقيقي تابع يصف منعوته","يتبعه في الإعراب والنوع والعدد والتعريف والتنكير"]],["النعت جملة",["قد يكون جملة فعلية: تكاد تسقط","أو اسمية: ليلها منير"]],["شروط الجملة النعت",["منعوتها نكرة","فيها ضمير يعود على المنعوت (رابط)","تتبع منعوتها في الرفع أو النصب أو الجر"]],["أمثلة من النص",["مدينة ليلها منير: اسمية","فناجين تكاد تسقط: فعلية","بلادا لا تعرف الإنجليزية: فعلية"]],["الإعراب",["الجملة في محل رفع أو نصب أو جر","بحسب إعراب المنعوت"]],["أخطاء شائعة",["نعت المعرفة بجملة (تكون حالا)","نسيان الضمير الرابط"]]],"K":"تأتي الجملة نعتا بعد نكرة، وتكون في محل إعراب منعوتها (رفع أو نصب أو جر)، وفيها ضمير يعود عليه.","M":["ابحث عن النكرة قبل الجملة","تأكد من وجود الضمير العائد","اجعل محلها مثل محل المنعوت","بعد المعرفة تكون الجملة حالا لا نعتا"],"X":"النعت عادة كلمة مفردة مثل «كبيرة». لكنه قد يكون جملة كاملة، كقولنا: مدينة ليلها منير. هنا جملة «ليلها منير» تصف المدينة. ونعرف أنها نعت لأن المدينة نكرة ولأن الضمير في «ليلها» يعود إليها.","EX":[["أعرب: القدس مدينة تضمّ أديان السماء.","القدس: مبتدأ مرفوع. مدينة: خبر مرفوع. جملة «تضمّ أديان السماء»: فعلية في محل رفع نعت لمدينة. وفيها ضمير مستتر يعود على المدينة."],["أعرب: في الجزائر شعب يحبّ الضيف.","في الجزائر: جار ومجرور خبر مقدم. شعب: مبتدأ مؤخر مرفوع. جملة «يحبّ الضيف»: فعلية في محل رفع نعت لشعب. والضمير المستتر يعود عليه."],["أكمل بجملة نعتية: الجزائريون شعب ...","الجزائريون شعب يحبّ السلام ويقاوم الظلم. الجملة نعتية لأن «شعب» نكرة، وفي الجملة ضمير مستتر يعود عليه."]]},{"m":4,"w":3,"t":"الظاهرة اللغوية: الجملة الواقعة حالا","pg":"ص 84","i":"🧭","B":[["تذكير بالحال",["اسم مشتق نكرة منصوب","يبيّن هيئة صاحبه وقت الفعل"]],["الحال جملة",["قد تكون فعلية أو اسمية","وهي في محل نصب حال"]],["الرابط",["للجملة الحالية عائد يربطها بصاحب الحال","ضمير متصل أو مستتر، أو واو الحال، أو كلاهما"]],["أمثلة",["تحدى الأفارقة الزمن وقد ثبتوا: اسمية أو فعلية","سنهديها لأحفادنا وهي حرة: اسمية"]],["مقارنة",["الحال المفردة: ثابتين","الحال الجملة: وقد ثبتوا"]],["أخطاء شائعة",["نسيان تحديد صاحب الحال","إغفال الرابط (الواو أو الضمير)"]]],"K":"تأتي الحال جملة فعلية أو اسمية في محل نصب، ويربطها بصاحبها عائد هو ضمير أو واو الحال أو هما معا.","M":["اسأل: كيف؟ يأتيك الجواب حالا","حدّد صاحب الحال أولا","ابحث عن الرابط في الجملة الحالية","الجملة الاسمية الحالية تبدأ غالبا بواو الحال"],"X":"الحال تجيب عن السؤال: كيف؟ فإذا أردنا أن نقول كيف قاوم الأفارقة، قلنا: وهم صامدون. هذه جملة كاملة وقعت حالا، وهي مربوطة بالأفارقة بالواو والضمير هم.","EX":[["أعرب: قاوم الأفارقة الظلم وهم صامدون.","قاوم: فعل ماض. الأفارقة: فاعل مرفوع. الظلم: مفعول به. الواو: واو الحال. هم: مبتدأ ضمير منفصل. صامدون: خبر مرفوع. جملة «هم صامدون» اسمية في محل نصب حال. صاحب الحال الأفارقة، والرابط الواو والضمير هم."],["حوّل الحال المفردة إلى جملة: يقيم الناس في نيويورك شاعرين أنها مدينتهم.","نحوّلها: يقيم الناس في نيويورك وهم يشعرون أنها مدينتهم. جملة «هم يشعرون» حال اسمية في محل نصب. صاحبها الناس، والرابط الواو والضمير."],["عيّن الحال الجملة: زار السياح إسطنبول ورجعوا وقد اكتشفوا جمالها.","الحال: «وقد اكتشفوا جمالها». جملة فعلية في محل نصب حال. صاحب الحال: واو الجماعة في رجعوا. والرابط: الواو وواو الجماعة."]]},{"m":4,"w":4,"t":"الإنتاج الكتابي: اختيار النمط والموضوع وجمع المعلومات","pg":"ص 73","i":"🧩","B":[["الهدف",["كتابة نص يغلب عليه العرض والإرشاد","موضوعه شعوب العالم وعلاقاتها"]],["اختيار النمط",["تفسيري مع حجاجي، أو وصفي مع حجاجي","سردي مع وصفي، أو حواري مع توجيهي","برّر اختيارك"]],["اختيار الموضوع",["الهوية الوطنية والتفتح على العالم","التبادل الثقافي بين الشعوب والتعرف عليها","مساندة الشعوب المستعمَرة ومناهضة العنصرية","حق الشعوب في تقرير مصيرها"]],["البحث على الإنترنت",["حدّد الموضوع والنمط ثم اختر محرك بحث","افحص النتائج وانتق الدقيق منها","حدّد عناصر الموضوع ثم رتّب المعلومات"]],["تصفية المعلومات",["صفِّ ولخّص مع أعضاء الفوج","استعن بالأستاذ"]],["تنويع المطالعة",["المصادر: مكتبة منزلية أو مدرسية أو الإنترنت","الأجناس: رسالة، مقالة، أدب رحلات، خطاب"]]],"K":"الإنتاج الكتابي يبدأ باختيار النمط والموضوع ثم بحث منظّم يُصنِّف المعلومات ويلخصها.","M":["اختر نمطا يناسب هدفك","حدّد عناصر الموضوع قبل البحث","نظّم البحث: موضوع، محرك، فرز، تحديد عناصر، تصفية","ناقش اختياراتك مع زملائك"],"X":"قبل الكتابة نحتاج إلى فكرة واضحة ومعلومات صحيحة. فنختار موضوعا من القائمة، ونبحث عنه خطوة بعد خطوة في الإنترنت، ثم نختار أدق النتائج ونرتب ما وجدنا ونلخصه مع فوجنا.","EX":[["اختر موضوعا وبرّر اختيارك.","الموضوع: التبادل الثقافي بين الشعوب. السبب: يعرّفنا على عادات غيرنا ويقوي التعارف والسلام. النمط: تفسيري مع حجاجي."],["رتّب خطوات البحث: تلخيص، اختيار محرك، تحديد الموضوع، فحص النتائج.","تحديد الموضوع والنمط. اختيار محرك البحث. فحص النتائج. ثم الفرز والتلخيص."]]},{"m":4,"w":4,"t":"الإنتاج الكتابي: التعريف بالشعوب على منوال أدب الرحلة","pg":"ص 79، 85","i":"🧳","B":[["المطلوب",["كتابة نص يعرّف بشعوب العالم","بالسرد والوصف ومعلومات جغرافية وبشرية","مع إبراز القيم: السلام، التعارف، احترام الآخر"]],["مؤشرات أدب الرحلة",["السرد الواقعي والتتابع الزمني للأحداث","ذكر الأماكن ووصفها بالتفصيل","أفعال ماض مسندة إلى ضمير المتكلم","إبراز الحيّز المكاني والزماني، وقيم الاحترام"]],["خطوات الكتابة",["اختر المكان أو الشعب والمنهج","ابدأ بسرد الرحلة بترتيب زمني","صِف الأماكن والناس ثم عبّر عن مشاعرك","اختم بقيمة إنسانية"]],["شبكة التقويم",["الموصوف يتعلق بمناطق ومدن","النص من أدب الرحلة بتسلسل زمني","النمط ومؤشراته مناسبان للوصف وللحكاية","الضمير مناسب وتوظيف التعلمات اللغوية"]],["الضوابط اللغوية",["احترم المعجم والصرف والإملاء والتركيب","عبّر عن مشاعر مناسبة"]],["نص نموذجي",["مقاطع عن الصين وإسطنبول ومراكش وبلغراد","تجمع الحكاية بالوصف والطرافة"]]],"K":"نص أدب الرحلة سرد واقعي بضمير المتكلم وماضي الأفعال، يتخلله وصف دقيق للأمكنة وتعبير عن المشاعر وقيم الاحترام.","M":["اكتب بضمير المتكلم وبأفعال الماضي","رتّب الأحداث زمنيا وحدّد الأماكن","وظّف النعت والحال جملة في الوصف","راجع النص بشبكة الفوج وصحّح"],"X":"أدب الرحلة هو أن تحكي سفرك كأنك تروي للقارئ ما رأيت وعشت. فتذكر المكان والزمان، وتصف ما شاهدته، وتقول ما شعرت به، وتُظهر احترامك للشعوب التي قابلتها.","EX":[["اكتب فقرة قصيرة من أدب الرحلة.","زرت مدينة قسنطينة صيفا. عبرت جسرا معلقا وشعرت بالدهشة. رأيت شعبا يحب الضيف ويكرمه. وعدت وقد أحببت أهلها. ففي الفقرة: ضمير المتكلم، أفعال ماض، مكان وزمان، وصف بجملة نعتية وحالية."],["كيف تتأكد أن نصك من أدب الرحلة؟","أراجع الشبكة: ذكر مدن وأماكن، تسلسل زمني، ضمير المتكلم، وصف وسرد، مشاعر وقيم. فإن غابت ميزة أعدّلها."]]},{"m":4,"w":5,"t":"الإدماج: وضعية تقويم المقطع 4","pg":"ص 80-81، 86","i":"🏁","B":[["الإنتاج الشفوي: السياق",["زرت مع أسرتك معرضا دوليا للكتاب في بلدك","تعرفت على ثقافات الشعوب عبر دور النشر","استمعت إلى حوارات مع ممثلي الشعوب"]],["الإنتاج الشفوي: التعليمة",["صِف مجريات المعرض لزملائك","قدّم أمثلة عن دور نشر وإنتاجات بلدانها","أبرز ما عرفت من تقاليد الشعوب وثقافاتها"]],["الإنتاج الكتابي: السياق",["اختارتك بلادك للمشاركة في ملتقى برلمانات أطفال العالم","تلقي خطابا باسم بلادك"]],["الإنتاج الكتابي: التعليمة",["نص من خمسة عشر سطرا على الأقل","انشغالات أبناء وطنك ورغبتهم في سلم وأمن وتعارف وتعاون","أمل زوال العنف والاستغلال والظلم"]],["منهج العمل",["حلّل السياق ثم التعليمة وحدّد النمط","اجمع الأفكار ورتبها في خطة","اكتب وراجع بشبكة التقويم الذاتي"]],["خطة نموذجية للخطاب",["مقدمة: تحية وتعريف ببلدك","عرض: الانشغالات ثم الطموحات بحجج","خاتمة: نداء وأمل بالسلم"]]],"K":"في وضعية الإدماج تحلّل السياق والتعليمة، ثم تنتج خطابا شفويا وصفيا وآخر كتابيا حجاجيا موجَّها، مستعملا ما تعلمته من أنماط وظواهر.","M":["اقرأ السياق والتعليمة جيدا قبل البدء","اختر النمط: وصف في الشفوي، حجاج وتوجيه في الكتابي","وظّف الجملة النعتية والحالية والمفعول به الجملة","احرص على عدد الأسطر وراجع بالشبكة"],"X":"في هذه الوضعية يُطلب منك أن تتكلم عن معرض كتاب زرته، وأن تكتب خطابا يعبر عن أحلام أطفال بلدك. فتبدأ بجمع أفكارك، ثم ترتبها، ثم تكتب بلغة صحيحة وبنمط مناسب.","EX":[["ضع مخططا للخطاب الكتابي.","المقدمة: أحييكم باسم أطفال الجزائر. العرض: انشغالاتنا (التعليم والصحة واللعب) ثم رغبتنا في السلم والتعارف. الحجة: الحروب تحرم الطفل من طفولته. الخاتمة: ندعو إلى عالم بلا عنف ولا ظلم."],["ابدأ الجواب الشفوي عن المعرض.","شاركت مع أسرتي في معرض دولي للكتاب. زرت جناح دار نشر يابانية فرأيت كتبا عن ثقافة بلدها وتقاليده. وسمعت حوارا مع ناشر إفريقي عن تراث بلاده. ثم أختم بما استفدته من تعارف الشعوب."]]},{"m":5,"w":1,"t":"فهم المنطوق: اللغة العربية وتحديات التقدم العلمي والتكنولوجي","pg":"ص 88-89","i":"🎧","B":[["المصدر والموضوع",["حوار صحفي مع العالم الجزائري الدكتور عبد الرحمن حاج صالح","الموضوع: العربية والهوية والعلم والمعلوماتية"]],["أسئلة الصحفي",["يسأل عن علاقة اللغة بالهوية","يسأل عن حضور العربية في المعلوماتية","يطلب بيان الفرق بين أمرين"]],["أفكار الباحث",["من يعيش بلغة ليل نهار فهو من أهلها","معرفة اللغات الأجنبية لا علاقة لها بفقدان الهوية بل بالانفتاح","على العربية أن تؤدي دورها في الحياة اليومية","الاكتشافات في الطب صارت يومية، فلا بد من لغات أخرى"]],["أسلوب المقارنة",["يقارن بين طرفين ليوضح فكرة","نعيد صياغة المقارنة ثم نستنتج الفكرة"]],["نمط الخطاب ومؤشراته",["النمط الغالب: الحوار","أسئلة تتبعها أجوبة","ضمائر المتكلم والمخاطب","علامات الوقف: التنصيص والاستفهام والشرطة"]]],"K":"المقابلة الصحفية نص حواري يغلب عليه نمط الحوار، وقد يتخلله سرد وإخبار وتفسير وحجاج بحسب موقف الحديث.","M":["أستمع إلى الخطاب كله ثم أحدد من يتكلم: السائل أم المجيب","أميز الجملة الاستفهامية من الإخبارية والمنفية من المثبتة","أبحث عن الضمائر وعلامات الوقف لأعرف النمط","في المقارنة أحدد الطرف الأول والطرف الثاني ثم الفكرة"],"X":"في هذا الحوار يسأل صحفي عالما جزائريا كبيرا عن اللغة العربية والعلم. العالم يشرح أن العيب ليس في اللغة بل في أهلها، وأن تعلم اللغات الأخرى لا يعني التخلي عن الهوية. نعرف أن النص حوار لأن فيه أسئلة وأجوبة وضمائر المتكلم والمخاطب.","EX":[["صنّف الجمل: ما الفرق بينهما؟ . فهذا ليس من أهلها . لا بد أن تؤدي ما عليها في الحياة اليومية. ونسبها إلى صاحبها.","الجملة الأولى استفهامية وصاحبها الصحفي السائل. الثانية إخبارية منفية وصاحبها الدكتور المجيب. الثالثة إخبارية مثبتة وصاحبها الدكتور. الأسئلة للسائل والإجابات للمجيب."],["استخرج مؤشر النمط من فكرة أن العيب في أهل اللغة وقصة أجانب بجاية.","نذكر أولا الدعوى: العيب في أهل اللغة لا فيها. ثم الحجة: مثال تاريخي لأجانب جاؤوا إلى بجاية ليتعلموا العربية. ثم النتيجة: لا نلوم اللغة بل أنفسنا. المؤشرات: دعوى وحجة ونتيجة، فالنمط حجاجي داخل الحوار."]]},{"m":5,"w":1,"t":"فهم المنطوق: بنية الحوار الصحفي وعلاقة الأنماط","pg":"ص 94-95، 100-101","i":"🎙️","B":[["بنية الخطاب",["فقرة تمهيدية يقدمها الصحفي ثم نص الحوار","التمهيد يعرف بسياق المقابلة وبالضيف"]],["الأنماط في الخطاب",["التمهيد وصفي أو سردي ووظيفته التعريف بالسياق","الحوار في الأسئلة والأجوبة","التوجيهي: الصحفي يطلب المعلومات","التفسيري: الباحث يقدم معلومات جديدة"]],["العلاقة بين الأنماط",["الحوار هو النمط الغالب ومحرك الخطاب","الأنماط الأخرى تخدمه وتتعاون معه","وجود أكثر من نمط سببه الموقف والمقام"]],["القيم المستخلصة",["قيمة تاريخية: مجيء الأجانب إلى بجاية لتعلم العربية","قيمة حضارية: الحضارة تجذب الناس إلى لغتها","قيمة إنسانية: الإنسان هو الثروة الحقيقية"]],["الإنتاج الشفوي",["أجري مقابلة مع زميل وأحكي فيها الخطاب","تمهيد ثم نص الحوار ثم خاتمة بشكر الضيف"]]],"K":"يدير الحوار الصحفي المقابلة ويدفع الباحث إلى الشرح، وتتكامل الأنماط بحسب المقام لتبلغ الغاية من الاستجواب.","M":["أميز التمهيد عن نص الحوار قبل تحديد النمط","أحدد وظيفة العبارة: طلب معلومات أم تقديم معلومات","أذكر قيمة واحدة لكل فقرة أسمعها","في الخاتمة أذكر نتائج الحوار وأشكر المحاور"],"X":"المقابلة الصحفية تبدأ بمقدمة يكتبها الصحفي ليعرفنا بالضيف، ثم يأتي الحوار نفسه. في الحوار يسأل الصحفي ليستخرج المعلومات، ويجيب الباحث فيشرح ويفسر. الحوار هو الخيط الذي يربط الأنماط كلها.","EX":[["ما نمط عبارة: ما رؤيتكم لعلاقة اللغة بالهوية؟ ووظيفتها؟","العبارة سؤال من الصحفي. نمطها توجيهي لأنها تطلب معلومات. وظيفتها الدلالية استثارة المعلومات لدى الباحث المحاور."],["ما نمط عبارة: الاكتشافات صارت يومية في الطب؟ ولماذا؟","العبارة من كلام الباحث. تقدم معلومة جديدة وتبرر بها فكرته. نمطها تفسيري ووظيفتها تقديم معلومات."],["ضع مخططا لمقابلة صحفية مع زميل.","التمهيد: أعرف بالزميل وبموضوع المقابلة. نص الحوار: أسئلة متدرجة وأجوبة مفسرة. الخاتمة: ألخص النتائج وأشكر الزميل."]]},{"m":5,"w":2,"t":"فهم المكتوب: الأنترنت","pg":"ص 90-91","i":"🌐","B":[["بطاقة النص",["العنوان: الأنترنت","الكاتب: يوسف حسين","المصدر: مجلة الجيل، عدد جانفي 1997"]],["الفكرة العامة",["الأنترنت شبكة عالمية تربط الناس ببعضهم عبر الكمبيوتر","نص تفسيري يعرف بالأنترنت ونشأتها ووظائفها وأخطارها"]],["تسلسل الأفكار",["التعريف: شبكة الشبكات الإلكترونية","ما يلزم للاشتراك: كمبيوتر ومودم وخط هاتف","عدد المستعملين وزيادتهم الشهرية الكبيرة","النشأة: فكرة سنة 1968 وانطلاقة فعلية سنة 1993","خوف الحكومات من عجزها عن المراقبة"]],["مفردات",["الكومبيوتر: آلة إلكترونية لمعالجة البيانات","المودم: جهاز يربط الحاسوب بالخط","المعلوماتية: مصطلح حديث مشتق من المعلومات"]],["النمط ومؤشراته",["تفسيري: تعريف وأمثلة وتفصيل","سردي: تواريخ وأحداث","وصفي: شبكة تلف العالم كالسلة الكبيرة","روابط كثيرة وتكرار كلمة أنترنت للتأكيد على المحور"]]],"K":"نص الأنترنت يفسر هذا الاختراع بنمط تفسيري تدعمه أنماط سردية ووصفية، ويربط بين فوائده ومخاوف الحكومات منه.","M":["أحدد المحور: الأنترنت ووظائفها وتأثيرها","التواريخ مؤشر على النمط السردي","التعريف والتفصيل مؤشران على التفسير","أحصي الروابط وأصنفها ثم أمثل لكل رابط","التكرار يضمن انسجام المعنى حول فكرة واحدة"],"X":"يشرح الكاتب ما هي الأنترنت: شبكة ضخمة تجمع المعلومات وتصل الناس بعضهم ببعض. يحكي كيف بدأت فكرتها ومتى انطلقت فعلا، ثم يبين أن بعض الحكومات تخاف منها لأنها لا تستطيع التحكم فيها كليا. تكرار كلمة أنترنت يجعل القارئ لا ينسى موضوع النص.","EX":[["ما الاختراع الذي تناوله النص؟ وما الحدث البارز وماذا تدل التواريخ؟","الاختراع: شبكة الأنترنت. الحدث البارز: ظهور الشبكة العنكبوتية العالمية. التواريخ تدل على النمط السردي وتبين مراحل التطور من فكرة إلى انطلاقة."],["لماذا تخاف حكومات كثيرة من الأنترنت بحسب النص؟","لأن مراقبتها كاملة شبه مستحيلة. ولأن قراصنة المعلوماتية اخترقوا حواسيب مؤسسات كبرى. فتصبح مصدر قلق على الأمن والمعلومات."]]},{"m":5,"w":2,"t":"فهم المكتوب: التقدم العلمي والأخلاق","pg":"ص 96-97","i":"⚖️","B":[["بطاقة النص",["العنوان: التقدم العلمي والأخلاق","الكاتب: محمد مزالي، مفكر ووزير تونسي سابق","المصدر: مجلة الفكر، عدد 1976"]],["الفكرة العامة",["رغم الانتصارات العلمية تعاني الإنسانية أزمة خوف وقلق","العلم وحده لا يكفي، فلا بد من أخلاق وعقيدة توجهه"]],["تسلسل الأفكار",["انتصارات علمية كبيرة في الطبيعة والكيمياء والطب","مخاطر السلاح النووي وسباق التسلح","أصحاب الرأي أن العلم يقود حتما إلى السعادة","الرد: العلم يحتاج إلى ضمير يحسن استعماله"]],["مفردات",["نواميس علمية: قوانين علمية","على شفا جرف هار: على وشك الانهيار","الأساطير: الخرافات البعيدة عن الواقع","العقيدة: التصديق الجازم بالشيء"]],["النمط والقيم",["حجاجي: أطروحة وحجج وروابط منطقية مثل لأن","القيمة: الجمع بين العلم والأخلاق","القصد: إقناع القارئ بخطر علم بلا ضمير"]]],"K":"قيمة العلم في حسن استعماله، ولا يستعمله الإنسان استعمالا سليما إلا إذا اقترن بضمير وأخلاق.","M":["أميز النمط الحجاجي بالدعوى والحجة والرابط المنطقي","أقابل بين هذا النص ونص الأنترنت في القصد والنمط","أستخرج الفكرة والرابط والحجة من الفقرة الأخيرة","أستعمل النمط الغالب لخدمة قصد الكاتب"],"X":"يقول الكاتب إن العلم أنجز أشياء عظيمة لكنه قد يدمر العالم إذا استعمل بسوء، كما في الأسلحة النووية. لذلك لا يكفي أن نتعلم، بل يجب أن نملك ضميرا وأخلاقا نوجه بهما علمنا. فالعلم يعطي القدرة والأخلاق تعطي الاتجاه الصحيح.","EX":[["هل قصد كاتب هذا النص وقصد كاتب نص الأنترنت واحد؟","لا. كاتب الأنترنت يريد التعريف بالاختراع وشرحه. أما مزالي فيريد إقناعنا بضرورة ربط العلم بالأخلاق. فالأول تفسيري والثاني حجاجي في الغالب."],["حلل الفقرة الأخيرة: الفكرة والرابط والحجة.","الفكرة: التأمل في الواقع يساعدنا على تقويم الحالة. الرابط المنطقي: لأن. الحجة: التحدي في الربع الأخير من القرن هو إعادة الروح للإنسان ليتحكم في نفسه."]]},{"m":5,"w":2,"t":"فهم المكتوب: فضل العلم","pg":"ص 102-103","i":"📜","B":[["بطاقة النص",["العنوان: فضل العلم، قصيدة من ثلاثة عشر بيتا","الشاعر: أفلح بن عبد الوهاب الرستمي","توفي سنة 240 هـ، ثالث أئمة الدولة الرستمية بتيهرت"]],["الفكرة العامة",["العلم باق خالد وأهله أحياء بآثارهم","يحث الشاعر على طلب العلم والعمل به"]],["الأبيات 1-6",["العلم يبقي ذكر أهله ولو ماتوا","العلم كالدر النفيس وقيمته عظيمة","اقتباس من السنة: فضل العلم على كثير من العبادة"]],["الأبيات 7-13",["أفعال الأمر: اشدد، صل، اصبر، الطف، جدد","السفر لطلب العلم وزيارة العلماء","احترام المعلم وعدم الاكتفاء بجمع الكتب","العمل بالعلم فضيلة وذخر"]],["الأسلوب والانسجام",["أسلوب خبري يمدح العلم ثم أسلوب إنشائي توجيهي بالأمر","التشبيه: من لا يعمل بعلمه كالعير يحمل كتبا","وحدة الموضوع والموقف والوزن والقافية، وتكرار كلمة العلم"]]],"K":"قصيدة تمدح العلم ثم تنتقل من التقرير إلى التوجيه بأفعال الأمر لتحث على طلبه والعمل به وإكرام أهله.","M":["أنظر إلى تحول الأسلوب عند أفعال الأمر","أستعين بالقاموس لمعاني الغريب مثل المهامه والرحال","أفرق بين تقرير الفضل والنصح والإرشاد","الوزن والقافية دليل انسجام من الخارج، ووحدة الموضوع من الداخل"],"X":"الشاعر يقول إن العلم أفضل ما يتركه الإنسان، فمن مات وعلمه حي بين الناس فهو حي. ثم ينصحنا بأن نسافر لطلب العلم ونصبر ونحترم معلمينا ولا نكتفي بجمع الكتب بل نعمل بما تعلمنا.","EX":[["ما الذي تغير في الكلام ابتداء من البيت السابع؟","بدأ الشاعر يستعمل أفعال الأمر. فانتقل من تقرير فضل العلم إلى نصح وتوجيه. فصار النمط توجيهيا."],["ما فائدة التشبيه في قوله لا تكن جامعا للصحف؟","شبه الشاعر من يجمع الكتب ولا يعمل بها بحمار يحمل كتبا. فائدته التنفير من العلم النظري وربط العلم بالعمل."]]},{"m":5,"w":3,"t":"الظاهرة اللغوية: الخبر المفرد وشبه الجملة والجملة","pg":"ص 92","i":"📝","B":[["القاعدة",["يكون خبر المبتدإ اسما مفردا","أو شبه جملة متعلقة بمحذوف خبر","أو جملة فعلية أو اسمية في محل رفع"]],["أنواع الخبر",["مفرد: الأنترنت شبكة","شبه جملة: الشبكة في كل العالم","جملة فعلية: الأنترنت يغزو العالم","جملة اسمية: الأنترنت منافعه جمة"]],["الإعراب",["المبتدأ مرفوع دائما","المفرد خبر مرفوع بعلامة إعرابه","شبه الجملة جار ومجرور متعلق بمحذوف تقديره كائنة","الجملة في محل رفع خبر"]],["أخطاء شائعة",["القول إن الجملة مرفوعة والصحيح: في محل رفع","اعتبار شبه الجملة خبرا بنفسه والصحيح أنه متعلق بمحذوف"]]],"K":"خبر المبتدإ مفرد أو شبه جملة أو جملة، والجملة تقع في محل رفع خبر.","M":["أسأل: ما الذي تم به المعنى بعد المبتدإ؟","إذا بدأ الخبر بحرف جر أو ظرف فهو شبه جملة","إذا بدأ الخبر بفعل فهو جملة فعلية","إذا بدأ باسم ومعه اسم آخر فقد يكون جملة اسمية"],"X":"المبتدأ كلمة تحتاج إلى خبر يكمل معناها. الخبر قد يكون كلمة واحدة، أو جارا ومجرورا، أو جملة كاملة. وإذا كان جملة فإننا نقول إنها في محل رفع لأنها نائبة عن كلمة مرفوعة.","EX":[["حدد نوع الخبر: الناس في حاجة إلى التواصل . الأنترنت أضاع على الناس زيارة بعضهم . وسائل الاتصال منافعها جمة .","الأولى: في حاجة شبه جملة، جار ومجرور متعلق بمحذوف خبر تقديره موجودون. الثانية: أضاع على الناس زيارة جملة فعلية في محل رفع خبر. الثالثة: منافعها جمة جملة اسمية في محل رفع خبر."],["أعرب: الشبكة في كل العالم.","الشبكة مبتدأ مرفوع بالضمة. في حرف جر. كل اسم مجرور بفي وهو مضاف. العالم مضاف إليه مجرور. الجار والمجرور متعلقان بمحذوف تقديره موجودة وهو خبر المبتدإ."],["كون جملة خبرها جملة اسمية وأخرى خبرها جملة فعلية.","العلم فوائده كثيرة، والخبر جملة اسمية. العالم يخدم وطنه، والخبر جملة فعلية."]]},{"m":5,"w":3,"t":"الظاهرة اللغوية: الجملة الفعلية الواقعة خبرا للمبتدإ","pg":"ص 98","i":"✍️","B":[["القاعدة",["يرد الخبر جملة فعلية","يشترط فيها ضمير يربطها بالمبتدإ","الضمير يطابق المبتدأ في الجنس والعدد","تعرب الجملة الفعلية في محل رفع خبر"]],["أمثلة",["العلم يتصل بالعقل وحده","العلم يسير في تقدمه سيرا حتميا"]],["الرابط",["في الأمثلة هو الضمير المستتر في الفعل","فاعل يعود على المبتدإ تقديره هو"]],["الإعراب",["العلم مبتدأ مرفوع","يتصل فعل مضارع مرفوع والفاعل ضمير مستتر تقديره هو","الجملة الفعلية في محل رفع خبر"]],["أخطاء شائعة",["نسيان الضمير الرابط","عدم مطابقة الضمير للمبتدإ في الجنس والعدد"]]],"K":"إذا كان الخبر جملة فعلية فلا بد من ضمير يعود على المبتدإ ويطابقه، والجملة في محل رفع خبر.","M":["أبحث عن الفعل بعد المبتدإ مباشرة","أذكر الضمير الرابط وأحدد ما يعود عليه","أقول في محل رفع لا مرفوعة","أطابق الضمير: المؤنث للمؤنثة والجمع للجمع"],"X":"عندما يأتي بعد المبتدإ فعل وفاعله فهذه الجملة كلها تكمل المعنى فتسمى خبرا. لكي ترتبط بالمبتدإ يجب أن يكون فيها ضمير يرجع إليه. فعندما نقول العلم يسير، الفاعل المستتر يعود على العلم.","EX":[["ميز الخبر الجملة الفعلية: الأنترنت أضاع على الناس زيارة بعضهم . الناس في حاجة إلى التواصل . الشبكة معقدة التكنولوجيا .","الجملة الأولى فقط خبرها جملة فعلية: أضاع على الناس زيارة بعضهم، والرابط الضمير المستتر العائد على الأنترنت. الثانية خبرها شبه جملة. الثالثة خبرها مفرد."],["كون جملتين خبرهما جملة فعلية وأعرب إحداهما.","العالم يخدم وطنه. التلميذ يحترم معلمه. الإعراب: العالم مبتدأ مرفوع. يخدم فعل مضارع مرفوع والفاعل ضمير مستتر تقديره هو. وطنه مفعول به منصوب والهاء مضاف إليه. والجملة الفعلية في محل رفع خبر."]]},{"m":5,"w":3,"t":"الظاهرة اللغوية: الجملة الاسمية الواقعة خبرا للمبتدإ","pg":"ص 104","i":"🧩","B":[["القاعدة",["المبتدأ يحتاج إلى خبر يتمم معناه","يأتي الخبر جملة اسمية أيضا","ترتبط بالمبتدإ الأول بضمير يعود عليه","تكون في محل رفع دائما"]],["البناء",["مبتدأ أول + مبتدأ ثان + خبر الثاني","الضمير في المبتدإ الثاني يعود على الأول"]],["مثال معرب",["العلم النافع طلبه واجب","العلم مبتدأ أول، النافع نعت","طلبه مبتدأ ثان وواجب خبره","جملة طلبه واجب خبر المبتدإ الأول في محل رفع"]],["الفرق بين الأنواع",["خبر مفرد كلمة واحدة","جملة فعلية تبدأ بفعل","جملة اسمية تبدأ باسم له خبر خاص"]],["أخطاء شائعة",["جعل النعت مبتدأ ثانيا","نسيان الضمير الرابط"]]],"K":"قد يكون خبر المبتدإ جملة اسمية فيها ضمير يعود عليه، وتكون في محل رفع خبر.","M":["أنتبه إلى اسمين متتاليين بعد المبتدإ","أعرب الجملة الصغرى أولا ثم أبين محلها","الضمير الرابط يعود على المبتدإ الأول","محل جملة الخبر دائما الرفع"],"X":"في بعض الجمل نجد مبتدأ ثم جملة اسمية كاملة بعده، مثل طالب العلم سعيه مشكور. هذه الجملة الصغيرة هي الخبر. وهي مرتبطة بالمبتدإ الأول بالضمير الهاء في سعيه.","EX":[["أعرب: طالب العلم سعيه مشكور.","طالب مبتدأ أول مرفوع وهو مضاف. العلم مضاف إليه مجرور. سعيه مبتدأ ثان مرفوع والهاء ضمير في محل جر مضاف إليه وهو الرابط. مشكور خبر المبتدإ الثاني مرفوع. جملة سعيه مشكور في محل رفع خبر المبتدإ الأول."],["ميز الخبر الجملة الاسمية: الأنترنت أضاع علينا وقتا . وسائل الاتصال منفعتها كبيرة . الشبكة قمة التكنولوجيا .","الأولى خبرها جملة فعلية. الثانية خبرها جملة منفعتها كبيرة اسمية في محل رفع. الثالثة خبرها مفرد هو قمة."],["كون جملتين خبرهما جملة اسمية.","العالم علمه ينفع الناس. التلميذ أخلاقه حسنة."]]},{"m":5,"w":4,"t":"الإنتاج الكتابي: اختيار النمط والموضوع وجمع الموارد","pg":"ص 93","i":"🔬","B":[["الهدف",["كتابة نص وثائقي أو علمي","اختيار نمط وتبرير الاختيار"]],["الأنماط المقترحة",["الحجاج","الوصف","السرد","التفسير","الحوار"]],["مواضيع مقترحة",["الأجهزة العلمية في ميدان الطب","الجزائر وإسهامها في الإشعاع العلمي","الاختراعات العلمية والتكنولوجيا الرقمية","العلم في خدمة البشرية والتحكم في التقنيات"]],["خصائص النص العلمي",["موضوعية وحياد","مصطلحات علمية ولغة الأرقام","تعبير مباشر ومنهج علمي في بناء الأفكار"]],["مؤشرات التفسير",["الشرح والتفصيل والأمثلة","الإجمال ثم التفصيل","جمل طويلة وروابط منطقية ولفظية","ترابط الأفكار وتسلسلها"]]],"K":"أختار النمط الأنسب للموضوع وأجمع موارد معرفية ثم أبني نصا علميا موضوعيا مليئا بالمؤشرات الصحيحة.","M":["أبرر اختيار النمط بقصدي من الكتابة","أحدد مصادري: كتب ومكتبة ومواقع الأنترنت","أحدد المجال الثقافي والجنس الأدبي لنصوص اطلعت عليها","أناقش اختياراتي مع زملائي"],"X":"قبل أن تكتب نصا علميا اختر موضوعا يهمك، ثم اختر نمطا مناسبا، وأفضله التفسير لأنه يشرح ويوضح. جمع المعلومات من مصادر موثوقة مهم جدا. واكتب بلغة محايدة وفيها مصطلحات علمية.","EX":[["اختر نمطا وموضوعا وبرر اختيارك.","الموضوع: الأجهزة العلمية في ميدان الطب. النمط التفسيري لأنني أريد شرح عمل هذه الأجهزة. أبرر الموضوع بأنه يمس صحة الناس ويظهر فضل العلم."],["اذكر مؤشرين للنمط التفسيري في نصك.","استعمال الأمثلة والتفاصيل. استعمال روابط منطقية مثل لأن وإذن."]]},{"m":5,"w":4,"t":"الإنتاج الكتابي: الكتابة على منوال سند وتقويم الإنتاج","pg":"ص 99، 105","i":"🖊️","B":[["تأمل السند",["أبحث في القاموس عن الكلمات الصعبة","أضع عنوانا مناسبا للسند","أحلل بنيته الفكرية","أستخرج مؤشرات النمط المختار","أستخرج المعلومات النافعة لموضوعي"]],["السند المقدم",["نص عن الأشعة السينية وفائدتها في الطب","تنفذ من الأنسجة اللينة وتظهر العظام","تستعمل في الكشف عن الإصابات الباطنية"]],["المخطط النموذجي",["المقدمة: التعريف بالموضوع وطرح تساؤل","العرض: صعوبات الماضي وإسهامات العلم في الطب والاتصال والتنقل","العرض: تحذير من استعمال العلم للدمار","الخاتمة: جواب عن تساؤل المقدمة"]],["شبكة التقويم",["الموارد المعرفية والمنهجية: العلم والأخلاق","النمط المستهدف مناسب","النمط الخادم مناسب","مؤشرات النمط صحيحة وكافية","نمو الفكرة وتطورها","المعجم والظواهر اللغوية صحيحة"]],["العمل الجماعي",["أناقش مشروعي مع زملائي","نعرض باسم الفوج ثم ننتقي أفضل ثلاثة مواضيع","ننشر أفضل موضوع في صفحة القسم"]]],"K":"أحلل السند ثم أكتب على منواله بمخطط من مقدمة وعرض وخاتمة، وأقوم إنتاجي بشبكة التقويم.","M":["أنقل شبكة التقويم إلى كراسي وأملأها بعد الكتابة","أحرص على المقدمة والعرض والخاتمة","أستعمل مؤشرات النمط المختار بوضوح","أراجع صحة المعجم والإعراب والتنسيق"],"X":"خذ نصا علميا قصيرا وافهمه جيدا: اعثر على أفكاره وكلماته الصعبة. ثم اكتب نصك أنت بالطريقة نفسها: مقدمة تطرح سؤالا، وعرض يشرح، وخاتمة تجيب. وفي النهاية قيم عملك بالجدول لتعرف ما أصبت فيه وما تصلحه.","EX":[["ضع مخططا لموضوع: أهمية العلم والتكنولوجيا في ترقية حياة الإنسان.","المقدمة: تعريف بالعلم ودوره وسؤال عن قدرته على ترقية الحياة. العرض: صعوبات الإنسان قديما ثم إسهامات العلم في الطب والاتصال والتنقل، وخطر سوء الاستعمال. الخاتمة: العلم نعمة إذا اقترن بالأخلاق."],["اكتب فقرة مقدمة في ثلاثة أسطر.","العلم والتكنولوجيا غيرا حياة الإنسان تغييرا كبيرا. فقد سهلا له العمل والتنقل والتواصل. فهل يستطيعان وحدهما ترقية الحياة الإنسانية؟"]]},{"m":5,"w":5,"t":"الإدماج: وضعية تقويم المقطع 5","pg":"ص 106","i":"🏁","B":[["الإنتاج الشفوي: السياق",["مناسبة يوم العلم","مقارنة بين اليابان والجزائر جغرافيا وبشريا واقتصاديا","الاعتماد على معطيات منظمات أممية"]],["الإنتاج الشفوي: التعليمة",["أعرض السبب الجوهري للفارق في مداخيل العملة الصعبة","أحث زملائي على العمل بما استنتجته"]],["الإنتاج الكتابي: السياق",["مدير المتوسطة أعجب بعرضك","يطلب تحويل الخطاب إلى مقالة لتنشر في مجلة تربوية"]],["الإنتاج الكتابي: التعليمة",["اثنا عشر سطرا على الأقل","أفسر أهمية العلم في تنمية الدول","أستشهد بنتائج مقارنتي بين اليابان والجزائر"]],["المنهج والنموذج",["مقدمة: يوم العلم والمقارنة","عرض: المعطيات ثم السبب ثم النتائج","خاتمة: دعوة إلى العمل","أقيم عملي بشبكة التقويم الذاتي"]]],"K":"أدمج ما تعلمته: أقارن بمعطيات صحيحة ثم أبرهن بأن العلم والمعرفة أساس تقدم الدول.","M":["أفهم السياق والتعليمة قبل الكتابة","أنظم عرضي: مقدمة وعرض وخاتمة","أستعمل نمطي التفسير والحجاج مع روابط منطقية","لا أنقل أرقاما من عندي، وأعتمد معطيات المنظمات","أكتب جملا خبرها جملة فعلية أو اسمية بإعراب سليم"],"X":"في هذه الوضعية تقارن بين بلدين لتفهم لماذا يختلف دخلهما. السبب الجوهري هو العلم والمعرفة والعناية بالإنسان. تتكلم أولا أمام زملائك وتشجعهم على العمل، ثم تكتب مقالة من اثني عشر سطرا على الأقل تشرح فيها أهمية العلم وتستشهد بالمقارنة.","EX":[["ضع مخططا للعرض الشفوي.","أبدأ بتحية زملائي وأذكر يوم العلم. أقارن بين اليابان والجزائر في الموقع والسكان والاقتصاد. أذكر السبب الجوهري للفارق وهو العلم والمعرفة. أختم بدعوة زملائي إلى الاجتهاد."],["اكتب مقدمة مقالة في أربعة أسطر.","يحتفل التلاميذ كل سنة بيوم العلم. وقد قارنت بين اليابان والجزائر لأفهم سبب الفرق بينهما. فما الدور الذي يؤديه العلم في تنمية الدول؟ هذا ما أبينه في هذه المقالة."]]},{"m":6,"w":1,"t":"فهم المنطوق: تلوث البيئة (الجزء الأول)","pg":"ص 108-109","i":"🎧","B":[["الموضوع",["خطاب علمي وثائقي عنوانه: تلوث البيئة","يعرض مظاهر التلوث ومخاطره على الإنسان والكائنات","ينتمي إلى المجال العلمي والبيئي"]],["الأفكار الأساسية",["تعدد مظاهر التلوث (هواء، ماء، ضوضاء...)","التلوث خطر على الصحة ومنه أمراض خطيرة كالسرطان","ضرورة البحث عن حلول تمنع تكراره"]],["بنية الجزء الأول",["قسم أول قصير (أقل من 80 كلمة): تعريف وتمهيد","قسم ثان أطول (180 إلى 200 كلمة): تفصيل أنواع التلوث","الاختلاف في الحجم سببه قصد المرسل: التمهيد يوجز والتفصيل يشرح"]],["النمط وفرضيته",["الفرضية الممكنة: النمط التفسيري","نقارنها بفرضيات الزملاء ونبين المشترك والمختلف","نتأكد منها بالقرائن بعد الاستماع مرة ثانية"]],["مؤشرات النمط التفسيري",["لغة بسيطة ومباشرة","تفصيل بعد الإجمال","شرح وتحليل وأمثلة وشواهد","وضوح الأفكار وموضوعيتها وتعليلها"]],["أسئلة الفهم",["تلخيص مظاهر الخطر وتحديد أخطرها مع التعليل","مناقشة آراء الزملاء حول أهم الأخطار","اقتراح حلول ووسائل تمنع عودة التلوث"]]],"K":"الخطاب العلمي الوثائقي يعتمد النمط التفسيري: لغة مباشرة، إجمال ثم تفصيل، شرح وأمثلة وموضوعية.","M":["اسمع الخطاب كاملا ثم دون فكرته العامة","حدد موضوعه ومجاله (علمي، سياسي، اجتماعي...)","ابن فرضية عن النمط ثم تحقق منها بالقرائن","علل كل جواب بمثال من الخطاب"],"X":"في هذا الخطاب يشرح المتحدث للمستمعين ما هو التلوث وما أنواعه وما أخطاره. لأنه يريد أن يفهمنا المعلومات لا أن يقنعنا بالقوة، يستعمل كلاما بسيطا وأمثلة وأرقاما. هذه علامات النمط التفسيري.","EX":[["ما الفرق بين قسمي الجزء الأول من حيث الحجم وما سببه؟","القسم الأول أقل من 80 كلمة والثاني بين 180 و200. الأول تمهيد موجز للموضوع. الثاني تفصيل لأنواع التلوث وأمثلتها. الجواب: الثاني أكبر لأن قصد المرسل هو الشرح والتفصيل."],["كيف تتأكد أن الخطاب تفسيري وليس حجاجيا؟","نبحث عن القرائن: هل يعرض معلومات وحقائق؟ نعم. هل يشرح ويمثل؟ نعم. هل يحاول إقناعنا برأي مخالف؟ لا. الجواب: النمط تفسيري لأن اللغة مباشرة والتفصيل بعد الإجمال."]]},{"m":6,"w":1,"t":"فهم المنطوق: بنية الخطاب وأنماطه (الجزء الثاني)","pg":"ص 114-115 و120-121","i":"🔊","B":[["الجزء الثاني",["يتناول أضرار التلوث ومنها الاحتباس الحراري","فكرة رئيسة تتفرع إلى عناصر فكرية متعددة","نحدد النمط ومؤشراته في كل عنصر"]],["المقارنة بين الجزأين",["الجزء الأول: هيكلة فكرية ونمط معينان","الجزء الثاني: نقارن هيكلته ونمطه بالأول","نسجل أوجه التطابق والاختلاف في جدول"]],["العلاقة بين الأنماط",["قد يتضمن الخطاب الواحد أكثر من نمط","نمط غالب ونمط مساعد يخدمه","نعلل بالمؤشرات الموجودة في كل جزء"]],["المخطط الفكري للتلوث",["تعريفه","أنواعه: هواء، ماء، تربة، ضوضاء، ضوء، حرارة","أضراره: أمراض، موت كائنات، تدمير أشجار"]],["التحقق من النمط",["مقاطع مثل تعريف تلوث الهواء بمواده الضارة تدل على الشرح","قياس الضوضاء بالديسيبل معلومة علمية دقيقة","ذكر أسباب موت الكائنات تعليل وتحليل"]],["الإنتاج الشفوي",["عرض ملخص تفسيري عن نظافة المؤسسة","لغة مباشرة وإجمال ثم تفصيل","أمثلة من الواقع المدرسي"]]],"K":"نحلل الخطاب بتحديد الفكرة الرئيسة وعناصرها ونمط كل جزء، ثم نقارن الجزأين ونعلل النمط الغالب.","M":["اكتب الفكرة الرئيسة ثم عناصرها","اربط كل عنصر بمؤشر يدل على النمط","قارن الجزأين في جدول: هيكلة، نمط، مؤشرات","النمط الغالب هو ما تتكرر مؤشراته أكثر"],"X":"الخطاب مثل بناء له أجزاء. في كل جزء فكرة كبيرة تنقسم إلى أفكار صغيرة. نقارن الجزأين لنرى هل بنيا بالطريقة نفسها وهل استعملا النمط نفسه. وقد نجد نمطين يتعاونان في خطاب واحد.","EX":[["أعد بناء الهيكلة الفكرية لموضوع تلوث البيئة اعتمادا على مخططه.","الفكرة العامة: تلوث البيئة. العنصر الأول: تعريفه. العنصر الثاني: أنواعه، وهي تلوث الهواء والماء والتربة والضوضاء والضوء والحرارة. العنصر الثالث: أضراره، وهي انتشار الأمراض وموت الكائنات وتدمير الأشجار."],["حدد نمط المقطع: «وتقاس شدة الضوضاء بوحدة الديسيبل».","نلاحظ أنه يعطي معلومة علمية دقيقة. فيه مصطلح علمي هو الديسيبل. لا يعبر عن رأي ولا يأمر. الجواب: النمط تفسيري، والمؤشر هو المصطلح العلمي والدقة."]]},{"m":6,"w":2,"t":"فهم المكتوب: هو في عقر دارنا!","pg":"ص 110-112","i":"📖","B":[["التعريف",["العنوان: هو في عقر دارنا!","المصدر: مجلة العربي (مجلة شهرية ثقافية كويتية مصورة)","الموضوع: وصول التلوث إلى البلاد العربية"]],["الفكرة العامة",["كنا نظن التلوث مشكلة الدول الصناعية فقط","تبين أنه يهدد الإنسان العربي في بيته وبيئته","علينا أن نبني بلادا نظيفة وصحية بدل إهمال الخطر"]],["الأفكار حسب الفقرات",["الإنسان العربي يتنفس ويشرب كغيره فيتضرر من هواء وماء ملوثين","تلوث البحار بالنفط والنشادر يقتل الأسماك","المصانع والسيارات والمحارق مصادر أخرى للتلوث","الضوضاء من الآلات والطائرات وآلات التنبيه خطر أيضا"]],["المفردات",["إجراء حاسم: قرار نهائي وفعال","تكرير النفط: تصفيته وفرز أنواعه","القطران: مادة سوداء لزجة تستخرج من مواد عضوية","مكننت: أدخلت فيها الآلة"]],["القيم",["الوعي بالمسؤولية المشتركة","حب الوطن والحفاظ على البيئة","الاهتمام بالصحة العامة"]],["نمط النص وانسجامه",["النمط تفسيري: حقائق وأرقام وأمثلة (لندن 1952)","الكلمات المفتاحية: التلوث، الهواء، الماء، البيئة، الضوضاء","تكرارها يحقق الاتساق ويدل على الموضوع"]]],"K":"نص تفسيري يبين أن التلوث خطر عالمي وصل إلى بلادنا، فعلينا أن نبني بيئة نظيفة بدل الإهمال.","M":["الكلمات المفتاحية تتكرر وتعطي فكرة عن الموضوع","ابحث عن مؤشرات النمط: أرقام، أمثلة، تفصيل","اقرن العنوان بقصد الكاتب: التنبيه إلى قرب الخطر","اشرح الكلمة الصعبة من السياق أو من القاموس"],"X":"يقول كاتب المقال إننا ظننا أن التلوث بعيد عنا لكنه صار في بيوتنا. يشرح مصادره من مصانع وسيارات ونفط وضوضاء، ويذكر أمثلة وأرقاما ليقنعنا بأن الخطر حقيقي. ثم ينصحنا ببناء بلاد نظيفة.","EX":[["لماذا اختار الكاتب عنوان «هو في عقر دارنا»؟","العقر هو وسط الدار. الكاتب يقصد أن التلوث ليس بعيدا. أراد تنبيه القارئ العربي إلى الخطر. الجواب: العنوان يعبر عن قرب الخطر منا."],["ما الكلمات المفتاحية في النص؟ وماذا تفيد؟","نبحث عن الكلمات الأكثر تكرارا. نجد: التلوث، الهواء، الماء، الضوضاء. الجواب: هي تعطي فكرة مجملة عن الموضوع وتحقق اتساق النص وانسجامه."]]},{"m":6,"w":2,"t":"فهم المكتوب: التوازن البيئي ومكافحة التلوث","pg":"ص 116-118","i":"🌳","B":[["التعريف",["العنوان: التوازن البيئي ومكافحة التلوث","المصدر: مجلة الجيش، وزارة الدفاع الوطني، الجزائر، عدد 640 سنة 2016","الموضوع: التصحر وحماية البيئة"]],["الفكرة العامة",["حماية البيئة مسؤولية الجميع لا الدولة وحدها","الجزائر تحارب التصحر بالتشجير والسد الأخضر","الحل الأعمق هو تغيير نظرة الإنسان إلى بيئته"]],["الأفكار حسب الفقرات",["للمواطنين والمؤسسات دور رئيس والجزائر تحيي اليوم العالمي للبيئة","التصحر يضيع أراضي صالحة للزراعة ويكلف خسائر مالية","أزمة بيئة العالم الصناعي تلوث وفي العالم النامي إتلاف التربة","الجزائر عالجت الأسباب المصطنعة ثم واجهت زحف الرمال بالسد الأخضر"]],["المفردات",["التصحر: تحول الأرض إلى صحراء","الأسباب المصطنعة: ما يفتعله الإنسان","الأساليب التقليدية: طرق قديمة موروثة","لا جدوى: لا فائدة"]],["القيم",["المسؤولية الجماعية","حب الأرض والتشجير","تحدي الشباب وروح المبادرة"]],["النمط والانسجام",["النمط تفسيري، وأهم مؤشراته التفصيل","وجود أرقام ونسب وأسباب ونتائج","الروابط مثل: كما أن، يضاف إلى ذلك، فضلا عن"]]],"K":"حماية البيئة مسؤولية الجميع، وأعمق حل هو تغيير علاقة الإنسان بالطبيعة وليس فقط مقاومة الآفات.","M":["الفقرة التفسيرية تعتمد التفصيل: معلومة ثم أرقام ثم أمثلة","الروابط تربط الجمل: للإضافة، للتعليل، للنتيجة","استخرج المؤشرات الثلاثة: تفصيل، أرقام، لغة مباشرة","اقرن ما فعلته الجزائر بما تعرفه من واقعك"],"X":"النص يقول إن التصحر يأكل الأراضي ويضر الاقتصاد، وإن الجزائر بدأت بإصلاح ما أفسده الإنسان بالتشجير ثم واجهت زحف الرمال. وخلاصته أن الإنسان هو السبب وهو الحل، فلا فائدة إن لم يتغير سلوكه.","EX":[["من المسؤول عن حماية البيئة حسب النص؟","نقرأ الفقرة الأولى. يقول الكاتب إن المكافحة ليست مهمة الدولة وحدها. للمواطنين والمؤسسات الاقتصادية والثقافية دور رئيس. الجواب: الجميع مسؤولون."],["ما العلاقة بين الأفكار في الفقرة التفسيرية؟ مثل بالروابط.","الفقرة تعرض معلومة ثم تضيف أخرى. مثلا: يضاف إلى ذلك موجات الجفاف، وكما أن سبعة بالمائة من الأراضي متضررة. الجواب: روابط الإضافة تحقق الترابط بين الجمل."]]},{"m":6,"w":2,"t":"فهم المكتوب: مظاهر تلوث البيئة (قصيدة)","pg":"ص 122-123","i":"📜","B":[["التعريف",["العنوان: مظاهر تلوث البيئة","الشاعر: الدكتور معتز علي القطب (فلسطيني، أستاذ علوم الأرض والبيئة)","القصيدة من 13 بيتا"]],["الفكرة العامة",["الشاعر يتألم من فساد الأرض والبحر بالتلوث","يصف ظاهرة الاحتباس الحراري وضياع الفصول","يدعو الجميع إلى الإنقاذ والعمل"]],["العناصر الفكرية",["البيت 1: ظهور الفساد في البر والبحر","الأبيات 2 إلى 9: مظاهر التلوث وأخطاره","الأبيات 10 إلى 13: دعوة إلى الإنقاذ والعمل"]],["المفردات",["العلل: الأضرار","الخلل: النقائص","معتقل: حبيس","الرئات: شبه بها الغابات"]],["النمط",["تفسيري في وصف الظواهر وأسبابها","توجيهي في أبيات الدعوة مثل: تعال ننقذ ما يحيا بتربتها","الأسئلة البلاغية تؤكد الحسرة على ما فقدناه"]],["الاتساق",["ضمير الجماعة (نا) يتكرر في القصيدة","يجمع الشاعر نفسه بالقراء في المسؤولية","يمنح النص تناسقا وإحكاما"]]],"K":"القصيدة تجمع بين العلم والأخلاق: تشرح مظاهر التلوث ثم تدعو الناس جميعا إلى إنقاذ الأرض.","M":["قسم القصيدة إلى مقاطع حسب الفكرة","ميز بين التفسير (يشرح) والتوجيه (يأمر وينصح)","الضمير المتكرر يحقق الانسجام","ابحث عن معاني الكلمات في القاموس"],"X":"الشاعر عالم وشاعر معا. يقول إن الأرض تفسد، والحرارة ترتفع، والفصول تضطرب، والغابات والمرجان تتضرر. ثم يناديك أنت وغيرك لتنقذوا الأرض معا. فالقصيدة قضية علمية وأخلاقية في آن.","EX":[["ما النمط في الشطر: أين الفصول التي كنا نعدها؟ وما وظيفته؟","الشطر سؤال يتحسر على ضياع الفصول. يذكر ظاهرة ويشرح أثرها. الجواب: النمط تفسيري، ووظيفته إبراز تغير المناخ."],["ما النمط في الشطر: تعال ننقذ ما يحيا بتربتها؟","فيه دعوة وطلب للعمل. فعل الأمر تعال والفعل ننقذ يدلان على النصح. الجواب: النمط توجيهي، ووظيفته حث القارئ على الإنقاذ."]]},{"m":6,"w":3,"t":"الظاهرة اللغوية: المضاف إليه وأنواعه","pg":"ص 112","i":"✏️","B":[["تعريف المضاف إليه",["اسم مجرور ينسب إلى اسم قبله","الاسم الذي قبله يسمى المضاف","مثال: «داخل دارنا»"]],["النوع الأول: مفرد",["اسم ظاهر مثل: دار","أو ضمير متصل مثل: نا في «دارنا»","يكون مجرورا بالإضافة"]],["النوع الثاني: جملة فعلية",["تأتي بعد ظرف زمان مثل: حين، إذ، لما","مثال: «حين اشتد تلوث الهواء»","تعرب في محل جر مضاف إليه"]],["النوع الثالث: جملة اسمية",["تأتي بعد ظرف مثل: إذ، حيث، مذ","وتعرب كذلك في محل جر مضاف إليه","مثال: «إذ التلوث منتشر» جملة اسمية"]],["الكلمات المضافة",["داخل، حين، مذ، منذ، يوم، حيث","بعضها ظروف تضاف إلى جملة","وبعضها أسماء تضاف إلى مفرد"]],["أخطاء شائعة",["نسيان جر المضاف إليه","اعتبار الجملة بعد الظرف جملة مستقلة","الخلط بين الإضافة والصفة"]]],"K":"المضاف إليه اسم مجرور بعد المضاف، وهو ثلاثة أنواع: مفرد (اسم ظاهر أو ضمير)، جملة فعلية، جملة اسمية.","M":["اسأل: ما الكلمة التي تنسب إلى الاسم قبلها؟","المضاف إليه مجرور دائما، والجملة تكون في محل جر","الجملة بعد حين وإذ ومنذ مضاف إليه","اذكر النوع: مفرد أو جملة فعلية أو جملة اسمية"],"X":"عندما تقول «دار الجيران» فكلمة الجيران نسبت الدار إليهم، لذلك هي مضاف إليه. وأحيانا يأتي بعد الظرف كلام كامل، كجملة فعلية أو اسمية، فتأخذ حكم الاسم المجرور وتكون في محل جر.","EX":[["عين المضاف والمضاف إليه ونوعه: «منذ أن وقعت حادثة تشارنوبيل».","المضاف: منذ. المضاف إليه: جملة «وقعت حادثة تشارنوبيل» بعد منذ أن. الجواب: المضاف إليه جملة فعلية في محل جر."],["ألف جملتين لنوعين من المضاف إليه.","الأولى: «يلوث الدخان هواء المدينة» فالمضاف إليه المدينة اسم ظاهر. الثانية: «انتشرت الأمراض حين ازداد التلوث» فالمضاف إليه جملة فعلية. الجواب: مفرد وجملة فعلية."]]},{"m":6,"w":3,"t":"الظاهرة اللغوية: الجملة الفعلية الواقعة مضافا إليه","pg":"ص 118","i":"🧩","B":[["بعد ظروف الزمان والمكان",["إذ، حيث، إذا، لما، مذ، منذ، يوم","تضاف إلى جملة فعلية","مثال: «حيث وجد التلوث»"]],["بعد أن",["تأتي أن بعد: قبل، بعد، منذ، مذ","وبعد المفعول لأجله مثل: مخافة أن","مثال: «قبل أن تتفاقم أخطارها»"]],["بعد ما",["تأتي ما بعد: قبل، بعد","مثال: «بعد ما تفشى خطر التلوث»","ما هنا حرف يصل الظرف بالجملة"]],["إعرابها",["الجملة الفعلية في محل جر مضاف إليه","الظرف هو المضاف وله إعرابه حسب موقعه في الجملة","مثل: حين ظرف زمان منصوب"]],["وظيفتها الدلالية",["تحدد الزمان أو المكان أو السبب","تربط حدثين","تكمل معنى الظرف"]],["أخطاء شائعة",["إعراب الجملة مبتدأ أو فعلا مستقلا","نسيان العلاقة بين الظرف والجملة","نسيان أن تأتي «أن» أو «ما» بعد «قبل» و«بعد» عند الحاجة"]]],"K":"تقع الجملة الفعلية مضافا إليه بعد ظروف مثل إذ وحين ومنذ، أو بعد قبل وبعد مع أن وما، وتعرب في محل جر.","M":["اسأل: هل سبقت الجملة بظرف أو بمجموعة قبل أن؟","اعرب الظرف أولا ثم الجملة","قل: في محل جر مضاف إليه","اربط الجملة بما قبلها لتفهم وظيفتها"],"X":"بعض الكلمات مثل حين وإذا ومنذ لا تكتمل معانيها وحدها، فنضع بعدها جملة فعلية تكمل المعنى. هذه الجملة تأخذ إعراب المضاف إليه، ولأنها جملة نقول إنها في محل جر.","EX":[["استخرج الجملة الفعلية المضاف إليها: «حين غزا الجيش الأمريكي العراق».","الظرف حين مضاف. بعده جملة «غزا الجيش الأمريكي العراق». الجواب: الجملة الفعلية «غزا الجيش الأمريكي العراق» في محل جر مضاف إليه."],["أعرب: «ماتت الأسماك حين اشتد التلوث».","حين: ظرف زمان منصوب وعلامة نصبه الفتحة متعلق بماتت وهو مضاف. اشتد: فعل ماض مبني على الفتح. التلوث: فاعل مرفوع. الجواب: جملة اشتد التلوث في محل جر مضاف إليه."],["كون جملة فيها قبل أن وجملة فيها بعد ما.","«نحمي الغابة قبل أن تتلف». «ننام بعد ما ننهي الدرس». الجواب: جملة تتلف وجملة ننهي الدرس فعليتان في محل جر مضاف إليه."]]},{"m":6,"w":3,"t":"الظاهرة اللغوية: الجملة الاسمية الواقعة مضافا إليه","pg":"ص 124","i":"🔗","B":[["متى تقع",["مباشرة بعد: إذ، حيث، إذا، لما، مذ، منذ، يوم","وبعد: حد، غير، سوى","تتكون من مبتدأ وخبر"]],["أمثلة",["«إذ التلوث منتشر في الماء»","«حيث التلوث طاغ»","«مذ أمره صار مدولا»"]],["إعرابها",["جملة اسمية في محل جر مضاف إليه","المبتدأ مرفوع والخبر مرفوع","الظرف قبلها مضاف"]],["مع أنّ",["قد يأتي بعد الظرف أو الكلمة حرف أن واسمها وخبرها","مثل: رغم أن، مع أن، غير أن، سوى أن","وتؤول بمصدر في محل جر"]],["وظيفتها الدلالية",["تبين زمان الحدث أو مكانه","تدل على حال ثابتة أو استمرار","تعطي معنى التعليل أو الاستدراك مع غير وسوى"]],["أخطاء شائعة",["الخلط بينها وبين الفعلية","نسيان رفع المبتدأ والخبر","عدم ذكر محل الجملة الإعرابي"]]],"K":"تقع الجملة الاسمية مضافا إليه مباشرة بعد ظروف الزمان والمكان وبعد حد وغير وسوى، وتعرب في محل جر.","M":["انظر ما بعد الظرف: اسم أم فعل؟","إن كان مبتدأ وخبرا فهي اسمية","أعرب المبتدأ والخبر ثم قل: في محل جر","غير وسوى وحد قد تضاف إلى جملة أو مصدر مؤول"],"X":"إذا جاء بعد الظرف اسم مرفوع ثم خبره، فالكلام جملة اسمية. مثل «حيث التلوث طاغ». هذه الجملة تعمل عمل الاسم المجرور فتكون في محل جر مضاف إليه، تماما كما رأينا في الجملة الفعلية.","EX":[["أعرب: «تموت الأسماك حيث التلوث طاغ».","حيث: ظرف مكان مبني على الضم في محل نصب مضاف. التلوث: مبتدأ مرفوع. طاغ: خبر مرفوع وعلامة رفعه ضمة مقدرة على الياء المحذوفة. الجواب: جملة التلوث طاغ في محل جر مضاف إليه."],["ركّب جملة اسمية بعد «حين».","حين الهواءُ نقيٌّ ينشرح الصدر. جملة «الهواء نقي» اسمية: الهواء مبتدأ مرفوع، ونقي خبر مرفوع. وهي في محل جر مضاف إليه بعد حين"],["كون جملة اسمية مضافا إليه.","«نكون في أمان إذ البيئة نظيفة». فالجملة «البيئة نظيفة» مبتدأ وخبر في محل جر مضاف إليه."]]},{"m":6,"w":4,"t":"الإنتاج الكتابي: وصف منظر بيئي","pg":"ص 113 و119","i":"✍️","B":[["اختيار النمط والموضوع",["نختار نمطا من: وصف، سرد، حوار، حجاج، تفسير","نبرر الاختيار","من المواضيع: النفايات الصناعية، الاحتباس الحراري، التسربات النووية"]],["هيكلة النص الوصفي",["ما الموضوع الموصوف؟","كيف هو؟","ما مكوناته؟","ما موقف الواصف منه؟"]],["طرق الوصف",["من مكان ثابت: من العام إلى التفصيلي","وأنا أقترب: من العام إلى الجزئيات","وأنا أبتعد: من التفصيل إلى العام"]],["مؤشرات النمط الوصفي",["جمل اسمية وجمل فعلية مضارعة","أوصاف وأحوال","كلمات تدل على المكان","صور بيانية"]],["النص النموذج",["مقطع لواسيني الأعرج من رواية سيدة المقام (2005)","يصف مدينة حزينة تتلوث وتفقد جمالها","نستخرج منه مؤشرات الوصف وموقف الكاتب"]],["ما نكتب",["نحاكي النص ونصف منظرا بيئيا","نوظف المؤشرات والمكتسبات اللغوية","نبرز موقفنا من المنظر"]]],"K":"النص الوصفي يقدم الموضوع ثم صفاته ومكوناته بجمل اسمية وأفعال مضارعة وأحوال وصور، ويبين موقف الكاتب.","M":["اختر مكانا بيئيا تعرفه جيدا","اتبع ترتيبا واحدا: عام إلى تفصيلي أو العكس","استعمل ظروف المكان والصور البيانية","اختم بموقفك وشعورك"],"X":"أن تصف منظرا يعني أن ترسمه بالكلمات. تبدأ بالمنظر عامة ثم تقترب من تفاصيله من ألوان وأماكن وأشياء. وتستعمل أوصافا وجملا اسمية وتشبيهات، ثم تقول رأيك: هل المنظر جميل أم حزين؟","EX":[["ضع مخططا لوصف شاطئ ملوث.","1. التقديم: شاطئ مدينتي المعروف. 2. المكونات: الرمال والموج والنفايات. 3. الصفات: الرمل أسود والماء عكر. 4. الموقف: حزن ودعوة لتنظيفه. الجواب: وصف من العام إلى التفصيلي."],["اكتب جملتين وصفيتين فيهما حال وصورة.","«يمتد الشاطئ حزينا كأنه ثوب متسخ». «تطفو النفايات على الماء كأنها جزر صغيرة». الجواب: حزينا حال، والتشبيه صورة بيانية."]]},{"m":6,"w":4,"t":"الإنتاج الكتابي: التدرب وشبكة تقويم الإنتاج","pg":"ص 125","i":"📝","B":[["المشروع",["نناقش مع الزملاء مشروعا لنص وصفي بيئي","ننتجه ثم نقيمه","وينشر باسم الفوج في شبكة القسم"]],["شبكة الضبط 1",["مناسبة المنتج لموضوع وصف المنظر البيئي","الاعتماد على منهجية وصف المنظر","توظيف مؤشرات النمط المناسب"]],["شبكة الضبط 2",["توظيف المكتسبات اللغوية السابقة","لغة سليمة ومعجم مناسب","توظيف صور توضيحية"]],["شبكة الضبط 3",["التعاون مع الرفاق والتجاوب معهم","الاستعانة بتوجيهات الأستاذ","تعديل المواقف أثناء المناقشة","استعمال وسائل الاتصال في البحث"]],["كيف نقيم",["لكل معيار حكم الفوج وتعليله","ثم التصديق أو التعديل","نعدل ما نحتاج إلى تعديله"]],["نماذج للوصف",["واحة في صحراء الجزائر","حديقة التجارب بالحامة","موضوعان مقترحان للتطبيق"]]],"K":"نقيم الإنتاج بشبكة معايير: الموضوع، المنهجية، المؤشرات، اللغة، الصور، والتعاون مع الفوج.","M":["اقرأ معايير الشبكة قبل الكتابة","اكتب ثم راجع كل معيار","علل حكمك على النص","عدل ما ينقصه ثم انشره"],"X":"قبل نشر نصك، تضع أمامك قائمة بالأسئلة: هل وصفت الموضوع المطلوب؟ هل استعملت الأوصاف والصور؟ هل لغتي سليمة؟ إن أجبت بنعم عن كل سؤال، فنصك جيد، وإلا فتعدله.","EX":[["قيم فقرة وصفية وفق معيار: توظيف مؤشرات النمط.","نبحث في الفقرة عن جمل اسمية وأفعال مضارعة وأحوال وكلمات مكان وصور. إن وجدناها فالمعيار متحقق. إن غابت الصور نقترح إضافة تشبيه. الجواب: متحقق جزئيا مع تعديل بإضافة صورة."]]},{"m":6,"w":5,"t":"الإدماج: وضعية تقويم المقطع 6","pg":"ص 126","i":"🎯","B":[["الإنتاج الشفوي: السياق",["رحلة إلى منتزه طبيعي وفرحة بلقاء الزملاء","ثم رؤية أكوام النفايات في المكان","تساؤل: كيف نقضي على هذه الظاهرة؟"]],["الإنتاج الشفوي: التعليمة",["تنظم مع فوجك ندوة عن نظافة البيئة","تعرض فيديو أو صورا عن تلوث النفايات المنزلية","تلقي خطابا عن المظاهر والأسباب والحلول ثم تفتح النقاش"]],["نموذج الخطاب الشفوي",["مقدمة تعرف التلوث بالنفايات","المظاهر ثم الأسباب","الحلول: فرز النفايات وإعادة التدوير والتوعية","خاتمة ودعوة للنقاش"]],["الإنتاج الكتابي: السياق",["معرض في المتوسطة بمناسبة يوم الشجرة","الأستاذ يكلفك بكتابة موضوع للافتات المعرض","فكرتك: أهمية التشجير للبيئة والصحة والاقتصاد"]],["الإنتاج الكتابي: التعليمة",["اعتمد مصادر ورقية ورقمية","حرر لافتة عن أهمية الشجرة والتشجير","ادعم النص بصور توضيحية"]],["التقويم الذاتي",["اختر شبكة من اقتراح الأستاذ","قارن نصك بالمعايير","عدل أخطاءك"]]],"K":"في الإدماج نوظف نمط الشرح والوصف واللغة المكتسبة في خطاب شفوي عن النفايات ولافتة كتابية عن أهمية الشجرة.","M":["اقرأ السياق ثم حدد المطلوب بدقة","ضع مخططا: مقدمة، عرض، خاتمة","وظف المضاف إليه (مفرد، جملة فعلية، اسمية)","راجع النص باستعمال شبكة التقويم"],"X":"في هذه الوضعية تطبق ما تعلمته: تتكلم أمام زملائك عن النفايات وحلولها، ثم تكتب لافتة عن فوائد الشجرة. استعمل لغة بسيطة وأمثلة، ورتب أفكارك، وراجع نصك في النهاية.","EX":[["ضع مخططا للافتة عن أهمية الشجرة.","1. عنوان جذاب. 2. فائدة بيئية: تنقي الهواء وتحمي التربة. 3. فائدة صحية: ظل وهواء نقي. 4. فائدة اقتصادية: ثمار وخشب. 5. دعوة إلى الغرس. الجواب: لافتة منظمة بصورة توضيحية."],["اكتب جملتين فيهما مضاف إليه جملة فعلية واسمية.","«نغرس الشجرة حين يحل الربيع» فجملة يحل الربيع فعلية في محل جر. «نرتاح إذ الظل وفير» فجملة الظل وفير اسمية في محل جر. الجواب: الجملتان صحيحتان."]]},{"m":7,"w":1,"t":"فهم المنطوق: معرض غرداية (السرد والوصف)","pg":"ص 128-129","i":"🎧","B":[["موضوع الخطاب",["رحلة إلى معرض غرداية للصناعة التقليدية","المعرض اقتصادي في مجاله وثقافي في قيمته","المدينة نفسها تبدو معرضا مفتوحا بألوانها"]],["الجزء الأول: السرد",["تنطلق السيارة بالراوي ثم يصل صباحا إلى غرداية","الأفعال ماضية والأحداث متتابعة","ترد أسماء أماكن وظروف زمان"]],["النمط المصاحب: الوصف",["يصف الواحة الخضراء والأزقة الضيقة والمحلات الكبيرة","مؤشراته: أفعال مضارعة ونعوت وجمل اسمية وظروف مكان","الجمل الاسمية تغلب على هذا الجزء"]],["العلاقة بين النمطين",["الفقرة الأولى سرد للسفر والثانية وصف للمناظر","الفقرة الثانية أطول لأن المشاهد هي المقصودة","السرد وسيلة والوصف هو الغاية"]],["محاور أسئلة الفهم",["طبيعة المعرض ومجاله الاقتصادي","تلخيص وصف الخطاب للمدينة بأسلوبك","المفاضلة بين البعد الاقتصادي والثقافي مع التعليل"]],["نشاط شخصي",["اذكر معرضا آخر تعرفه وصفه","بين أهميته للزوار وللاقتصاد"]]],"K":"في الخطاب سرد مؤشراته الأفعال الماضية وتتابع الأحداث وأسماء المكان وظروف الزمان، يصاحبه وصف مؤشراته الأفعال المضارعة والنعوت والجمل الاسمية وظروف المكان.","M":["الفعل الماضي مع تتابع الأحداث يدل على السرد","النعوت والجمل الاسمية والمضارع تدل على الوصف","اسأل: هل ينقل النص حدثا أم حالة؟","استمع مرة للمضمون ومرة لتحديد المؤشرات"],"X":"عندما يحكي الكاتب ما فعله خطوة بعد خطوة فهذا سرد، وعندما يصور لك شكل المكان وألوانه فهذا وصف. في هذا الخطاب بدأ بالسفر ثم توقف ليريك المدينة، فالسرد كان طريقا للوصف.","EX":[["صنف الجملة «انطلقت بنا السيارة» حسب نمطها","الفعل ماض. تنقل حدثا وقع. لا تصف حالة. النمط: سرد"],["ما نمط «أزقة ملتوية ضيقة إلى جانب المحلات التجارية»؟","لا فعل فيها بل نعوت (ملتوية، ضيقة). فيها ظرف مكان (إلى جانب). تصور مشهدا ثابتا. النمط: وصف"],["ماذا تنقل عبارة «تتزين غرداية للزائرين بمختلف الألوان»؟","الفعل مضارع. لا يروي حدثا منتهيا. تنقل حالا تتكرر وتصور المدينة. إذن هي حال أي وصف"]]},{"m":7,"w":1,"t":"فهم المنطوق: بناء خطاب معرض غرداية وأنماطه","pg":"ص 134-135 و140-141","i":"🎙️","B":[["الفقرة الأولى: وصف موضوعي",["الربيع موسم مناسب للسياحة لاعتدال طقسه","غرداية سوق كبيرة: شوارع مزدحمة ودكاكين مليئة بالحرف","حرف من كل الوطن: زرابي تلمسان وتطريز قسنطينة وخزف شرشال"]],["الفقرة الثانية: تفسير",["المعرض لا يبلغ مداه في سنة أو سنتين","التخطيط على المدى البعيد لا مغامرة فيه","الجزائر تتصدر الصناعة التقليدية ولزرابيها أكثر من عشرين نوعا"]],["وظيفة الوصف",["في الأولى وصف تأثري تعبيري يظهر الإعجاب","في الثانية عرض معلومات وتبرير وتعليل","الوصف أقوى مظهرا في الفقرة الأولى"]],["تدرج الخطاب",["الجزء 1: سرد ووصف لوضع المستمع في الجو","الجزء 2: وصف ثم تفسير لإبراز القيمة الوطنية والسياحية","الجزء 3: تفسير لإبراز القيمة العالمية للتراث غير المادي"]],["مؤشرات التفسير",["التعليل والاستشهاد، مثل شهادة أحد السياح","استفهام يبرز الإعجاب للتأثير في السامع لا لطلب جواب","يرتبط بالبناء الفكري للخطاب"]],["القصد والنمط الغالب",["الغالب هو التفسير والسرد والوصف خادمان له","الرسالة: العناية بالتراث الثقافي غير المادي لأنه هوية","للإنتاج الشفوي: حدد الموضوع والقصد والجمهور والمناسبة"]]],"K":"يمكن للكاتب أن يوظف عدة أنماط تتغير بتطور الأفكار ليصل إلى رسالته التواصلية، وفي هذا الخطاب يغلب التفسير ويخدمه السرد والوصف.","M":["أحص مؤشرات الوصف وارتب الأكثر تكرارا فالأقل","قارن الفقرتين: أيهما يعرض معلومات وأيهما يعبر عن الإعجاب","حدد النمط الغالب من قصد الكاتب أولا","في الخطاب الشفوي: تمهيد ثم دخول في الموضوع ثم استكمال ثم وصول للقصد"],"X":"الخطاب لا يستعمل نمطا واحدا. يبدأ بحكاية الرحلة، ثم يصف السوق، ثم يشرح لماذا يتميز التراث الجزائري. الغرض الأخير هو إقناعك بقيمة هذا التراث، لذلك يغلب التفسير.","EX":[["ما نمط عبارة: المعرض لا يبلغ مداه في سنة، فكل شيء مخطط على المدى البعيد؟","فيها حكم وسبب. تستعمل التعليل بالفاء. لا تروي حدثا ولا تصور شكلا. النمط: تفسير"],["حدد النمط الغالب والنمطين الخادمين في الخطاب","القصد إبراز قيمة التراث. الغالب: التفسير. الخادمان: السرد والوصف. لأنهما يمهدان للمعلومات والتعليل"]]},{"m":7,"w":2,"t":"فهم المكتوب: سجّاد أمي","pg":"ص 130-132","i":"🧶","B":[["التعريف بالنص",["الكاتب عبد الكريم بلجيلالي من كتاب عن بومهدي والفخار","بومهدي (1924-2006) فنان تشكيلي جزائري","نشر الكتاب سنة 2004 في الجزائر"]],["الفكرة العامة",["الفنان يتذكر طفولته وسجاد أمه بحياء وتأثر","السجادة جزء من عالمه وأصل إلهامه الفني"]],["أفكار النص",["الحديث عن الطفولة جرح لأنها كانت زمن حرب وجوع","السجاد والنسيج مصدر إلهامه وتأثيره في فنه","أمه تنسج بخيوط صوف طويلة ورسوم تختلف عن سجاد جبل عمور","العائلة تهدي كل فرد زربية، والحنبل غطاء يجمع الجميع"]],["مفردات",["الطلسم: لغز غامض","هدهدته: حركته برفق ليهدأ","الصوف الخام: الصوف في حالته الطبيعية الأولى"]],["القيم",["الوفاء للأم وللجذور","الحفاظ على التراث الحرفي","التضامن العائلي والبساطة"]],["النمط ومؤشراته",["يتنازع النص السرد والوصف والوصف هو الخادم لقصد الكاتب","مؤشرات الوصف: فعل مضارع ونعوت وجمل اسمية","الوصف يبرز جمال السجاد وفن الفنان"]]],"K":"النص يجمع السرد والوصف، والوصف هو الأقوى لأنه يحقق قصد الكاتب في إبراز جمال السجاد وقيمته المعنوية عند الفنان.","M":["اقرأ مرتين: الأولى للفكرة العامة والثانية لتحديد المؤشرات","لخص كل فقرة بفكرة واحدة","ميز بين القيمة المادية والمعنوية للسجادة","للاتساق: ابحث عن الكلمة المتكررة والضمائر وأدوات الربط"],"X":"في هذا النص يتذكر فنان كبير أمه وهي تنسج السجاد. السجادة عنده ليست قطعة قماش بل ذكرى وهوية. الكاتب يصف شكل السجاد ويحكي عادات العائلة ليظهر هذه القيمة.","EX":[["لماذا يتحفظ بومهدي في الحديث عن طفولته؟","كانت طفولته في فترة الاستعمار. عاش فيها الحرب والجوع. الحديث عنها يفتح جرحا قديما. الجواب: الحياء والألم"],["ما الذي يميز زربية أمه؟","كانت تنسج بخيوط صوف طويلة. رسومها خاصة بها. تختلف عن سجاد جبل عمور الأكثر دقة. الجواب: الطول والرسوم الخاصة"]]},{"m":7,"w":2,"t":"فهم المكتوب: آنية الفخّار","pg":"ص 136-137","i":"🏺","B":[["التعريف",["الكاتب عبد الحميد بن هدوقة (1925-1996)","المقطع من رواية «ريح الجنوب»","من أدباء الجزائر الروائيين والمسرحيين"]],["الفكرة العامة",["عجوز مريضة تهذي فتتخيل نفسها آنية فخار تنادي من يشتريها","مشهد يظهر تعلقها بحرفتها وعطف الطفل عليها"]],["أحداث المقطع",["الحمى تجعل رحمة ترى بيتها فرنا ملتهبا","ينزعج الطفل عبد القادر وينادي جدة رحمة","تستعيد وعيها وتبتسم وتطلب ماء","تعتذر عن الهذيان ثم تستسلم للحمى"]],["مفردات",["الرثارة: كثيرة الماء","ينفث: ينفخ","هذيان: كلام بلا وعي","أذعره: أخافه وأفزعه"]],["القيم والدلالات",["التعلق بالحرفة التقليدية حتى في المرض","الحنان بين الأجيال","معاناة الحرفيين وحاجة حرفهم إلى حماية"]],["النمط ومؤشراته",["النمط سرد: ضمير الغائب وأحداث متتابعة وأفعال ماضية","مكان الأحداث بيت العجوز وزمنها ليلة مرضها","عودة الطفل نقطة تحول في سير الأحداث","وصف معنوي ومادي لرحمة داخل السرد"]]],"K":"قصة قصيرة سردية يغلب فيها ضمير الغائب وتتحول فيها الأحداث بعودة الطفل، وتبين تعلق الحرفية رحمة بصناعتها حتى في هذيانها.","M":["السرد: شخصيات وزمان ومكان وأحداث وتحول","ميز الوصف الداخل في السرد: مادي ومعنوي","للاتساق: الضمائر والروابط المنطقية واللفظية","اربط جملة «أنا آنية الفخار» بمعاناة الصناع"],"X":"تمرض امرأة عجوز كانت تصنع الفخار فتهذي، وتتخيل نفسها آنية تباع. يخاف حفيدها ثم يهدأ عندما تعود إلى وعيها. القصة تعبر عن حب الحرفة وحاجتها إلى من يقدرها.","EX":[["ما النمط الغالب على المقطع؟ علل","فيه شخصيات وأحداث متتابعة. الأفعال ماضية وهناك مكان وزمان. نقطة التحول عودة الطفل. النمط: سرد"],["ما دلالة عبارة «أنا آنية الفخار؛ من يشتريني»؟","العجوز ترى نفسها آنية. تعرض نفسها للبيع. تدل على تعلقها بحرفتها وعلى كساد صناعتها. الجواب: ارتباط الحرفي بصنعته ومعاناته"]]},{"m":7,"w":2,"t":"فهم المكتوب: قصة الفخّار (قصيدة)","pg":"ص 142-143","i":"📜","B":[["التعريف",["الشاعر علي مويسات جزائري قاص وشاعر","أستاذ في قطاع التربية الوطنية","نشرت القصيدة في موقع منابر ثقافية سنة 2018"]],["الفكرة العامة",["الشاعر يتغنى بصانع الفخار ودكانه ويرى في الطين حياة وحكاية"]],["أقسام القصيدة",["الأول: دكان صغير فيه تحف تزين الجدار","الثاني: الصفيحة تدور كالإعصار والطين يروي قصة وأسطورة","الثالث: الطين يصير جرة جميلة والنقش على سطحها كالأسفار"]],["مفردات",["الأسطورة: قصة خرافية","الأسفار: الكتب","اللبيب: الحاذق صاحب العقل الراجح"]],["القيم",["تقدير الصانع والعمل الحرفي الإبداعي","الاعتزاز بالتراث","الحرفة عمل يدوي وفن معا"]],["النمط والاتساق",["اجتمعت مؤشرات الوصف: صفات ومضارع وجمل اسمية وتشبيه وأماكن","فيها مقطع سردي صغير","الاتساق: تكرار الكلمات ونهاية الفقرات بنغمة واحدة وتفعيلة متفاعلن","الانسجام: موضوع واحد وتطور منطقي ووحدة المشاعر"]]],"K":"قصيدة وصفية في صانع الفخار تحول الطين من مادة إلى كائن حي، وتتماسك بوحدة الموضوع والتكرار والجرس الموسيقي.","M":["حدد الحرفة والمكان والصانع في القصيدة","استخرج أمثلة لكل مؤشر وصفي","فرق بين الاتساق (الشكل) والانسجام (المعنى)","اقترح حلولا لإحياء الحرفة"],"X":"القصيدة تأخذنا إلى دكان صغير لصانع فخار. نرى الطين يدور ويصير جرة ثم يزين بالنقوش كأنه كتاب. الشاعر يريدنا أن نحترم هذه الحرفة ونحميها.","EX":[["أي حرفة يصف الشاعر؟ وماذا يجعل العمل فنيا؟","الحرفة صناعة الفخار. الصانع لا يعمل بيديه فقط. يحول الطين إلى جرة جميلة وينقشها. الإبداع في الشكل والنقش"],["اذكر قرينتي اتساق في القصيدة","تكرار الكلمة في بدايات الفقرات. وحدة الجرس الموسيقي بتفعيلة واحدة. هما قرينتا اتساق"]]},{"m":7,"w":3,"t":"الظاهرة اللغوية: الجملة الواقعة خبرا لكان وأخواتها","pg":"ص 132","i":"📘","B":[["القاعدة",["خبر كان وأخواتها اسم مفرد أو جملة فعلية أو جملة اسمية","الجملة الواقعة خبرا لها محل نصب"]],["الرابط",["تتضمن جملة الخبر ضميرا يعود على اسم الناسخ","يطابقه في النوع والعدد"]],["أمثلة",["«كانت أمي تنجز سجادا»: خبرها جملة فعلية","«كان إنتاج النساء جيدا»: خبرها مفرد","«كانت أمي سجادها ينجز»: خبرها جملة اسمية"]],["أخوات كان",["صار وأصبح وأمسى وبات","ظل وما زال وما دام"]],["طريقة التطبيق",["حدد الناسخ واسمه","ابحث عما بعده يتمم المعنى","إن كان يبدأ بفعل فهو جملة فعلية وإن بدأ باسم فاسمية"]],["أخطاء شائعة",["القول إن الجملة الخبرية مرفوعة وهي محلها نصب","نسيان الضمير الرابط","الخلط بين الناسخ وفعل الجملة الخبرية"]]],"K":"خبر كان وأخواتها قد يكون جملة فعلية أو اسمية في محل نصب، تحتوي ضميرا يعود على اسمها.","M":["الجملة الخبرية: محلها نصب دائما","ابحث عن الضمير الرابط","الجملة التي تبدأ بفعل فعلية، والتي تبدأ باسم اسمية","غير الناسخ في الجملة لتختبر فهمك"],"X":"كان وأخواتها تدخل على جملة اسمية فتنصب خبرها. أحيانا يكون الخبر كلمة واحدة وأحيانا جملة كاملة. في هذه الحالة يلزم ضمير يعود على اسم كان.","EX":[["ما نوع الخبر في «ما زالت بعض الحرف التقليدية تستقطب هواتها»؟","ما زال: ناسخ. بعض: اسمها. الجملة بعدها تبدأ بفعل. جملة «تستقطب هواتها» فعلية في محل نصب خبر ما زال. الرابط: ضمير مستتر يعود على بعض (أو الحرف)"],["أعرب خبر كان في «أصبحت الأم تنسج الصوف»","أصبحت: فعل ماض ناقص. التاء للتأنيث. الأم اسمها مرفوع. «تنسج الصوف»: جملة فعلية في محل نصب خبر أصبح. فاعل تنسج ضمير مستتر تقديره هي يعود على الأم"],["أعرب «كان الحرفي يداه ماهرتان»","كان: ناسخ. الحرفي: اسمها. يداه: مبتدأ مرفوع بالألف لأنه مثنى والهاء مضاف إليه. ماهرتان: خبر المبتدأ مرفوع بالألف. الجملة الاسمية في محل نصب خبر كان. الرابط: الهاء"]]},{"m":7,"w":3,"t":"الظاهرة اللغوية: الجملة الواقعة خبرا لإنّ وأخواتها","pg":"ص 138","i":"📗","B":[["القاعدة",["خبر إن وأخواتها جملة فعلية أو اسمية في محل رفع","قد يكون أيضا مفردا"]],["الرابط",["الجملة الخبرية فيها ضمير يعود على اسم إن","مطابق له في النوع والعدد"]],["أخوات إن",["أن وكأن ولكن","ليت ولعل"]],["أمثلة",["«إنها صاهرة»: الخبر مفرد","«إنها تصهرني»: الخبر جملة فعلية","«أن دارها صارت فرنا»: الخبر جملة فعلية"]],["طريقة التطبيق",["حدد الحرف واسمه المنصوب","اقرأ ما يكمل المعنى بعده","نوع الجملة بحسب أول كلمة: فعل أم اسم"]],["أخطاء شائعة",["نصب خبر إن مع أن محله رفع","الخلط بين كان وإن في الإعراب","نسيان الضمير الرابط"]]],"K":"خبر إن وأخواتها جملة فعلية أو اسمية في محل رفع، وفيها ضمير يعود على اسمها يطابقه.","M":["إن وأخواتها تنصب الاسم وترفع الخبر","الجملة الخبرية محلها رفع","اكتشف الضمير الرابط","جرب حرفا آخر من أخواتها لتتأكد"],"X":"إن وأخواتها حروف تدخل على الجملة الاسمية: يصبح المبتدأ اسمها منصوبا ويبقى الخبر مرفوعا. إذا جاء الخبر جملة كاملة فمحلها رفع وفيها ضمير يعود على الاسم.","EX":[["أعرب «إن الحرفي يصنع الجرة بيديه»","إن: حرف توكيد ينصب الاسم ويرفع الخبر. الحرفي: اسمها منصوب بالفتحة الظاهرة. «يصنع الجرة بيديه»: جملة فعلية في محل رفع خبر إن. الفاعل ضمير مستتر تقديره هو يعود على الحرفي"],["أعرب «لعل الفخار صنعته جميلة»","لعل: حرف ترج. الفخار: اسمها منصوب. صنعته: مبتدأ مرفوع والهاء مضاف إليه. جميلة: خبر مرفوع. الجملة الاسمية في محل رفع خبر لعل. الرابط: الهاء"],["ما نوع خبر «إن غرداية صارت أيقونة للحرف»؟","إن: حرف توكيد. غرداية: اسمها. الجملة بعدها تبدأ بفعل. «صارت أيقونة»: جملة فعلية في محل رفع خبر إن. الرابط: ضمير مستتر يعود على غرداية"]]},{"m":7,"w":3,"t":"الظاهرة اللغوية: خبر أفعال المقاربة والرجاء والشروع","pg":"ص 144","i":"📙","B":[["القاعدة",["خبرها جملة فعلية اسمها اسم ظاهر أو ضمير متصل","فعلها مضارع مقترن بضمير يعود على اسمها"]],["أنواع الأفعال",["المقاربة: كاد وأوشك وكرب","الرجاء: عسى وحرى واخلولق","الشروع: طفق وأخذ وجعل وشرع"]],["الاقتران بأن",["قد تقترن جملة الخبر بأن مع أفعال الرجاء والمقاربة","عسى تقترن بها غالبا وكاد لا تقترن غالبا","أفعال الشروع لا تقترن بأن"]],["أمثلة",["«كاد الطين يصير جرة»","«أوشك الطين أن يصير جرة»","«أخذ اللبيب يبصرها في تأمل»"]],["طريقة التطبيق",["حدد الفعل: مقاربة أم رجاء أم شروع","حدد اسمه وجملة خبره","أعرب الجملة في محل نصب"]],["أخطاء شائعة",["جعل الخبر اسما مفردا وهو جملة فعلية","إدخال أن على خبر أفعال الشروع","نسيان الضمير الرابط"]]],"K":"خبر أفعال المقاربة والرجاء والشروع جملة فعلية فعلها مضارع يتضمن ضميرا يعود على اسمها، وقد تقترن بأن مع المقاربة والرجاء.","M":["كل خبرها جملة فعلية مضارعة","محل جملة الخبر نصب","الشروع بلا أن","أن مع عسى وأوشك غالبا ومع كاد قليلا"],"X":"هذه الأفعال تدل على قرب حدوث الشيء أو الرجاء فيه أو بدء العمل به. وخبرها دائما فعل مضارع بعده فاعله ضمير يعود على اسمها.","EX":[["أعرب «كادت الصناعات التقليدية تكون النشاط الوحيد»","كادت: فعل ماض ناقص من أفعال المقاربة. الصناعات: اسمها مرفوع. «تكون النشاط الوحيد»: جملة فعلية في محل نصب خبر كاد. اسم تكون ضمير مستتر تقديره هي يعود على الصناعات"],["أعرب «أوشكت منطقة القبائل أن تصبح أيقونة»","أوشكت: فعل ماض ناقص من أفعال المقاربة. منطقة: اسمها مرفوع. أن تصبح: مضارع منصوب بأن مقترن بضمير مستتر يعود على منطقة. الجملة الفعلية في محل نصب خبر أوشك"],["أعرب «طفق الصانع ينقش الجرة»","طفق: فعل ماض ناقص من أفعال الشروع. الصانع: اسمه مرفوع. «ينقش الجرة»: جملة فعلية في محل نصب خبر طفق. لم تقترن بأن لأنه فعل شروع"]]},{"m":7,"w":4,"t":"الإنتاج الكتابي: وصف حرفي وحرفته","pg":"ص 133","i":"✍️","B":[["اختيار النمط والموضوع",["لنص وثائقي اختر نمطا وبرر اختيارك: وصف أو سرد أو تفسير أو حجاج أو حوار","الوصف مناسب لتقديم حرفة وحرفي"]],["مواضيع مقترحة",["صياغة الفضة والذهب وصناعة النسيج والزرابي","صناعة النحاس والجلود","النقش على الخشب والتحف الفنية والفخار"]],["وصف الحرفي",["أصفه ماديا (جسميا) ثم معنويا (نفسيا وسلوكيا)","أصفه من الأعلى إلى الأسفل","أصف نشاطه وحرفته وأعبر عن إعجابي"]],["مؤشرات الوصف",["جمل اسمية وجمل فعلية وأفعال مضارعة","أوصاف وأحوال","كلمات دالة على المكان وصور بيانية"]],["جمع المصادر",["المكتبة المنزلية أو الجوارية أو المدرسية","مواقع الأنترنت","صنف النصوص بحسب مجالها (الصناعة التقليدية) وجنسها (مقالة، قصة، خاطرة، ترجمة)"]],["خطوات العمل",["اختر الموضوع وعلل","اجمع المعلومات وصنفها","ناقش اختياراتك مع زملائك"]]],"K":"لكتابة وصف حرفي: اختر الموضوع والنمط، اجمع المعلومات، صف الحرفي ماديا ومعنويا ثم حرفته، وعبر عن إعجابك مستعملا مؤشرات الوصف.","M":["صف من الأعلى إلى الأسفل","ابدأ بالجسم ثم الطباع ثم العمل","استعمل النعوت والجمل الاسمية والمضارع","اختم بإبداء إعجابك"],"X":"قبل أن تكتب، اختر حرفة تحبها واجمع معلومات عنها من الكتب والأنترنت. ثم صف الحرفي كما تراه: شكله وأخلاقه وعمله. استعمل كلمات وصفية ودع القارئ يشعر بإعجابك.","EX":[["اختر موضوعا وبرر اختيارك","الموضوع: صناعة الفخار. السبب: حرفة قريبة من منطقتي وهي مهددة بالاندثار. أجمع معلومات من مكتبة المدرسة ومن الأنترنت"],["اكتب فقرة قصيرة تصف حرفيا (3 جمل)","الحرفي رجل متوسط القامة، ملامحه هادئة ويداه خشنتان. يجلس أمام العجلة ويشكل الطين بدقة. أعجبني صبره وإتقانه"]]},{"m":7,"w":4,"t":"الإنتاج الكتابي: وصف منظر والشبكة الذاتية للتقويم","pg":"ص 139 و145","i":"📝","B":[["النص النموذج",["الطاهر وطار، «الشمعة والدهاليز» (2013)","شخصية تفتح حقيبة قديمة وتخرج برنسا صوفيا أبيض","ثم يرقص بالبرنس ويتذكر مدرسته في قسنطينة"]],["طرق وصف منظر بيئي",["من مكان ثابت: وصف عام ثم تفصيل الجزئيات","أثناء الاقتراب: من العام إلى التفصيلي","أثناء الابتعاد: من التفصيلي إلى العام"]],["هيكل النص الوصفي",["ما موضوع الوصف؟","كيف هو؟ وما مكوناته؟","ما تقييمي له وإعجابي به؟"]],["مهمتي",["أرصد خصائص الوصف ومؤشراته وموقف الكاتب من الموصوف","أحضر نصا وصفيا يحاكي النموذج موظفا المؤشرات"]],["شبكة التقويم (بنودها)",["ضبط تصوراتي حول الموصوف وصفاته","اعتماد منهجية الوصف وتوظيف مؤشرات النمط","استثمار المكتسبات السابقة وغة سليمة ومعجم مناسب"]],["العمل الجماعي",["تعاون مع الزملاء والاستفادة من توجيهات الأستاذ","تعديل المواقف أثناء النقاش","الاستعانة بالأنترنت وبصور توضيحية، ثم النشر باسم الفوج"]]],"K":"النص الوصفي ينطلق من موضوع واضح ويعرض مكوناته بترتيب (عام ثم تفصيلي أو العكس) ويختم بتقييم الواصف، ويقوّم الإنتاج بشبكة ذاتية.","M":["اختر طريقة الوصف قبل الكتابة","التزم بالترتيب: عام إلى خاص أو العكس","ضع موقفك وإعجابك في الخاتمة","راجع نصك بالشبكة: نعم أم لا"],"X":"اختر منظرا من محيطك ثم قرر: هل تصفه وأنت ثابت، أم وأنت تقترب أم تبتعد؟ اكتب موضوعه ثم أجزاءه ثم رأيك فيه. بعد ذلك راجع نصك ببنود الشبكة لتعرف ما ينقصه.","EX":[["ما أسئلة هيكلة النص الوصفي؟","ما موضوع الوصف. كيف هو. ما مكوناته. ما مدى تثميني له. هذا هو الهيكل"],["ضع خطة لوصف سوق شعبي من مكان ثابت","المقدمة: السوق في الصباح (وصف عام). الوسط: الأروقة والباعة والسلع (تفصيل). الخاتمة: أثره في نفسي وإعجابي. أستعمل نعوتا وجملا اسمية"]]},{"m":7,"w":5,"t":"الإدماج: وضعية تقويم المقطع 7","pg":"ص 146","i":"🏆","B":[["السياق الشفوي",["قسمكم اقترح معرضا للصناعات التقليدية في المتوسطة","الأستاذ يجمعكم لاقتراح برنامج عمل للتحضير","تحديد المهام: الإنجاز والتحضير المادي واللوجستي والتنظيمي"]],["المطلوب الشفوي",["وضع رزنامة للإنجاز التحضيري والتنظيمي","توزيع المهام على أفواج القسم","شرح الصور المعروضة والتعريف بالصناعات التقليدية لزوار المعرض"]],["السياق الكتابي",["صديقة جزائرية مغتربة تريد صورة عن المنتجات الحرفية قبل زيارتها","جمعت معلومات من مصادر ورقية ورقمية","صنفتها ورتبتها"]],["المطلوب الكتابي",["لخص المعلومات في مطوية كالتي تقدمها الوكالات السياحية","أرسلها إلى المراسلة"]],["منهجية الإنجاز",["حدد القصد والجمهور","رتب الأفكار ووظف الوصف والتفسير","استعمل لغة سليمة وصورا توضيحية"]],["التقويم الذاتي",["اختر شبكة من الشبكات التي يقترحها الأستاذ","قوم ما أنجزته وعدل نقاط الضعف"]]],"K":"في وضعية الإدماج تنظم عملا جماعيا شفويا حول معرض الصناعات التقليدية وتنتج كتابيا مطوية تعرف بالحرف الجزائرية، ثم تقوم عملك بشبكة ذاتية.","M":["نظم الأفكار في عناوين قصيرة","وظف مؤشرات الوصف والتفسير","وزع الأدوار بوضوح في العمل الشفوي","راجع بالشبكة قبل التسليم"],"X":"المطلوب أن تتكلم عن معرض الصناعات التقليدية وتشرح صوره، ثم تكتب مطوية قصيرة منظمة بعناوين تعرف بالحرف الجزائرية. تذكر أن تستعمل الوصف والتفسير وأن تقوّم نفسك.","EX":[["اقترح مهام وتقسيما لأفواج القسم لتحضير المعرض","فوج الإنجاز: اختيار الحرف والمعروضات. فوج التحضير: القاعة والطاولات واللافتات. فوج التنظيم: الدعوات والزوار والبرنامج. الرزنامة: أسبوعان للتحضير ويوم للمعرض"],["ضع مخططا لمطوية عن الصناعات التقليدية الجزائرية","العنوان: كنوز الحرف الجزائرية. الصفحة 1: تقديم الصناعة التقليدية وأهميتها. الصفحة 2: حرف: الزرابي والفخار والحلي (وصف قصير). الصفحة 3: أماكنها وأوقات الزيارة. الخاتمة: دعوة للزيارة"]]}];
ZAD_EOF
cat > lessons_4am.js <<'ZAD_EOF'
/* دروس اللغة العربية - الرابعة متوسط (المقاطع 1-7). يُحمَّل بعد lessons.js و ar4_data.js */
(function(){
  if(typeof LESSONS_DB==='undefined'||typeof AR4_DATA==='undefined')return;
  var KEY='__KEY__';
  function text(c){
    var t=[];
    c.B.forEach(function(b){t.push('▸ '+b[0]);b[1].forEach(function(x){t.push('• '+x)})});
    t.push('▸ للحفظ');t.push('• '+c.K);
    t.push('▸ طرق وقواعد');c.M.forEach(function(x){t.push('• '+x)});
    t.push('▸ شرح مبسط');t.push('• '+c.X);
    t.push('▸ تمارين محلولة');
    c.EX.forEach(function(e,j){t.push('• تمرين '+(j+1)+': '+e[0]);t.push('• الحل: '+e[1])});
    t.push('▸ المرجع');t.push('• كتاب اللغة العربية للسنة الرابعة متوسط (الشهاب 2019) '+c.pg+' — ملخص بتصرف');
    return t.join('\n');
  }
  var L=AR4_DATA.map(function(c){return {title:'م'+c.m+' · '+c.t,content:text(c)}});
  var A=LESSONS_DB['4AM']=LESSONS_DB['4AM']||{};
  var o=A[KEY]||{};
  o.name=o.name||'اللغة العربية';
  o.lessons=(o.lessons||[]).concat(L);
  o.maps='ar4';
  A[KEY]=o;
})();
ZAD_EOF
