# --- اكتشاف مفتاح مادة العربية للرابعة متوسط في db.js ---
LV=$(tr -d '\n' < db.js | sed 's/"name": *"السنة/\n&/g' | grep 'السنة الرابعة متوسط' | head -1)
KEY=$(printf '%s' "$LV" | grep -o '"key": *"[^"]*", *"name": *"اللغة العربية[^"]*"' | head -1 | sed 's/"key": *"\([^"]*\)".*/\1/')
if [ -z "$KEY" ]; then
  KEY=$(printf '%s' "$LV" | grep -o '"name": *"اللغة العربية[^"]*", *"key": *"[^"]*"' | head -1 | sed 's/.*"key": *"\([^"]*\)".*/\1/')
fi
if [ -z "$KEY" ]; then
  printf '%s' "$LV" | head -c 3000 > ~/storage/downloads/ar4_diag.txt
  echo "لم أجد مادة اللغة العربية للرابعة متوسط في db.js. كتبتُ تشخيصا في التنزيلات: ar4_diag.txt - أرسله لي."
  echo "لم يُربط شيء بالتطبيق بعد (الملفات الجديدة فقط في www)."
  exit 1
fi
echo "مفتاح المادة: $KEY"
sed -i "s/__KEY__/$KEY/" lessons_4am.js

# --- ربط الملفات في index.html (مرة واحدة فقط) ---
if ! grep -q 'lessons_4am.js' index.html; then
  LN=$(grep -n '<script src="lessons' index.html | tail -1 | cut -d: -f1)
  if [ -n "$LN" ]; then
    sed -i "${LN}a <script src=\"ar4_data.js\"></script>\n<script src=\"lessons_4am.js\"></script>" index.html
  else
    echo "تنبيه: لم أجد وسوم lessons في index.html"
  fi
fi
if ! grep -q 'maps_4am_hook.js' index.html; then
  sed -i '/maps_hg_hook.js/a <script src="maps_4am_hook.js"></script>' index.html
fi

echo "---- تحقق ----"
ls -l ar4_data.js lessons_4am.js maps_ar4.html maps_4am_hook.js
grep -n 'ar4_data.js\|lessons_4am.js\|maps_4am_hook.js' index.html
echo "تم. نسخة احتياطية: index.html.bak_ar4"
